cat > poison_testbed/aggregators.py <<'__CPC_DP_EOF__'
"""ClipNoise and ScheduledAggregator, following the library's stateless classmethod convention."""

import math
from collections.abc import Sequence
from typing import Any

import torch
from torch import Tensor

from krum.primitives.aggregators import Aggregator


class ClipNoise(Aggregator):
    r"""Clip each worker gradient to L2 norm ``C``, average, add Gaussian noise.

    Noise is :math:`\mathcal{N}(0, (\sigma C)^2 / n)` per coordinate, i.e. std
    :math:`\sigma C / \sqrt{n}` (as specified; note DP-SGD's averaged convention
    would be :math:`\sigma C / n`).
    """

    @classmethod
    def aggregate(
        cls,
        gradients: Sequence[Tensor] | Tensor,
        /,
        out: Tensor | None = None,
        *,
        C: float,
        sigma: float,
        noise: Tensor | None = None,
        generator: torch.Generator | None = None,
        **specialized: Any,
    ) -> Tensor:
        """Aggregate.

        Args:
            gradients: (n, d) worker gradients.
            out: Optional output buffer of shape (d,).
            C: Clipping threshold (L2).
            sigma: Noise multiplier.
            noise: Optional pre-drawn standard-normal tensor of shape (d,). Lets the
                caller draw noise every round from its own stream (common random
                numbers across schedules). If ``None``, drawn from ``generator``.
            generator: RNG used when ``noise`` is None.
        """
        if C <= 0:
            raise ValueError(f"Expected C > 0, got {C!r}")
        if sigma < 0:
            raise ValueError(f"Expected sigma >= 0, got {sigma!r}")
        g = gradients if isinstance(gradients, Tensor) else torch.stack(list(gradients))
        n = g.shape[0]
        norms = g.norm(dim=1, keepdim=True)
        scale = torch.clamp(C / norms.clamp_min(1e-12), max=1.0)
        agg = (g * scale).mean(dim=0)
        if sigma > 0:
            if noise is None:
                noise = torch.randn(agg.shape, generator=generator, device=agg.device, dtype=agg.dtype)
            agg = agg + noise * (sigma * C / math.sqrt(n))
        if out is not None:
            out.copy_(agg)
            return out
        return agg


class ScheduledAggregator(Aggregator):
    """Dispatch to ``plain`` or ``defense`` by block: ``schedule[round // block_len]``.

    Stateless: the caller passes the current ``round``. ``n``/``f`` (and any extra
    kwargs) go to both rules; ``plain_kwargs``/``defense_kwargs`` to one each.
    """

    @classmethod
    def aggregate(
        cls,
        gradients: Sequence[Tensor] | Tensor,
        /,
        out: Tensor | None = None,
        *,
        round: int,
        plain: type[Aggregator],
        defense: type[Aggregator],
        schedule: Sequence[int],
        block_len: int,
        plain_kwargs: dict[str, Any] | None = None,
        defense_kwargs: dict[str, Any] | None = None,
        **specialized: Any,
    ) -> Tensor:
        block = round // block_len
        if not 0 <= block < len(schedule):
            raise ValueError(f"round {round} is outside the schedule ({len(schedule)} blocks of {block_len})")
        if schedule[block]:
            return defense.aggregate(gradients, out, **specialized, **(defense_kwargs or {}))
        return plain.aggregate(gradients, out, **specialized, **(plain_kwargs or {}))

    @staticmethod
    def active(round: int, schedule: Sequence[int], block_len: int) -> int:
        return int(schedule[round // block_len])
__CPC_DP_EOF__
cat > poison_testbed/alarm.py <<'__CPC_DP_EOF__'
"""Alarm-driven defense schedules (xp6): the defense reacts to an OBSERVABLE alarm, never to the true attack window.

Why (xp5a): schedules that switch the defense on at the true window start ('react', 'probehold') make a planned
W = 1 announce an attack, and an outcome model fed with the planned W learns 'W = 1 -> high attack success'. Here
W depends only on what a defender sees (the signals and its own past W), as at deployment.

Alarm score of a block = max of two z-scores, each against no-attack training blocks of the same defense, defense
state W and 25-block time bin: x_norm_std (v1) and x2_outlier_proj_max_max (v2). The z tables are the xp5 alarm
(deploy_xp5.fit_alarm on xp5 training runs, file alarm_xp5.json), fixed before any xp6 run.

Schedule "alarm_t<tau>_d<delay>_h<hold>":
    an alarm is a block with score > tau; the defense switches on `delay` blocks after an alarm seen while off,
    then stays on until `hold` consecutive blocks without an alarm (at least `hold` blocks).
"""

import json
import math
import random
import re
from functools import lru_cache
from pathlib import Path
from typing import Any

ALARM_FILE = Path(__file__).with_name("alarm_xp5.json")
ALARM_SCHEDULE = re.compile(r"alarm_t([0-9.]+)_d(\d+)_h(\d+)")
GAMMA_SCHEDULE = re.compile(r"gamma_g([0-9.]+)_c([0-9.]+)_p(\d+)")
V1, V2, BIN = "x_norm_std", "x2_outlier_proj_max_max", 25


@lru_cache(maxsize=None)
def load_alarm(path: str = str(ALARM_FILE)) -> dict:
    """{'table': {'<defense>|<W>|<bin>': [mean_v1, sd_v1, mean_v2, sd_v2]}, 'threshold': float}."""
    return json.loads(Path(path).read_text())


def score(row: dict[str, Any], table: dict) -> float:
    """Alarm score of one observed block row (-inf when it cannot be scored: init row, missing signal or bin)."""
    if row.get("block", -1) < 0:
        return -math.inf
    w = row.get("W")
    if w is None or (isinstance(w, float) and math.isnan(w)):
        return -math.inf
    stats = table.get(f"{row['defense']}|{int(w)}|{int(row['block']) // BIN}")
    v1, v2 = row.get(V1), row.get(V2)
    if stats is None or v1 is None or v2 is None or not (math.isfinite(v1) and math.isfinite(v2)):
        return -math.inf
    m1, s1, m2, s2 = stats
    return max((v1 - m1) / max(s1, 1e-9), (v2 - m2) / max(s2, 1e-9))


class AlarmSchedule:
    """Online policy(history, b) -> (W_b, extra) for simulate(); history = observable rows of blocks -1..b-1."""

    def __init__(self, tau: float, delay: int, hold: int, table: dict):
        self.tau, self.delay, self.hold, self.table = tau, delay, hold, table
        self.on, self.pending, self.quiet = False, None, 0

    def __call__(self, history: list[dict[str, Any]], b: int) -> tuple[int, dict[str, Any]]:
        hit = score(history[-1], self.table) > self.tau
        self.quiet = 0 if hit else self.quiet + 1
        if hit and not self.on and self.pending is None:
            self.pending = b + self.delay
        if self.pending is not None and b >= self.pending:
            self.on, self.pending, self.quiet = True, None, 0
        elif self.on and self.quiet >= self.hold:
            self.on = False
        return int(self.on), {}


class GammaSchedule:
    """xp7: stochastic alarm policy with a known propensity. Every `period` blocks (from block 0) the defense is
    redrawn: P(on) = sigmoid(gamma * (s - center)), s = the highest alarm score seen since the previous decision
    (-inf before any scored block). gamma = 0: a fair coin (no confounding); larger gamma: closer to a threshold
    rule on the alarm. W is held between decisions. Logged on every row: p_on (propensity of the current W's
    decision) and decision (1 on the block where it was drawn)."""

    def __init__(self, gamma: float, center: float, period: int, table: dict, seed: int):
        self.gamma, self.center, self.period, self.table = gamma, center, period, table
        self.rng = random.Random(seed)
        self.w, self.p, self.s = 0, 0.5, -math.inf

    def __call__(self, history: list[dict[str, Any]], b: int) -> tuple[int, dict[str, Any]]:
        self.s = max(self.s, score(history[-1], self.table))
        if b % self.period:
            return self.w, {"p_on": self.p, "decision": 0}
        z = self.gamma * (self.s - self.center) if self.gamma > 0 else 0.0
        self.p = 1.0 / (1.0 + math.exp(-z)) if z > -700 else 0.0
        self.w, self.s = int(self.rng.random() < self.p), -math.inf
        return self.w, {"p_on": self.p, "decision": 1}


def is_alarm_schedule(schedule: str) -> bool:
    """Schedules decided online by a policy (alarm or gamma)."""
    return ALARM_SCHEDULE.fullmatch(schedule) is not None or GAMMA_SCHEDULE.fullmatch(schedule) is not None


def alarm_policy(schedule: str, seed: int = 0):
    if m := ALARM_SCHEDULE.fullmatch(schedule):
        return AlarmSchedule(float(m.group(1)), int(m.group(2)), int(m.group(3)), load_alarm()["table"])
    if m := GAMMA_SCHEDULE.fullmatch(schedule):
        return GammaSchedule(float(m.group(1)), float(m.group(2)), int(m.group(3)), load_alarm()["table"], seed)
    raise ValueError(f"not an online schedule: {schedule!r}")
__CPC_DP_EOF__
cat > poison_testbed/data.py <<'__CPC_DP_EOF__'
"""MNIST as preloaded, normalised tensors, plus a clean val split and a triggered test set."""

from dataclasses import dataclass
from functools import lru_cache
from pathlib import Path

import torch
from torch.utils.data import TensorDataset
from torchvision import datasets

MEAN, STD = 0.1307, 0.3081
DATA_ROOT = Path(__file__).resolve().parent.parent / "data"
VAL_SIZE = 5_000
SPLIT_SEED = 0  # fixed: the train/val split is identical in every run


@dataclass(frozen=True)
class Mnist:
    train: TensorDataset  # 55k, on CPU; sampled by the workers' DataLoaders
    val: tuple[torch.Tensor, torch.Tensor]  # 5k clean held-out
    test: tuple[torch.Tensor, torch.Tensor]  # 10k
    triggered: tuple[torch.Tensor, torch.Tensor]  # test images with true label != target, patched; y = true label


def _tensors(train: bool) -> tuple[torch.Tensor, torch.Tensor]:
    ds = datasets.MNIST(str(DATA_ROOT), train=train, download=True)
    x = (ds.data.float().div(255.0).sub(MEAN).div(STD)).unsqueeze(1)  # (N,1,28,28)
    return x, ds.targets.clone().long()


def patch_value() -> float:
    """Normalised value of a white pixel."""
    return (1.0 - MEAN) / STD


def apply_patch(x: torch.Tensor, size: int) -> torch.Tensor:
    """Return a copy of ``x`` (B,1,28,28) with a white ``size``×``size`` square in the bottom-right corner."""
    x = x.clone()
    x[..., -size - 1 : -1, -size - 1 : -1] = patch_value()
    return x


@lru_cache(maxsize=4)
def load_mnist(device: str, patch_size: int, target: int) -> Mnist:
    x, y = _tensors(train=True)
    perm = torch.randperm(len(y), generator=torch.Generator().manual_seed(SPLIT_SEED))
    val_idx, train_idx = perm[:VAL_SIZE], perm[VAL_SIZE:]
    xt, yt = _tensors(train=False)
    keep = yt != target
    dev = torch.device(device)
    return Mnist(
        train=TensorDataset(x[train_idx], y[train_idx]),
        val=(x[val_idx].to(dev), y[val_idx].to(dev)),
        test=(xt.to(dev), yt.to(dev)),
        triggered=(apply_patch(xt[keep], patch_size).to(dev), yt[keep].to(dev)),
    )


# ----------------------------------------------------------------------------- xp5: datasets and triggers
# Normalisation per dataset (train-set pixel mean / std). MNIST keeps the constants above, so load_mnist is unchanged.
NORM = {"mnist": (MEAN, STD), "fmnist": (0.2860, 0.3530)}
BLEND_ALPHA = 0.2


@dataclass(frozen=True)
class Data:
    train: TensorDataset
    val: tuple[torch.Tensor, torch.Tensor]
    test: tuple[torch.Tensor, torch.Tensor]
    triggered: tuple[torch.Tensor, torch.Tensor]  # test images with true label != target, with the run's trigger
    flip_source: tuple[torch.Tensor, torch.Tensor]  # test images of class flip_source (label flip success)
    flip_pool: torch.Tensor  # training images of class flip_source (CPU): what a label-flip attacker feeds in


def _tensors_of(dataset: str, train: bool) -> tuple[torch.Tensor, torch.Tensor]:
    cls = {"mnist": datasets.MNIST, "fmnist": datasets.FashionMNIST}[dataset]
    mean, std = NORM[dataset]
    ds = cls(str(DATA_ROOT), train=train, download=True)
    return (ds.data.float().div(255.0).sub(mean).div(std)).unsqueeze(1), ds.targets.clone().long()


def _checkerboard() -> torch.Tensor:
    """Fixed blend pattern in pixel space: 2x2-pixel checkerboard of 0 / 1, shape (28, 28)."""
    i = torch.arange(28)
    return (((i[:, None] // 2) + (i[None, :] // 2)) % 2).float()


def make_trigger(dataset: str, trigger: str, patch_size: int):
    """Return stamp(x) -> triggered copy of x (B,1,28,28), normalised with the dataset's statistics.

    "corner"           white patch_size x patch_size square, bottom-right (as in xp1-xp4)
    "patch_r{r}_c{c}"  the same white square with its top-left pixel at (r, c)
    "blend"            x_pixel -> (1 - BLEND_ALPHA) x_pixel + BLEND_ALPHA * checkerboard (whole image)
    """
    mean, std = NORM[dataset]
    white = (1.0 - mean) / std
    if trigger == "corner":
        def stamp(x):
            x = x.clone()
            x[..., -patch_size - 1: -1, -patch_size - 1: -1] = white
            return x
        return stamp
    if trigger.startswith("patch_r"):
        r, c = (int(v) for v in trigger[len("patch_r"):].split("_c"))

        def stamp(x):
            x = x.clone()
            x[..., r: r + patch_size, c: c + patch_size] = white
            return x
        return stamp
    if trigger == "blend":
        pattern = (_checkerboard() - mean) / std

        def stamp(x):
            return (1 - BLEND_ALPHA) * x + BLEND_ALPHA * pattern.to(x.device)
        return stamp
    raise ValueError(f"unknown trigger {trigger!r}")


@lru_cache(maxsize=8)
def load_data(dataset: str, device: str, trigger: str, patch_size: int, target: int, flip_source: int) -> Data:
    x, y = _tensors_of(dataset, train=True)
    perm = torch.randperm(len(y), generator=torch.Generator().manual_seed(SPLIT_SEED))
    val_idx, train_idx = perm[:VAL_SIZE], perm[VAL_SIZE:]
    xt, yt = _tensors_of(dataset, train=False)
    keep = yt != target
    src = yt == flip_source
    stamp = make_trigger(dataset, trigger, patch_size)
    dev = torch.device(device)
    return Data(
        train=TensorDataset(x[train_idx], y[train_idx]),
        val=(x[val_idx].to(dev), y[val_idx].to(dev)),
        test=(xt.to(dev), yt.to(dev)),
        triggered=(stamp(xt[keep]).to(dev), yt[keep].to(dev)),
        flip_source=(xt[src].to(dev), yt[src].to(dev)),
        flip_pool=x[train_idx][y[train_idx] == flip_source],
    )
__CPC_DP_EOF__
cat > poison_testbed/poisoning.py <<'__CPC_DP_EOF__'
"""Attack conditions: data-poisoning corruptions and library gradient attacks, with an optional block window.

A *data* attack makes the f Byzantine workers compute an honest gradient on a
corrupted copy of their micro-batch. A *gradient* attack replaces their gradient
by ``attack.generate(honest_gradients, f=f, ...)`` from the library. Outside the
window the Byzantine workers behave exactly like honest ones.
"""

from collections.abc import Callable
from dataclasses import dataclass, field
from typing import Any

import torch

from krum.primitives.attacks import Attack
from krum.primitives.attacks.alie import ALIEAttack
from krum.primitives.attacks.sign_flip import SignFlipAttack

from .data import apply_patch

Batch = tuple[torch.Tensor, torch.Tensor]


def _n_poisoned(batch_size: int, poison_frac: float) -> int:
    return int(round(poison_frac * batch_size))


def label_flip(x: torch.Tensor, y: torch.Tensor, *, poison_frac: float, num_classes: int = 10, **_: Any) -> Batch:
    """y -> (num_classes - 1 - y) on the first ``poison_frac`` of the micro-batch."""
    k = _n_poisoned(len(y), poison_frac)
    y = y.clone()
    y[:k] = num_classes - 1 - y[:k]
    return x, y


def backdoor(x: torch.Tensor, y: torch.Tensor, *, poison_frac: float, patch_size: int, target: int,
             stamp: Callable[[torch.Tensor], torch.Tensor] | None = None, **_: Any) -> Batch:
    """Stamp the trigger and set label ``target`` on the first ``poison_frac`` of the micro-batch.

    ``stamp`` (xp5) applies the run's trigger; None = the MNIST corner patch of xp1-xp4 (unchanged).
    """
    k = _n_poisoned(len(y), poison_frac)
    x, y = x.clone(), y.clone()
    x[:k] = apply_patch(x[:k], patch_size) if stamp is None else stamp(x[:k])
    y[:k] = target
    return x, y


def targeted_flip(x: torch.Tensor, y: torch.Tensor, *, poison_frac: float, target: int, flip_pool: torch.Tensor,
                  flip_gen: torch.Generator, **_: Any) -> Batch:
    """Targeted label flip: the first ``poison_frac`` of the micro-batch is replaced by training images of the
    source class (drawn from ``flip_pool`` with the attacker's own generator, so the honest data stream is
    unchanged), all labelled ``target``. The attacker controls the content of its micro-batch."""
    k = _n_poisoned(len(y), poison_frac)
    x, y = x.clone(), y.clone()
    idx = torch.randint(len(flip_pool), (k,), generator=flip_gen)
    x[:k] = flip_pool[idx].to(x.device)
    y[:k] = target
    return x, y


@dataclass(frozen=True)
class AttackSpec:
    name: str  # value of the `attack` / `u_type` columns
    kind: str  # "none" | "data" | "gradient"
    corrupt: Callable[..., Batch] | None = None
    attack_cls: type[Attack] | None = None
    attack_kwargs: dict[str, Any] = field(default_factory=dict)
    window: tuple[int, int] | None = None  # inclusive block range; None = always
    has_trigger: bool = False  # y_atk = backdoor success
    outcome: str = ""  # xp5: "backdoor" | "flip" | "none" (no targeted harm: y_atk masked); "" = has_trigger rule
    burst: tuple[int, int] | None = None  # (period, on): inside the window, active `on` blocks of every `period`

    def active(self, block: int) -> bool:
        if self.kind == "none":
            return False
        if self.window is not None and not self.window[0] <= block <= self.window[1]:
            return False
        if self.burst is not None:
            period, on = self.burst
            start = self.window[0] if self.window is not None else 0
            return (block - start) % period < on
        return True


def make_attack(name: str, *, sign_flip_scale: float = 1.0, alie_z: float | str = "max",
                window: tuple[int, int] = (15, 30), burst: tuple[int, int] | None = None) -> AttackSpec:
    """Build the named condition. Hyperparameters of the corruptions live in the run config.

    ``backdoor_burst``: the backdoor, active inside ``window`` only during bursts (``burst`` = (period, on)).
    """
    if name == "backdoor_burst":
        if burst is None:
            raise ValueError("backdoor_burst needs burst=(period, on)")
        return AttackSpec("backdoor_burst", "data", corrupt=backdoor, has_trigger=True, window=window, burst=burst)
    specs = {
        "none": AttackSpec("none", "none"),
        "label_flip": AttackSpec("label_flip", "data", corrupt=label_flip),
        "backdoor": AttackSpec("backdoor", "data", corrupt=backdoor, has_trigger=True),
        "backdoor_win": AttackSpec("backdoor_win", "data", corrupt=backdoor, has_trigger=True, window=window),
        "alie": AttackSpec("alie", "gradient", attack_cls=ALIEAttack, attack_kwargs={"z": alie_z}),
        # xp5: windowed targeted label flip and windowed ALIE
        "flip_win": AttackSpec("flip_win", "data", corrupt=targeted_flip, window=window, outcome="flip"),
        "alie_win": AttackSpec("alie_win", "gradient", attack_cls=ALIEAttack, attack_kwargs={"z": alie_z},
                               window=window, outcome="none"),
        # xp7: windowed sign flip (no targeted harm: its harm is in y_clean_acc, like alie_win)
        "sign_flip_win": AttackSpec("sign_flip_win", "gradient", attack_cls=SignFlipAttack,
                                    attack_kwargs={"scale": sign_flip_scale}, window=window, outcome="none"),
        "sign_flip": AttackSpec("sign_flip", "gradient", attack_cls=SignFlipAttack,
                                attack_kwargs={"scale": sign_flip_scale}),
    }
    if name not in specs:
        raise ValueError(f"Unknown attack {name!r}; expected one of {sorted(specs)}")
    return specs[name]
__CPC_DP_EOF__
cat > poison_testbed/runner.py <<'__CPC_DP_EOF__'
"""One run = one (attack, defense, seed, schedule): train, log one row per block, write CSV + JSON."""

import hashlib
import json
import math
import re
import subprocess
import time
from dataclasses import asdict, dataclass, field, replace
from pathlib import Path
from typing import Any, Callable

import numpy as np
import pandas as pd
import torch

import krum
from krum.primitives.aggregators import Aggregator
from krum.primitives.aggregators.average import Average
from krum.primitives.aggregators.bulyan import Bulyan
from krum.primitives.aggregators.krum import Krum
from krum.primitives.aggregators.median import Median
from krum.primitives.aggregators.multikrum import MultiKrum
from krum.primitives.aggregators.trimmed_mean import TrimmedMean
from krum.primitives.models.mlp import Krum2017MLPMnist

from .aggregators import ClipNoise
from .alarm import alarm_policy, is_alarm_schedule
from .data import load_data, load_mnist, make_trigger
from .poisoning import make_attack
from .signals import X2_COLUMNS, X_COLUMNS
from .simulation import PoisoningSimulation

# Bump when a code change should invalidate cached runs.
TESTBED_VERSION = 1
REPO_DIR = Path(__file__).resolve().parent.parent / "krum"

DEFENSES: dict[str, type[Aggregator]] = {
    "Average": Average,
    "ClipNoise": ClipNoise,
    "Krum": Krum,
    "MultiKrum": MultiKrum,
    "Median": Median,
    "TrimmedMean": TrimmedMean,
    "Bulyan": Bulyan,
}

COLUMNS = [
    "run_id", "seed", "schedule_seed", "defense", "attack", "poison_frac", "n", "f",
    "block", "round_start", "lr", "W",
    *X_COLUMNS, "x_val_acc",
    "y_clean_acc", "y_clean_loss", "y_atk",
    "u_active", "u_type",
]


@dataclass(frozen=True)
class RunConfig:
    attack: str
    defense: str
    seed: int
    C: float
    sigma: float
    # "random" | "on" | "off" | "policy" | "cf_<on|off|ontil20|offtil20|alt>_p<prefix>"
    # | "sticky_p<switch prob>" | "react_d<delay>_e<extra>" (blocks, relative to `window`)
    # | "alarm_t<tau>_d<delay>_h<hold>" (xp6: online, reacts to the observable alarm; see alarm.py)
    schedule: str = "random"
    schedule_seed: int | None = None  # default: 1000 + seed
    n: int = 16
    f: int = 3
    batch_size: int = 8  # micro-batch size; mini-batch = n * batch_size
    lr: float = 0.1
    block_len: int = 10
    n_blocks: int = 50
    poison_frac: float = 1.0
    patch_size: int = 4
    target: int = 0
    window: tuple[int, int] = (15, 30)
    sign_flip_scale: float = 1.0
    alie_z: float | str = "max"
    burst: tuple[int, int] | None = None  # backdoor_burst: (period, on) blocks inside the window
    # Measure backdoor success (y_atk) even without a trigger attack, e.g. in no-attack runs (xp3). It then
    # reads as the base rate (~1%), which teaches a model that without an attack the backdoor stays at 0.
    always_measure_backdoor: bool = False
    # Signal set: "v1" = the 7 X columns of xp1-xp3; "v2" adds the X2 columns (tail, scale-free, memory; xp4).
    # v2 changes no computation of the run itself: v1 columns, outcomes and training are identical.
    signals: str = "v1"
    # xp5 (defaults = xp1-xp4 behaviour): dataset, backdoor trigger, source class of the targeted label flip
    # (images of flip_source relabelled `target`), and extended logging (per-round signal values r0/r1 and both
    # targeted outcomes y_bd / y_flip in every run).
    dataset: str = "mnist"
    trigger: str = "corner"
    flip_source: int = 1
    extended_log: bool = False
    # xp7: non-iid workers. None = every worker samples the full training set (iid, xp1-xp6). A float = Dirichlet
    # concentration: each class's training images are split across the n workers with shares ~ Dir(alpha), fixed
    # per seed (smaller alpha = more skewed workers; Krum then discards honest but unusual gradients).
    noniid_alpha: float | None = None
    # xp8: number of Byzantine workers when it differs from f (Krum and the signals always assume f).
    n_attackers: int | None = None
    device: str = field(default_factory=lambda: "cuda" if torch.cuda.is_available() else "cpu")

    @property
    def sched_seed(self) -> int:
        return 1000 + self.seed if self.schedule_seed is None else self.schedule_seed

    @property
    def run_id(self) -> str:
        tag = "" if self.schedule == "random" else f"__{self.schedule}"
        return f"{self.attack}__{self.defense}{tag}__s{self.seed:03d}"

    def hash(self) -> str:
        fields = asdict(self)
        # Fields added after xp1/xp2: left out while at their default, so every earlier config's hash is unchanged.
        for name, default in LATER_FIELDS.items():
            if fields[name] == default:
                del fields[name]
        payload = json.dumps({**fields, "_v": TESTBED_VERSION}, sort_keys=True, default=str)
        return hashlib.sha256(payload.encode()).hexdigest()[:16]


LATER_FIELDS = {"burst": None, "always_measure_backdoor": False, "signals": "v1", "dataset": "mnist",
                "trigger": "corner", "flip_source": 1, "extended_log": False,
                "noniid_alpha": None, "n_attackers": None}


def is_legacy_data(cfg: "RunConfig") -> bool:
    """MNIST with the corner patch: the xp1-xp4 data path (load_mnist, apply_patch), kept bit-identical."""
    return cfg.dataset == "mnist" and cfg.trigger == "corner"


def load_run_data(cfg: "RunConfig"):
    if is_legacy_data(cfg) and not cfg.extended_log:
        return load_mnist(cfg.device, cfg.patch_size, cfg.target)
    return load_data(cfg.dataset, cfg.device, cfg.trigger, cfg.patch_size, cfg.target, cfg.flip_source)

CF_SCHEDULE = re.compile(r"cf_(on|off|ontil20|offtil20|alt)_p(\d+)")
PROBE_SCHEDULE = re.compile(r"probe_P(\d+)_L(\d+)_o(\d+)")
PROBEHOLD_SCHEDULE = re.compile(r"probehold_P(\d+)_L(\d+)_o(\d+)_d(-?\d+)_e(\d+)")
FLIP_SUFFIX = re.compile(r"(.+)\+flip_s(\d+)_l(\d+)")
STICKY_SCHEDULE = re.compile(r"sticky_p([0-9.]+)")
REACT_SCHEDULE = re.compile(r"react_d(-?\d+)_e(\d+)")


def counterfactual_schedule(name: str, prefix: int, n_blocks: int) -> list[int]:
    """Defended prefix of ``prefix`` blocks, then a candidate continuation.

    on: always on; off: always off; ontil20: on through block 19 then off;
    offtil20: off through block 19 then on; alt: alternate, starting off.
    """
    rest = range(prefix, n_blocks)
    cont = {
        "on": [1 for _ in rest],
        "off": [0 for _ in rest],
        "ontil20": [int(b < 20) for b in rest],
        "offtil20": [int(b >= 20) for b in rest],
        "alt": [int((b - prefix) % 2 == 1) for b in rest],
    }[name]
    return [1] * prefix + cont


def probe_schedule(period: int, length: int, offset: int, n_blocks: int) -> list[int]:
    """Short defenses to look: defend `length` blocks out of every `period`, starting at `offset`."""
    return [int((b - offset) % period < length) if b >= offset else 0 for b in range(n_blocks)]


def make_schedule(cfg: RunConfig) -> list[int]:
    if m := FLIP_SUFFIX.fullmatch(cfg.schedule):
        # Paired twin: the base schedule with W flipped on blocks [s, s + l). Same seed, so the pair gives the
        # true effect of that short change.
        if is_alarm_schedule(m.group(1)):
            raise ValueError("twins of alarm schedules are not defined (their W is decided online)")
        base = make_schedule(replace(cfg, schedule=m.group(1)))
        s, ln = int(m.group(2)), int(m.group(3))
        return [1 - w if s <= b < s + ln else w for b, w in enumerate(base)]
    if m := PROBE_SCHEDULE.fullmatch(cfg.schedule):
        return probe_schedule(int(m.group(1)), int(m.group(2)), int(m.group(3)), cfg.n_blocks)
    if m := PROBEHOLD_SCHEDULE.fullmatch(cfg.schedule):
        # Probe; from window start + d hold the defense on through window end + e; then probe again. Follows
        # cfg.window whether or not an attack happens (phantom window in no-attack runs).
        period, length, offset, d, e = (int(g) for g in m.groups())
        out = probe_schedule(period, length, offset, cfg.n_blocks)
        on, off = cfg.window[0] + d, cfg.window[1] + e
        return [1 if on <= b <= off else w for b, w in enumerate(out)]
    if cfg.schedule == "on":
        return [1] * cfg.n_blocks
    if cfg.schedule == "off":
        return [0] * cfg.n_blocks
    if cfg.schedule == "random":
        gen = torch.Generator().manual_seed(cfg.sched_seed)
        return torch.bernoulli(torch.full((cfg.n_blocks,), 0.5), generator=gen).int().tolist()
    if cfg.schedule == "policy" or is_alarm_schedule(cfg.schedule):
        return [0] * cfg.n_blocks  # placeholder: each entry is set online by the policy before its block runs
    if cfg.schedule == "oracle":
        # Defend exactly the blocks where the attack is active (knows the attack: an upper reference only).
        spec = make_attack(cfg.attack, window=cfg.window, burst=cfg.burst)
        return [int(spec.active(b)) for b in range(cfg.n_blocks)]
    if m := STICKY_SCHEDULE.fullmatch(cfg.schedule):
        # Two-state Markov chain: random initial state, switch with probability p before each block.
        gen = torch.Generator().manual_seed(cfg.sched_seed)
        p = float(m.group(1))
        state = int(torch.rand(1, generator=gen).item() < 0.5)
        out = []
        for _ in range(cfg.n_blocks):
            out.append(state)
            if torch.rand(1, generator=gen).item() < p:
                state = 1 - state
        return out
    if m := REACT_SCHEDULE.fullmatch(cfg.schedule):
        # Defend from window start + delay through window end + extra. Follows cfg.window whether or not an
        # attack happens (phantom window for no-attack runs), so W never reveals the attack by itself.
        delay, extra = int(m.group(1)), int(m.group(2))
        on, off = cfg.window[0] + delay, cfg.window[1] + extra
        return [int(on <= b <= off) for b in range(cfg.n_blocks)]
    if m := CF_SCHEDULE.fullmatch(cfg.schedule):
        return counterfactual_schedule(m.group(1), int(m.group(2)), cfg.n_blocks)
    raise ValueError(f"Unknown schedule {cfg.schedule!r}")


def worker_datasets(train: torch.utils.data.TensorDataset, cfg: RunConfig) -> list:
    """One training set per worker: the full set for every worker (iid), or a Dirichlet split by class (xp7)."""
    if cfg.noniid_alpha is None:
        return [train] * cfg.n
    x, y = train.tensors
    gen = torch.Generator().manual_seed(cfg.seed + NONIID_STREAM)
    conc = torch.full((cfg.n,), float(cfg.noniid_alpha))
    parts: list[list[torch.Tensor]] = [[] for _ in range(cfg.n)]
    for c in range(int(y.max()) + 1):
        idx = (y == c).nonzero().flatten()
        idx = idx[torch.randperm(len(idx), generator=gen)]
        share = _dirichlet(conc, gen)
        cuts = (share.cumsum(0) * len(idx)).round().long().tolist()
        for w, (a, b) in enumerate(zip([0] + cuts[:-1], cuts)):
            parts[w].append(idx[a:b])
    out = []
    for w in range(cfg.n):
        idx = torch.cat(parts[w])
        if len(idx) < cfg.batch_size:
            raise ValueError(f"worker {w} has {len(idx)} images (< batch {cfg.batch_size}); raise noniid_alpha")
        out.append(torch.utils.data.TensorDataset(x[idx], y[idx]))
    return out


def _dirichlet(conc: torch.Tensor, gen: torch.Generator) -> torch.Tensor:
    """Dirichlet draw from a seeded generator (torch.distributions has no generator argument)."""
    rng = np.random.default_rng(int(torch.randint(0, 2**31 - 1, (1,), generator=gen)))
    return torch.from_numpy(rng.dirichlet(conc.numpy())).float()


NONIID_STREAM = 50_000


def defense_kwargs(cfg: RunConfig) -> dict[str, Any]:
    return {"C": cfg.C, "sigma": cfg.sigma} if cfg.defense == "ClipNoise" else {}


def build(cfg: RunConfig) -> PoisoningSimulation:
    torch.use_deterministic_algorithms(True)
    data = load_run_data(cfg)
    spec = make_attack(cfg.attack, sign_flip_scale=cfg.sign_flip_scale, alie_z=cfg.alie_z, window=cfg.window,
                       burst=cfg.burst)
    sim = PoisoningSimulation(
        attack_spec=spec,
        corrupt_kwargs={"poison_frac": cfg.poison_frac, "patch_size": cfg.patch_size, "target": cfg.target,
                        **({"flip_pool": data.flip_pool, "flip_gen": torch.Generator().manual_seed(cfg.seed + 30_000)}
                           if cfg.attack == "flip_win" else {}),
                        **({} if is_legacy_data(cfg) else {"stamp": make_trigger(cfg.dataset, cfg.trigger, cfg.patch_size)})},
        plain=Average,
        defense=DEFENSES[cfg.defense],
        defense_kwargs=defense_kwargs(cfg),
        schedule=make_schedule(cfg),
        block_len=cfg.block_len,
        C_ref=cfg.C,
        signals_v2=cfg.signals == "v2",
        n_byz=cfg.n_attackers,
        model_cls=Krum2017MLPMnist,
        train_datasets=worker_datasets(data.train, cfg),
        test_set=torch.utils.data.TensorDataset(*data.test),
        n=cfg.n,
        f=cfg.f,
        rounds=cfg.block_len * cfg.n_blocks,
        batch_size=cfg.batch_size,
        lr=cfg.lr,
        device=torch.device(cfg.device),
        seed=cfg.seed,
    )
    sim.setup()
    return sim


def _outcomes(sim: PoisoningSimulation, cfg: RunConfig) -> dict[str, float]:
    data = load_run_data(cfg)
    val_acc, _ = sim.accuracy_loss(*data.val)
    acc, loss = sim.accuracy_loss(*data.test)
    spec = sim.attack_spec
    out = {"x_val_acc": val_acc, "y_clean_acc": acc, "y_clean_loss": loss}
    if spec.outcome == "flip":  # targeted label flip: share of flip_source test images predicted as the target
        out["y_atk"] = sim.target_rate(data.flip_source[0], cfg.target)
    elif spec.outcome == "none":  # no targeted harm (ALIE): masked; its harm is in y_clean_acc
        out["y_atk"] = math.nan
    else:  # xp1-xp4 rule: backdoor success when the attack has a trigger (or when asked, e.g. no-attack runs)
        measure = spec.has_trigger or cfg.always_measure_backdoor
        out["y_atk"] = sim.target_rate(data.triggered[0], cfg.target) if measure else math.nan
    if cfg.extended_log:  # both targeted outcomes in every run, whatever the attack
        out["y_bd"] = sim.target_rate(data.triggered[0], cfg.target)
        out["y_flip"] = sim.target_rate(data.flip_source[0], cfg.target)
    return out


HIDDEN_FROM_POLICY = ("y_", "u_", "attack")


def observable(row: dict[str, Any]) -> dict[str, Any]:
    """What a defender can see: drops outcomes (y_*), attack labels (u_*) and the attack name."""
    return {k: v for k, v in row.items() if not k.startswith(HIDDEN_FROM_POLICY)}


Policy = Callable[[list[dict[str, Any]], int], tuple[int, dict[str, Any]]]


def simulate(cfg: RunConfig, policy: Policy | None = None) -> pd.DataFrame:
    """Train one run and return its block table (no file I/O).

    ``policy(history, b) -> (W_b, extra)``, if given, decides W for block b before it runs. ``history`` holds the
    observable part of rows -1..b-1 only (see ``observable``). ``extra`` is logged on block b's row.
    """
    if policy is None and is_alarm_schedule(cfg.schedule):  # xp6: W decided online from the observable alarm
        policy = alarm_policy(cfg.schedule, cfg.sched_seed)
    sim = build(cfg)
    base = {"run_id": cfg.run_id, "seed": cfg.seed, "schedule_seed": cfg.sched_seed, "defense": cfg.defense,
            "attack": cfg.attack, "poison_frac": cfg.poison_frac, "n": cfg.n, "f": cfg.f}
    if cfg.extended_log:  # attack configuration as evaluation labels (u_: hidden from any policy)
        base.update({"u_trigger": cfg.trigger, "u_target": cfg.target, "u_flip_source": cfg.flip_source,
                     "u_burst": "" if cfg.burst is None else f"{cfg.burst[0]}_{cfg.burst[1]}"})
    rows = [{**base, "block": -1, "round_start": pd.NA, "lr": sim._current_lr, "W": pd.NA,
             **{c: math.nan for c in X_COLUMNS}, **_outcomes(sim, cfg), "u_active": 0, "u_type": "none"}]
    extra_cols: list[str] = []
    for b in range(cfg.n_blocks):
        extra: dict[str, Any] = {}
        if policy is not None:
            w, extra = policy([observable(r) for r in rows], b)
            sim.schedule[b] = int(w)
            extra_cols += [k for k in extra if k not in extra_cols]
        lr = sim._current_lr
        per_round = [sim.step() for _ in range(cfg.block_len)]
        x_block = {c: sum(r[c] for r in per_round) / len(per_round) for c in X_COLUMNS}
        if cfg.signals == "v2":  # block mean and block max of every v2 signal
            for c in per_round[0]:
                if c.startswith("x2_"):
                    x_block[f"{c}_mean"] = sum(r[c] for r in per_round) / len(per_round)
                    x_block[f"{c}_max"] = max(r[c] for r in per_round)
        if cfg.extended_log:  # the value of every signal in each round of the block
            for k, r in enumerate(per_round):
                for c, v in r.items():
                    x_block[f"{c}_r{k}"] = v
        active = sim.attack_spec.active(b)
        rows.append({**base, "block": b, "round_start": b * cfg.block_len, "lr": lr, "W": sim.schedule[b],
                     **x_block, **_outcomes(sim, cfg),
                     "u_active": int(active), "u_type": cfg.attack if active else "none", **extra})
    x2 = list(X2_COLUMNS) if cfg.signals == "v2" else []
    if cfg.extended_log:
        x2 += ["y_bd", "y_flip", "u_trigger", "u_target", "u_flip_source", "u_burst"]
        x2 += [c for c in rows[-1] if c[-3:-1] == "_r" and c.startswith("x")]
    df = pd.DataFrame(rows, columns=COLUMNS + x2 + extra_cols)
    return df.astype({"round_start": "Int64", "W": "Int64"})


def _git_commit() -> str | None:
    try:
        return subprocess.run(["git", "-C", str(REPO_DIR), "rev-parse", "HEAD"], capture_output=True,
                              text=True, check=True).stdout.strip()
    except Exception:
        return None


def run(cfg: RunConfig, out_root: Path) -> tuple[pd.DataFrame, dict[str, Any]]:
    """Run (or load if already done with the same config) and write runs/<run_id>/{blocks.csv,config.json}."""
    out = out_root / cfg.run_id
    csv, js = out / "blocks.csv", out / "config.json"
    if csv.exists() and js.exists():
        meta = json.loads(js.read_text())
        if meta.get("config_hash") == cfg.hash():
            return pd.read_csv(csv, dtype={"round_start": "Int64", "W": "Int64"}), meta
    started = time.time()
    df = simulate(cfg)
    wall = time.time() - started
    out.mkdir(parents=True, exist_ok=True)
    meta = {
        "run_id": cfg.run_id,
        "config_hash": cfg.hash(),
        "config": asdict(cfg),
        "schedule": ([int(w) for w in df.W.iloc[1:]] if is_alarm_schedule(cfg.schedule) else make_schedule(cfg)),
        "testbed_version": TESTBED_VERSION,
        "krum_version": krum.__version__,
        "krum_git_commit": _git_commit(),
        "torch_version": torch.__version__,
        "device_name": torch.cuda.get_device_name(0) if cfg.device == "cuda" else cfg.device,
        "wall_clock_s": round(wall, 2),
        "finished_at": time.strftime("%Y-%m-%dT%H:%M:%S"),
    }
    df.to_csv(csv, index=False)
    js.write_text(json.dumps(meta, indent=2, default=str))
    return df, meta
__CPC_DP_EOF__
cat > poison_testbed/signals.py <<'__CPC_DP_EOF__'
"""Observable signals X, computed from the received gradients only (before aggregation).

These functions take the (n, d) gradient stack, the losses of data-bearing
micro-batches and the fixed reference threshold C. They never see which workers
are Byzantine, nor whether an attack is active.
"""

import torch

from krum.primitives.aggregators.median import Median

X_COLUMNS = (
    "x_norm_mean",
    "x_norm_std",
    "x_pdist_mean",
    "x_maxdist_median",
    "x_cos_avg_median",
    "x_frac_clipped",
    "x_train_loss",
)


@torch.no_grad()
def round_signals(gradients: torch.Tensor, losses: torch.Tensor, C: float) -> dict[str, float]:
    """Per-round signals. ``gradients`` is (n, d); ``losses`` holds one loss per data-bearing micro-batch."""
    norms = gradients.norm(dim=1)
    avg = gradients.mean(dim=0)
    med = Median.aggregate(gradients)
    values = torch.stack([
        norms.mean(),
        norms.std(correction=0),
        torch.pdist(gradients).mean(),
        (gradients - med).norm(dim=1).max(),
        torch.nn.functional.cosine_similarity(avg, med, dim=0),
        (norms > C).float().mean(),
        losses.mean(),
    ])
    return dict(zip(X_COLUMNS, values.tolist()))


# ----------------------------------------------------------------------------- signal set v2 (xp4)
# Tail, scale-free and memory signals. Same rule as v1: computed from what the trainer sees in the round (the
# micro-batch gradients, the per-sample losses and the training labels as given, poisoned or not), never from
# which workers are Byzantine, whether an attack is active, the trigger or the target class.
X2_SIGNALS = (
    # A. per-sample loss tail
    "loss_max_ratio",       # max sample loss / median sample loss
    "loss_top3_ratio",      # mean of the 3 largest sample losses / median
    "loss_tail_frac",       # share of samples above the 99th percentile of the previous TAIL_ROUNDS rounds' losses
    # B. label-concentrated loss
    "label_hiloss_max",     # among the TOPK highest-loss samples, the largest share carrying one same label
    "label_loss_gap",       # max over labels of the label's mean loss / median over labels
    # C. outlier micro-batches
    "krum_top_ratio",       # mean of the f largest Krum scores / median Krum score
    "mb_loss_max_ratio",    # max micro-batch loss / median micro-batch loss
    "norm_max_ratio",       # max micro-batch gradient norm / median
    # D. low-rank structure of the centred gradients
    "sv_ratio",             # largest / second singular value
    "sv_top_share",         # share of variance on the top direction
    # E. cross-round consistency
    "outlier_consistency",  # cosine between this round's outlier deviation and the running outlier direction
    "outlier_proj_max",     # max over micro-batches of cos(g_i - median, running outlier direction)
    # F. drift-normalised: z-score against the same signal over the previous Z_ROUNDS rounds
    "z_loss_max_ratio", "z_krum_top_ratio", "z_sv_ratio", "z_mb_loss_max_ratio", "z_norm_std", "z_train_loss",
)
TAIL_ROUNDS, Z_ROUNDS, TOPK, EMA = 20, 50, 8, 0.9
Z_BASE = {"z_loss_max_ratio": "loss_max_ratio", "z_krum_top_ratio": "krum_top_ratio", "z_sv_ratio": "sv_ratio",
          "z_mb_loss_max_ratio": "mb_loss_max_ratio", "z_norm_std": "norm_std", "z_train_loss": "train_loss"}


class SignalTrackerV2:
    """Per-round v2 signals; keeps the cross-round state (loss history, running outlier direction, z windows)."""

    def __init__(self, n: int, f: int):
        self.n, self.f = n, f
        self.loss_hist: list[torch.Tensor] = []
        self.direction: torch.Tensor | None = None
        self.z_hist: dict[str, list[float]] = {k: [] for k in Z_BASE.values()}

    @torch.no_grad()
    def __call__(self, gradients: torch.Tensor, mb_losses: torch.Tensor, sample_losses: torch.Tensor,
                 sample_labels: torch.Tensor) -> dict[str, float]:
        eps = 1e-12
        g = gradients.double()
        n, f = g.shape[0], self.f
        out: dict[str, float] = {}
        # A
        sl = sample_losses.double()
        med_l = sl.median().clamp_min(eps)
        top = sl.topk(min(3, len(sl))).values
        out["loss_max_ratio"] = float(sl.max() / med_l)
        out["loss_top3_ratio"] = float(top.mean() / med_l)
        if self.loss_hist:
            q99 = torch.quantile(torch.cat(self.loss_hist), 0.99)
            out["loss_tail_frac"] = float((sl > q99).double().mean())
        else:
            out["loss_tail_frac"] = 0.0
        self.loss_hist = (self.loss_hist + [sl])[-TAIL_ROUNDS:]
        # B
        k = min(TOPK, len(sl))
        hi_labels = sample_labels[sl.topk(k).indices]
        out["label_hiloss_max"] = float(torch.bincount(hi_labels).max()) / k
        labels = sample_labels.unique()
        per_label = torch.stack([sl[sample_labels == c].mean() for c in labels])
        out["label_loss_gap"] = float(per_label.max() / per_label.median().clamp_min(eps))
        # C
        d2 = torch.cdist(g, g) ** 2
        m = max(1, n - f - 2)
        krum = d2.sort(dim=1).values[:, 1: m + 1].sum(1)  # skip the zero self-distance
        out["krum_top_ratio"] = float(krum.topk(f).values.mean() / krum.median().clamp_min(eps))
        ml = mb_losses.double()
        out["mb_loss_max_ratio"] = float(ml.max() / ml.median().clamp_min(eps))
        norms = g.norm(dim=1)
        out["norm_max_ratio"] = float(norms.max() / norms.median().clamp_min(eps))
        # D (singular values from the n x n Gram matrix of the centred gradients)
        c = g - g.mean(0)
        ev = torch.linalg.eigvalsh(c @ c.T).flip(0).clamp_min(0)
        sv = ev.sqrt()
        out["sv_ratio"] = float(sv[0] / sv[1].clamp_min(eps))
        out["sv_top_share"] = float(ev[0] / ev.sum().clamp_min(eps))
        # E (outliers = the f micro-batches with the largest Krum scores)
        med = g.sort(dim=0).values[(n - 1) // 2]  # coordinate-wise median (deterministic on CUDA)
        dev = g - med
        idx = krum.topk(f).indices
        d = dev[idx].mean(0)
        d = d / d.norm().clamp_min(eps)
        if self.direction is None:
            out["outlier_consistency"], out["outlier_proj_max"] = 0.0, 0.0
            self.direction = d
        else:
            v = self.direction / self.direction.norm().clamp_min(eps)
            out["outlier_consistency"] = float(d @ v)
            out["outlier_proj_max"] = float((dev @ v / dev.norm(dim=1).clamp_min(eps)).max())
            self.direction = EMA * self.direction + (1 - EMA) * d
        # F
        base = {**out, "norm_std": float(norms.std(correction=0)), "train_loss": float(ml.mean())}
        for zname, b in Z_BASE.items():
            h = self.z_hist[b]
            if len(h) >= 5:
                t = torch.tensor(h, dtype=torch.float64)
                out[zname] = float((base[b] - t.mean()) / t.std(correction=0).clamp_min(1e-9))
            else:
                out[zname] = 0.0
            self.z_hist[b] = (h + [base[b]])[-Z_ROUNDS:]
        return {f"x2_{k}": out[k] for k in X2_SIGNALS}


X2_COLUMNS = tuple(f"x2_{s}_{agg}" for s in X2_SIGNALS for agg in ("mean", "max"))
__CPC_DP_EOF__
cat > poison_testbed/simulation.py <<'__CPC_DP_EOF__'
"""PoisoningSimulation: the library's centralised SGD round, with data-poisoning workers,
a windowed attack, a per-round scheduled aggregator and signal capture.

Differences from ``CentralisedSimulation.step`` (library code is not modified):

* all n workers own a DataLoader over the *same* full training set, so each
  round's n micro-batches are IID draws from one dataset (micro-batch reading);
* every worker draws its micro-batch every round, attacked or not, so the data
  stream depends only on the seed (not on the schedule or the attack window);
* the f Byzantine workers either corrupt their micro-batch (data attack), or are
  replaced by a library ``Attack`` (gradient attack), or behave honestly
  (no attack / outside the window);
* worker order is shuffled each round (seeded) before signals and aggregation, so
  position cannot reveal who is Byzantine;
* ClipNoise noise is drawn every round from a dedicated stream, whether or not the
  defense is on (common random numbers across schedules);
* ``step`` returns the per-round signals X, computed before aggregation. It is ``gather`` (gradients and
  signals) then ``apply`` (aggregate and update): a caller can decide the aggregator of a round from that
  round's own signals by setting ``schedule`` between the two (xp8);
* ``n_byz`` (xp8): number of Byzantine workers, which may differ from ``f``, the number Krum and the
  signals assume (default: equal).
"""

from typing import Any

import torch
from torch.utils.data import DataLoader

from krum.primitives.aggregators import Aggregator
from krum.simulations.centralised.krum_nips_2017 import KrumSimulation

from .aggregators import ClipNoise, ScheduledAggregator
from .poisoning import AttackSpec
from .signals import SignalTrackerV2, round_signals

# Offsets that separate the seeded streams of one run.
PERM_STREAM, NOISE_STREAM = 10_000, 20_000


class PoisoningSimulation(KrumSimulation):
    def __init__(
        self,
        *,
        attack_spec: AttackSpec,
        corrupt_kwargs: dict[str, Any],
        plain: type[Aggregator],
        defense: type[Aggregator],
        defense_kwargs: dict[str, Any],
        schedule: list[int],
        block_len: int,
        C_ref: float,
        signals_v2: bool = False,
        n_byz: int | None = None,
        **kwargs: Any,
    ) -> None:
        # The library's own aggregator/attack slots are left empty: this subclass's step() handles both.
        super().__init__(aggregator=None, attack=None, **kwargs)
        self.attack_spec = attack_spec
        self.corrupt_kwargs = corrupt_kwargs
        self.plain = plain
        self.defense = defense
        self.defense_kwargs = defense_kwargs
        self.schedule = schedule
        self.block_len = block_len
        self.C_ref = C_ref
        self.tracker = SignalTrackerV2(self.n, self.f) if signals_v2 else None
        self.n_byz = self.f if n_byz is None else n_byz
        if not 0 <= self.n_byz < self.n:
            raise ValueError(f"n_byz must be in [0, n), got {self.n_byz}")
        self._pending: tuple[int, torch.Tensor] | None = None
        if len(schedule) * block_len != self.rounds:
            raise ValueError(f"schedule covers {len(schedule) * block_len} rounds, expected {self.rounds}")

    def setup(self) -> None:
        super().setup()  # seeds, model, honest loaders (generator seed + w), test loader
        # Byzantine workers get loaders too (same seeding scheme), so they can carry data.
        for w in range(self.n - self.f, self.n):
            gen = torch.Generator().manual_seed(self.seed + w)
            self._worker_loaders.append(
                DataLoader(self.train_datasets[w], batch_size=self.batch_size, shuffle=True, generator=gen)
            )
        dev = self.device
        self._perm_gen = torch.Generator(device=dev).manual_seed(self.seed + PERM_STREAM)
        self._noise_gen = torch.Generator(device=dev).manual_seed(self.seed + NOISE_STREAM)

    def _grad_and_loss(self, x: torch.Tensor, y: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor, torch.Tensor]:
        """Same computation as the library's ``_train_one_worker``, also returning the loss, and the per-sample
        losses and labels when v2 signals are on (computed from the same logits, outside the autograd graph, so
        the gradient is unchanged)."""
        assert self._model is not None
        self._model.module.train()
        x, y = x.to(self.device), y.to(self.device)
        self._model.module.zero_grad()
        logits = self._model.module(x)
        loss = self.loss_fn(logits, y)
        loss.backward()
        per_sample = None
        if self.tracker is not None:
            with torch.no_grad():
                per_sample = torch.nn.functional.cross_entropy(logits.detach(), y, reduction="none")
        return self._model.relink_gradients().clone(), loss.detach(), per_sample, y

    def step(self) -> dict[str, float]:
        x_round = self.gather()
        self.apply()
        return x_round

    def gather(self) -> dict[str, float]:
        """First half of a round: every worker's gradient and the round's signals (nothing is aggregated)."""
        if self._pending is not None:
            raise RuntimeError("gather() called twice without apply()")
        if self._model is None:
            raise RuntimeError("Simulation not set up. Call setup() first.")
        t = self._current_round
        block = t // self.block_len
        attacking = self.attack_spec.active(block)
        n_honest = self.n - self.n_byz
        spec = self.attack_spec

        grads: list[torch.Tensor] = []
        losses: list[torch.Tensor] = []
        sample_losses: list[torch.Tensor] = []
        sample_labels: list[torch.Tensor] = []
        for w in range(self.n):
            x, y = next(iter(self._worker_loaders[w]))  # always drawn: keeps the data stream fixed
            byzantine = w >= n_honest and attacking
            if byzantine and spec.kind == "gradient":
                continue  # filled below from the honest gradients
            if byzantine and spec.kind == "data":
                assert spec.corrupt is not None
                x, y = spec.corrupt(x, y, **self.corrupt_kwargs)
            g, loss, per_sample, labels = self._grad_and_loss(x, y)
            grads.append(g)
            losses.append(loss)
            if per_sample is not None:
                sample_losses.append(per_sample)
                sample_labels.append(labels)

        if attacking and spec.kind == "gradient":
            assert spec.attack_cls is not None
            byz = spec.attack_cls.generate(torch.stack(grads[:n_honest]), f=self.n_byz, **spec.attack_kwargs)
            grads.extend(byz)

        perm = torch.randperm(self.n, generator=self._perm_gen, device=self.device)
        stacked = torch.stack(grads)[perm]
        x_round = round_signals(stacked, torch.stack(losses), self.C_ref)
        if self.tracker is not None:
            mb_losses = torch.stack(losses)
            if len(mb_losses) == self.n:
                mb_losses = mb_losses[perm]  # same order as the gradients
            x_round.update(self.tracker(stacked, mb_losses, torch.cat(sample_losses), torch.cat(sample_labels)))

        self._pending = (t, stacked)
        return x_round

    def apply(self) -> None:
        """Second half of a round: aggregate with schedule[round // block_len] and update the model."""
        if self._pending is None:
            raise RuntimeError("apply() called before gather()")
        t, stacked = self._pending
        self._pending = None
        noise = torch.randn(stacked.shape[1], generator=self._noise_gen, device=self.device, dtype=stacked.dtype)
        defense_kwargs = dict(self.defense_kwargs)
        if issubclass(self.defense, ClipNoise):
            defense_kwargs["noise"] = noise
        aggregated = ScheduledAggregator.aggregate(
            stacked, round=t, plain=self.plain, defense=self.defense, schedule=self.schedule,
            block_len=self.block_len, defense_kwargs=defense_kwargs, n=self.n, f=self.f,
        )

        # Same update as the library's step (weight decay and lr schedule are off in this testbed).
        self._model.gradients = aggregated
        with torch.no_grad():
            self._model.parameters.add_(self._model.gradients, alpha=-self._current_lr)
        self._current_round += 1

    @torch.no_grad()
    def accuracy_loss(self, x: torch.Tensor, y: torch.Tensor) -> tuple[float, float]:
        assert self._model is not None
        self._model.module.eval()
        logits = self._model.module(x)
        return (logits.argmax(1) == y).float().mean().item(), self.loss_fn(logits, y).item()

    @torch.no_grad()
    def target_rate(self, x: torch.Tensor, target: int) -> float:
        assert self._model is not None
        self._model.module.eval()
        return (self._model.module(x).argmax(1) == target).float().mean().item()
