cat > analyze.py <<'__CPC_DP_EOF__'
"""Step 4: causal analysis of the randomized-defense logs.

    python analyze.py --runs results/xp1/results_collect/runs/all_blocks.csv --out results/xp1/analysis

Q1  When does defending matter?
    (i)  one-step effect: per block b and condition, regress Y[b] - Y[b-1] on W[b]
         (= difference in means, W is a single binary regressor); also pooled by phase.
    (ii) final effect: regress Y[49] on the fraction of defended blocks in 5 phases of 10.
    Bootstrap CIs resample runs (not rows) within each condition.
Q2  Does the one-step effect depend on history X, or only on time (and lr)?
    Ridge regression of Y[b] - Y[b-1] on W, time, W x time, X[b-1]  (M0)
    versus M0 + W x X[b-1]  (M1). Held-out MSE, 5-fold split by run.
Q3  Can the attack be detected from X alone? Logistic regression X[b] -> u_active[b],
    AUC per attack type (and per defense), 5-fold split by seed.
Outputs: figures (PNG), tables (CSV), summary.md.
"""

import argparse
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402
from matplotlib.colors import LinearSegmentedColormap  # noqa: E402
from sklearn.linear_model import LogisticRegression, Ridge  # noqa: E402
from sklearn.metrics import roc_auc_score  # noqa: E402
from sklearn.model_selection import GroupKFold  # noqa: E402
from sklearn.pipeline import make_pipeline  # noqa: E402
from sklearn.preprocessing import StandardScaler  # noqa: E402

ATTACKS = ["none", "label_flip", "backdoor", "backdoor_win", "alie", "sign_flip"]
DEFENSES = ["ClipNoise", "Krum", "MultiKrum", "Median", "TrimmedMean", "Bulyan"]
X_COLS = ["x_norm_mean", "x_norm_std", "x_pdist_mean", "x_maxdist_median", "x_cos_avg_median",
          "x_frac_clipped", "x_train_loss", "x_val_acc"]
OUTCOMES = {"y_clean_acc": "clean accuracy", "y_atk": "backdoor success"}
N_PHASES = 5

# Reference palette (validated: light surface, categorical slots 1-6; contrast WARN -> legends + tables).
SURFACE, INK, INK2, GRID = "#fcfcfb", "#0b0b0b", "#52514e", "#e4e3df"
SERIES = dict(zip(DEFENSES, ["#2a78d6", "#eb6834", "#1baf7a", "#eda100", "#e87ba4", "#008300"]))
DIVERGING = LinearSegmentedColormap.from_list("div", ["#e34948", "#f0efec", "#2a78d6"])
SEQUENTIAL = LinearSegmentedColormap.from_list("seq", ["#f0efec", "#86b6ef", "#2a78d6", "#104281"])

plt.rcParams.update({
    "figure.facecolor": SURFACE, "axes.facecolor": SURFACE, "savefig.facecolor": SURFACE,
    "axes.edgecolor": GRID, "axes.labelcolor": INK2, "xtick.color": INK2, "ytick.color": INK2,
    "text.color": INK, "axes.grid": True, "grid.color": GRID, "grid.linewidth": 0.6,
    "axes.spines.top": False, "axes.spines.right": False, "font.size": 9, "axes.titlesize": 9,
    "lines.linewidth": 1.6, "legend.frameon": False,
})


# ----------------------------------------------------------------------------- data
def load(path: Path) -> pd.DataFrame:
    df = pd.read_csv(path).sort_values(["run_id", "block"]).reset_index(drop=True)
    sizes = df.groupby("run_id").size()
    if sizes.nunique() != 1:
        raise SystemExit(f"runs have different lengths: {sizes.value_counts().to_dict()}")
    return df


def panel(df: pd.DataFrame, attack: str, defense: str, y: str) -> dict[str, np.ndarray]:
    """Arrays for one condition: Y (R, B+1) incl. block -1, W (R, B), X (R, B, k) for blocks 0..B-1."""
    sub = df[(df.attack == attack) & (df.defense == defense)]
    runs = sorted(sub.run_id.unique())
    sub = sub.set_index(["run_id", "block"]).sort_index()
    Y = sub[y].unstack("block").loc[runs].to_numpy(float)
    W = sub["W"].unstack("block").loc[runs].drop(columns=-1).to_numpy(float)
    X = np.stack([sub[c].unstack("block").loc[runs].drop(columns=-1).to_numpy(float) for c in X_COLS], axis=2)
    seeds = sub["seed"].groupby("run_id").first().loc[runs].to_numpy()
    return {"Y": Y, "W": W, "X": X, "seeds": seeds, "runs": np.array(runs)}


def conditions(df: pd.DataFrame, y: str) -> list[tuple[str, str]]:
    have = df.groupby(["attack", "defense"])[y].apply(lambda s: s.notna().any())
    return [(a, d) for a in ATTACKS for d in DEFENSES if have.get((a, d), False)]


# ----------------------------------------------------------------------------- Q1
def diff_in_means(D: np.ndarray, W: np.ndarray) -> np.ndarray:
    """Per-column E[D | W=1] - E[D | W=0]; works on (..., R, B) arrays."""
    on, off = W.sum(-2), (1 - W).sum(-2)
    with np.errstate(invalid="ignore", divide="ignore"):
        return (D * W).sum(-2) / on - (D * (1 - W)).sum(-2) / off


def q1(df: pd.DataFrame, y: str, n_boot: int, rng: np.random.Generator) -> tuple[pd.DataFrame, pd.DataFrame, pd.DataFrame]:
    step_rows, phase_rows, final_rows = [], [], []
    for attack, defense in conditions(df, y):
        p = panel(df, attack, defense, y)
        D, W, Y = np.diff(p["Y"], axis=1), p["W"], p["Y"]
        R, B = W.shape
        per_phase = B // N_PHASES
        idx = rng.integers(0, R, size=(n_boot, R))

        est = diff_in_means(D, W)
        boot = diff_in_means(D[idx], W[idx])  # (n_boot, B)
        lo, hi = np.nanpercentile(boot, [2.5, 97.5], axis=0)
        for b in range(B):
            step_rows.append((attack, defense, b, est[b], lo[b], hi[b]))

        ph = est.reshape(N_PHASES, per_phase).mean(1)
        ph_boot = np.nanmean(boot.reshape(n_boot, N_PHASES, per_phase), axis=2)
        plo, phi = np.nanpercentile(ph_boot, [2.5, 97.5], axis=0)
        for k in range(N_PHASES):
            phase_rows.append((attack, defense, k + 1, ph[k], plo[k], phi[k]))

        F = W.reshape(R, N_PHASES, per_phase).mean(2)
        A = np.column_stack([np.ones(R), F])
        beta = np.linalg.lstsq(A, Y[:, -1], rcond=None)[0]
        bb = np.array([np.linalg.lstsq(A[i], Y[i, -1], rcond=None)[0] for i in idx])
        blo, bhi = np.percentile(bb, [2.5, 97.5], axis=0)
        for k in range(N_PHASES):
            final_rows.append((attack, defense, k + 1, beta[k + 1], blo[k + 1], bhi[k + 1]))

    cols = ["attack", "defense"]
    return (pd.DataFrame(step_rows, columns=[*cols, "block", "effect", "lo", "hi"]),
            pd.DataFrame(phase_rows, columns=[*cols, "phase", "effect", "lo", "hi"]),
            pd.DataFrame(final_rows, columns=[*cols, "phase", "effect", "lo", "hi"]))


# ----------------------------------------------------------------------------- Q2
def q2_design(p: dict[str, np.ndarray]) -> tuple[dict[str, np.ndarray], np.ndarray, np.ndarray]:
    """Rows (run, b) for b = 1..B-1: target Y[b]-Y[b-1], treatment W[b], history X[b-1]."""
    D = np.diff(p["Y"], axis=1)  # D[:, b] = Y[b] - Y[b-1], b = 0..B-1
    R, B = p["W"].shape
    b = np.arange(1, B)
    t = np.tile((b - B / 2) / (B / 2), R)
    T = np.column_stack([t, t**2, t**3])
    w = p["W"][:, 1:].reshape(-1, 1)
    X = p["X"][:, :-1, :].reshape(-1, len(X_COLS))
    X = (X - X.mean(0)) / X.std(0).clip(1e-12)
    designs = {
        "base (no W)": np.column_stack([T, X]),
        "M0: W x time": np.column_stack([w, T, w * T, X]),
        "M1: + W x X": np.column_stack([w, T, w * T, X, w * X]),
    }
    groups = np.repeat(np.arange(R), B - 1)
    return designs, D[:, 1:].reshape(-1), groups


def q2(df: pd.DataFrame, y: str) -> pd.DataFrame:
    rows = []
    for attack, defense in conditions(df, y):
        designs, target, groups = q2_design(panel(df, attack, defense, y))
        fold_mse = {name: [] for name in designs}
        for tr, te in GroupKFold(n_splits=5).split(target, groups=groups):
            for name, A in designs.items():
                model = make_pipeline(StandardScaler(), Ridge(alpha=1.0)).fit(A[tr], target[tr])
                fold_mse[name].append(np.mean((model.predict(A[te]) - target[te]) ** 2))
        m = {k: np.array(v) for k, v in fold_mse.items()}
        gain = m["M0: W x time"] - m["M1: + W x X"]  # > 0: interactions help out of sample
        w_gain = m["base (no W)"] - m["M0: W x time"]
        rows.append({
            "attack": attack, "defense": defense,
            "mse_base": m["base (no W)"].mean(), "mse_M0": m["M0: W x time"].mean(), "mse_M1": m["M1: + W x X"].mean(),
            "rel_gain_M1_vs_M0": 1 - m["M1: + W x X"].mean() / m["M0: W x time"].mean(),
            "gain_se": gain.std(ddof=1) / np.sqrt(len(gain)),
            "gain_mean": gain.mean(),
            "rel_gain_W": 1 - m["M0: W x time"].mean() / m["base (no W)"].mean(),
            "w_gain_mean": w_gain.mean(), "w_gain_se": w_gain.std(ddof=1) / np.sqrt(len(w_gain)),
        })
    return pd.DataFrame(rows)


# ----------------------------------------------------------------------------- Q3
def q3(df: pd.DataFrame) -> pd.DataFrame:
    trained = df[df.block >= 0]

    def auc(frame: pd.DataFrame) -> float:
        Xm, u, g = frame[X_COLS].to_numpy(float), frame.u_active.to_numpy(int), frame.seed.to_numpy()
        if u.min() == u.max():
            return np.nan
        scores = np.zeros(len(u))
        for tr, te in GroupKFold(n_splits=5).split(Xm, groups=g):
            model = make_pipeline(StandardScaler(), LogisticRegression(max_iter=2000)).fit(Xm[tr], u[tr])
            scores[te] = model.predict_proba(Xm[te])[:, 1]
        return roc_auc_score(u, scores)

    rows = []
    for attack in ATTACKS[1:]:
        both = trained[trained.attack.isin(["none", attack])]
        rows.append({"attack": attack, "defense": "all", "auc": auc(both)})
        for defense in DEFENSES:
            rows.append({"attack": attack, "defense": defense, "auc": auc(both[both.defense == defense])})
    rows.append({"attack": "any", "defense": "all", "auc": auc(trained)})
    return pd.DataFrame(rows)


# ----------------------------------------------------------------------------- figures
def fig_onestep(step: pd.DataFrame, phase: pd.DataFrame, y: str, out: Path) -> None:
    attacks = [a for a in ATTACKS if a in set(step.attack)]
    fig, axes = plt.subplots(len(attacks), len(DEFENSES), figsize=(15, 2.0 * len(attacks) + 0.8),
                             sharex=True, sharey="row", squeeze=False)
    for i, attack in enumerate(attacks):
        for j, defense in enumerate(DEFENSES):
            ax = axes[i, j]
            s = step[(step.attack == attack) & (step.defense == defense)]
            ph = phase[(phase.attack == attack) & (phase.defense == defense)]
            color = SERIES[defense]
            ax.axhline(0, color=INK2, linewidth=0.8)
            ax.fill_between(s.block, s.lo, s.hi, color=color, alpha=0.15, linewidth=0)
            ax.plot(s.block, s.effect, color=color, linewidth=1.0, alpha=0.7)
            for _, r in ph.iterrows():  # phase-pooled estimate as a step
                x0, x1 = (r.phase - 1) * 10 - 0.5, r.phase * 10 - 0.5
                ax.plot([x0, x1], [r.effect, r.effect], color=INK, linewidth=2.0)
            if i == 0:
                ax.set_title(defense, color=INK, fontweight="bold")
            if j == 0:
                ax.set_ylabel(f"{attack}\nΔ {OUTCOMES[y]}")
            if i == len(attacks) - 1:
                ax.set_xlabel("block")
    fig.suptitle(f"Q1(i) One-step effect of defending block b on {OUTCOMES[y]}:  "
                 f"E[Y_b − Y_(b−1) | W_b=1] − E[· | W_b=0].  Thin line + band: per block, 95% bootstrap CI "
                 f"(runs resampled).  Black: pooled per phase of 10 blocks.", fontsize=9, color=INK, x=0.01, ha="left")
    fig.tight_layout(rect=(0, 0, 1, 0.97))
    fig.savefig(out / f"q1_onestep_{y}.png", dpi=130)
    plt.close(fig)


def fig_final(final: pd.DataFrame, y: str, out: Path) -> None:
    attacks = [a for a in ATTACKS if a in set(final.attack)]
    cols = min(3, len(attacks))
    rows = int(np.ceil(len(attacks) / cols))
    fig, axes = plt.subplots(rows, cols, figsize=(4.6 * cols, 3.0 * rows + 0.6), squeeze=False)
    offsets = np.linspace(-0.25, 0.25, len(DEFENSES))
    for k, attack in enumerate(attacks):
        ax = axes[k // cols, k % cols]
        ax.axhline(0, color=INK2, linewidth=0.8)
        for off, defense in zip(offsets, DEFENSES):
            s = final[(final.attack == attack) & (final.defense == defense)]
            ax.errorbar(s.phase + off, s.effect, yerr=[s.effect - s.lo, s.hi - s.effect], color=SERIES[defense],
                        marker="o", markersize=4, linewidth=1.4, capsize=0, label=defense)
        ax.set_title(attack, color=INK, fontweight="bold")
        ax.set_xticks(range(1, N_PHASES + 1), [f"{10 * (p - 1)}–{10 * p - 1}" for p in range(1, N_PHASES + 1)])
        ax.set_xlabel("phase (blocks)")
        ax.set_ylabel(f"Δ final {OUTCOMES[y]}")
    for k in range(len(attacks), rows * cols):
        axes[k // cols, k % cols].set_visible(False)
    handles, labels = axes[0, 0].get_legend_handles_labels()
    fig.legend(handles, labels, loc="upper right", ncol=len(DEFENSES), fontsize=8)
    fig.suptitle(f"Q1(ii) Effect on final {OUTCOMES[y]} of defending a whole phase (vs never), "
                 f"OLS on phase fractions; 95% bootstrap CI", fontsize=9, color=INK, x=0.01, ha="left")
    fig.tight_layout(rect=(0, 0, 1, 0.93))
    fig.savefig(out / f"q1_final_{y}.png", dpi=130)
    plt.close(fig)


def heatmap(ax, table: pd.DataFrame, cmap, vmin: float, vmax: float, fmt: str, title: str) -> None:
    im = ax.imshow(table.to_numpy(float), cmap=cmap, vmin=vmin, vmax=vmax, aspect="auto")
    ax.set_xticks(range(table.shape[1]), table.columns, rotation=0)
    ax.set_yticks(range(table.shape[0]), table.index)
    ax.grid(False)
    for (i, j), v in np.ndenumerate(table.to_numpy(float)):
        if not np.isnan(v):
            ax.text(j, i, format(v, fmt), ha="center", va="center", fontsize=8, color=INK)
    ax.set_title(title, color=INK, loc="left")
    return im


def fig_q2(q2s: dict[str, pd.DataFrame], out: Path) -> None:
    fig, axes = plt.subplots(len(q2s), 1, figsize=(9, 2.6 * len(q2s) + 0.4), squeeze=False)
    for ax, (y, t) in zip(axes[:, 0], q2s.items()):
        # Cell = gain of M1 over M0 in units of its fold standard error (|z| > 2 ~ significant).
        z = (t.gain_mean / t.gain_se).to_numpy()
        tab = pd.DataFrame({"attack": t.attack, "defense": t.defense, "z": z}).pivot(
            index="attack", columns="defense", values="z").reindex(
            index=[a for a in ATTACKS if a in set(t.attack)], columns=DEFENSES)
        im = heatmap(ax, tab, DIVERGING, -4, 4, "+.1f",
                     f"{OUTCOMES[y]}: held-out MSE gain of M1 (+ W×X) over M0 (W×time), in fold-SE units")
        fig.colorbar(im, ax=ax, shrink=0.8, label="z  (>0: history helps)")
    fig.tight_layout()
    fig.savefig(out / "q2_interactions.png", dpi=130)
    plt.close(fig)


def fig_q3(t: pd.DataFrame, out: Path) -> None:
    tab = t[t.attack != "any"].pivot(index="attack", columns="defense", values="auc").reindex(
        index=ATTACKS[1:], columns=["all", *DEFENSES])
    fig, ax = plt.subplots(figsize=(9, 3.2))
    im = heatmap(ax, tab, SEQUENTIAL, 0.5, 1.0, ".2f",
                 "Q3  Detecting an active attack from X alone: held-out AUC (split by seed)")
    fig.colorbar(im, ax=ax, shrink=0.8, label="AUC")
    fig.tight_layout()
    fig.savefig(out / "q3_detection_auc.png", dpi=130)
    plt.close(fig)


# ----------------------------------------------------------------------------- summary
def fmt_ci(r: pd.Series, scale: float = 100) -> str:
    return f"{scale * r.effect:+.1f} [{scale * r.lo:+.1f}, {scale * r.hi:+.1f}]"


def summary(df: pd.DataFrame, res: dict, out: Path) -> str:
    n_runs = df.run_id.nunique()
    per_cond = df.groupby(["attack", "defense"]).run_id.nunique()
    shared = df[df.block >= 0].groupby("seed").apply(lambda g: g.groupby("run_id").W.apply(tuple).nunique()).max()
    L = [
        "# Step 4 summary: randomized defense schedules",
        "",
        f"Data: {n_runs} runs, {per_cond.min()}–{per_cond.max()} runs per (attack, defense), "
        f"{df.block.max() + 1} blocks per run. Effects are in **percentage points**; brackets are 95% bootstrap "
        "CIs resampling runs.",
        "",
        "Design note: the schedule seed is `1000 + seed`, so a given seed has the same W schedule in every "
        f"condition (max distinct schedules per seed: {shared}). Within a condition the 20 schedules are "
        "independent, which is what every estimate below relies on; conditions are not independent replicates "
        "of each other.",
        "",
    ]

    # Q1 ---------------------------------------------------------------------
    L += ["## Q1. When does defending matter?", ""]
    for y in res["q1"]:
        final = res["q1"][y][2]
        L += [f"### Final {OUTCOMES[y]}: effect of defending a whole phase (vs never)", "",
              "| attack | defense | " + " | ".join(f"blocks {10 * (p - 1)}–{10 * p - 1}" for p in range(1, 6)) + " |",
              "|---|---|" + "---|" * 5]
        for (a, d), g in final.groupby(["attack", "defense"], sort=False):
            cells = []
            for _, r in g.sort_values("phase").iterrows():
                sig = (r.lo > 0) or (r.hi < 0)
                cells.append(("**" + fmt_ci(r) + "**") if sig else fmt_ci(r))
            L.append(f"| {a} | {d} | " + " | ".join(cells) + " |")
        L += ["", "Bold: CI excludes 0.", ""]
        phase = res["q1"][y][1]
        top = phase.assign(sig=(phase.lo > 0) | (phase.hi < 0))
        n_sig = int(top.sig.sum())
        L += [f"One-step effect on {OUTCOMES[y]} (pooled per phase): {n_sig} of {len(top)} (condition, phase) "
              "cells have a CI excluding 0. Largest effects:", ""]
        for _, r in top.reindex(top.effect.abs().sort_values(ascending=False).index).head(6).iterrows():
            L.append(f"- {r.attack} / {r.defense}, phase {r.phase}: {fmt_ci(r, 100)} pts per defended block")
        L.append("")

    # Q2 ---------------------------------------------------------------------
    L += ["## Q2. Does the effect depend on history X?", "",
          "M0 lets the effect of W vary with time only (W × cubic in block; lr is constant in this "
          "dataset, so it cannot be separated from time). M1 adds W × X[b−1]. Held-out MSE, 5 folds split "
          "by run. z = mean fold gain / its standard error.", ""]
    for y, t in res["q2"].items():
        z = t.gain_mean / t.gain_se
        zw = t.w_gain_mean / t.w_gain_se
        L += [f"**{OUTCOMES[y]}**: W itself improves held-out error (z > 2) in {int((zw > 2).sum())}/{len(t)} "
              f"conditions. Adding W × X improves it (z > 2) in {int((z > 2).sum())}/{len(t)}, "
              f"hurts (z < −2) in {int((z < -2).sum())}/{len(t)}; median relative MSE change "
              f"{100 * t.rel_gain_M1_vs_M0.median():+.2f}%.", ""]
        best = t.assign(z=z).sort_values("z", ascending=False).head(5)
        L += ["| attack | defense | MSE gain from W (%) | MSE gain from W×X (%) | z (W×X) |", "|---|---|---|---|---|"]
        for _, r in best.iterrows():
            L.append(f"| {r.attack} | {r.defense} | {100 * r.rel_gain_W:+.2f} | {100 * r.rel_gain_M1_vs_M0:+.2f} | "
                     f"{r.z:+.1f} |")
        L.append("")

    # Q3 ---------------------------------------------------------------------
    t = res["q3"]
    L += ["## Q3. Can an attack be detected from X alone?", "",
          "Logistic regression X[b] → u_active[b] on the attacked runs plus the no-attack runs; "
          "held-out AUC with 5 folds split by seed (a seed's runs are never in train and test at once).", "",
          "| attack | all defenses | " + " | ".join(DEFENSES) + " |", "|---|---|" + "---|" * len(DEFENSES)]
    for a in ATTACKS[1:]:
        g = t[t.attack == a].set_index("defense").auc
        L.append(f"| {a} | **{g['all']:.3f}** | " + " | ".join(f"{g[d]:.3f}" for d in DEFENSES) + " |")
    L += ["", f"Any attack vs none, all conditions pooled: AUC {t[t.attack == 'any'].auc.iloc[0]:.3f}.", ""]

    L += ["## Files", "",
          "- `q1_onestep_<y>.png`, `q1_final_<y>.png`, `q2_interactions.png`, `q3_detection_auc.png`",
          "- tables: `q1_onestep_<y>.csv`, `q1_phase_<y>.csv`, `q1_final_<y>.csv`, `q2_<y>.csv`, `q3.csv`", ""]
    text = "\n".join(L)
    (out / "summary.md").write_text(text, encoding="utf-8")
    return text


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--runs", type=Path, default=Path("results/xp1/results_collect/runs/all_blocks.csv"))
    ap.add_argument("--out", type=Path, default=Path("results/xp1/analysis"))
    ap.add_argument("--boot", type=int, default=1000)
    ap.add_argument("--seed", type=int, default=0)
    args = ap.parse_args()
    args.out.mkdir(parents=True, exist_ok=True)
    rng = np.random.default_rng(args.seed)
    df = load(args.runs)

    res: dict = {"q1": {}, "q2": {}}
    for y in OUTCOMES:
        step, phase, final = q1(df, y, args.boot, rng)
        res["q1"][y] = (step, phase, final)
        step.to_csv(args.out / f"q1_onestep_{y}.csv", index=False)
        phase.to_csv(args.out / f"q1_phase_{y}.csv", index=False)
        final.to_csv(args.out / f"q1_final_{y}.csv", index=False)
        fig_onestep(step, phase, y, args.out)
        fig_final(final, y, args.out)
        res["q2"][y] = q2(df, y)
        res["q2"][y].to_csv(args.out / f"q2_{y}.csv", index=False)
        print(f"done {y}", flush=True)
    fig_q2(res["q2"], args.out)
    res["q3"] = q3(df)
    res["q3"].to_csv(args.out / "q3.csv", index=False)
    fig_q3(res["q3"], args.out)
    import sys
    sys.stdout.reconfigure(encoding="utf-8")
    print(summary(df, res, args.out))


if __name__ == "__main__":
    main()
__CPC_DP_EOF__
cat > gru_experiment.py <<'__CPC_DP_EOF__'
"""GRU outcome model: predict future outcomes under a candidate defense schedule.

    python gru_experiment.py                                    # xp1 (frozen model in results/xp1/gru)
    python gru_experiment.py --cf runs_cf/all_blocks.csv        # xp1 + check 3 against true counterfactual runs
    python gru_experiment.py --runs results/xp2/runs_xp2/all_blocks.csv --out results/xp2/gru   # xp2

Model. An encoder GRU reads the observable history up to block b: the signals X
(incl. validation accuracy), the defense flag W, time and the defense type. A
decoder GRU, started from the encoder state, reads the candidate future
schedule W[b+1:] and outputs y_clean_acc and y_atk for every future block.
Inputs never include U (attack type / activity), Y_clean or Y_atk: the attack
must be inferred from X. Future X is not predicted (no feedback of errors).

The run length is read from the data (xp1: 50 blocks of 10 rounds; xp2: 250
blocks of 2 rounds). Training samples CUTS_PER_BATCH cut points per batch
(all of them when a run has fewer cuts).

Split by seed, stratified by attack (see assign_splits): 70% train, 10%
validation (early stopping), 20% test. For xp1 (seeds 0-19 in every
condition) this is train 0-13 / val 14-15 / test 16-19.

Check 1  Prediction error on test seeds, by horizon, vs baselines.
Check 2  (xp1-shaped data only) GRU-implied one-step effect of W vs the
         randomized Q1 estimate (analyze.py).
Check K  (windowed attacks) Kill awareness: from the history up to the attack's
         first block, does the GRU predict that defending from now on keeps the
         backdoor out, and that not defending implants it?
Check 3  (xp1, --cf) Counterfactual reruns. The model is frozen once trained
         (weights hash in report.json); --cf only loads it, never retrains.
"""

import argparse
import hashlib
import json
import re
import sys
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt 
import numpy as np 
import pandas as pd 
import torch 
from torch import nn 

import analyze 
from analyze import DEFENSES, INK, INK2, SERIES, X_COLS 

Y_COLS = ["y_clean_acc", "y_atk"]
CF_PREFIX = 3
CUTS_PER_BATCH = 16
MAX_RIDGE_PAIRS = 1_000_000


def assign_splits(df: pd.DataFrame) -> pd.Series:
    """Split by seed, stratified by attack: rank each attack's seeds, then rank % 20 in 0-13 train, 14-15 val,
    16-19 test (70/10/20).

    xp1: each attack has seeds 0-19, so rank = seed (train 0-13, val 14-15, test 16-19, as before).
    xp2: the attack is set by seed % 10, so a plain seed % 20 rule would leave the windowed attack out of
    the test set; ranking within each attack keeps every attack in every split. The attack label is used
    for stratification only, never as a model input.
    """
    split = pd.Series(index=df.index, dtype=object)
    # xp3 logs the poison rate: stratify by it too, so every rate is in every split (xp1/xp2: attack only).
    keys = ["attack", "poison_frac"] if "poison_frac" in df else ["attack"]
    # xp5 mixes defenses per run: stratify by defense too (xp1: every (attack, defense) has seeds 0-19 -> same split).
    mixed = df.defense.nunique() > 1
    if mixed:
        keys.append("defense")
    for _, g in df.groupby(keys):
        seeds = sorted(g.seed.unique())
        rank = {s: k for k, s in enumerate(seeds)}
        if mixed:
            # Relative rank: every group, however small, spreads over train / val / test (xp5 has many small groups).
            # xp1 (20 seeds per group): rank/20 < 0.7 <=> rank < 14, < 0.8 <=> rank < 16 -> the same split as before.
            q = g.seed.map(rank) / len(seeds)
            split[g.index] = np.where(q < 0.7, "train", np.where(q < 0.8, "val", "test"))
        else:
            r = g.seed.map(rank) % 20
            split[g.index] = np.where(r < 14, "train", np.where(r < 16, "val", "test"))
    return split


def x_columns(df: pd.DataFrame) -> list[str]:
    return list(X_COLS) + [c for c in df.columns if c.startswith("x2_")]


def horizons(n_blocks: int) -> list[int]:
    return [1, 5, n_blocks // 5, n_blocks // 2]  # xp1: 1, 5, 10, 25


# ----------------------------------------------------------------------------- tensors
class Data:
    """Per-run tensors. Row i is block i-1 (row 0 = initial state); n_rows = n_blocks + 1."""

    def __init__(self, df: pd.DataFrame, x_mean: np.ndarray | None = None, x_std: np.ndarray | None = None,
                 x_cols: list[str] | None = None):
        # Inputs: the v1 signals, plus the v2 signals when the data has them (xp4). xp1-xp3 are unchanged.
        self.x_cols = x_cols if x_cols is not None else x_columns(df)
        df = df.sort_values(["run_id", "block"])
        runs = df.groupby("run_id", sort=True)
        sizes = runs.size()
        if sizes.nunique() != 1:
            raise ValueError(f"runs have different lengths: {sizes.value_counts().to_dict()}")
        meta = runs.first()[["seed", "attack", "defense"]]
        self.run_ids = meta.index.to_numpy()
        self.seed = meta.seed.to_numpy()
        self.attack = meta.attack.to_numpy()
        self.defense = meta.defense.to_numpy()
        R, n = len(meta), int(sizes.iloc[0])
        self.n_rows, self.n_blocks = n, n - 1
        X = df[self.x_cols].to_numpy(float).reshape(R, n, len(self.x_cols))
        if x_mean is None:
            x_mean, x_std = np.nanmean(X[:, 1:], axis=(0, 1)), np.nanstd(X[:, 1:], axis=(0, 1))
        self.x_mean, self.x_std = x_mean, x_std
        X = np.nan_to_num((X - x_mean) / x_std)  # row 0 (init) -> 0, flagged below
        if len(self.x_cols) > len(X_COLS):
            X = np.clip(X, -10, 10)  # v2 ratio signals are heavy-tailed (xp4 only; v1 data is left as before)
        W = np.nan_to_num(df.W.to_numpy(float).reshape(R, n))
        t = np.broadcast_to((np.arange(n) - 1) / self.n_blocks, (R, n))
        init = np.zeros((R, n)); init[:, 0] = 1
        D = np.stack([self.defense == d for d in DEFENSES], 1).astype(float)  # (R, 6)
        Dr = np.broadcast_to(D[:, None, :], (R, n, len(DEFENSES)))
        self.W = W
        self.enc = torch.tensor(np.concatenate([X, W[..., None], t[..., None], init[..., None], Dr], -1),
                                dtype=torch.float32)
        self.D = torch.tensor(D, dtype=torch.float32)
        Y = df[Y_COLS].to_numpy(float).reshape(R, n, 2)
        self.Y = torch.tensor(np.nan_to_num(Y), dtype=torch.float32)
        self.Ymask = torch.tensor(~np.isnan(Y), dtype=torch.float32)
        # Attack activity per block: an evaluation label only (never a model input).
        self.U = df.u_active.to_numpy(float).reshape(R, n) if "u_active" in df else None

    def dec_inputs(self, W: np.ndarray | torch.Tensor, runs: slice | None = None) -> torch.Tensor:
        """Decoder inputs for rows 1..n-1 given a schedule W (R, n): [W, t, defense one-hot].

        ``runs`` selects whose defense one-hot to use; by default W has one row per run of this Data (or this
        Data holds a single run, whose one-hot is shared by every row of W, e.g. several candidate plans).
        """
        W = torch.as_tensor(np.asarray(W, float), dtype=torch.float32)
        R, n = W.shape[0], self.n_rows
        D = self.D if runs is None else self.D[runs]
        t = ((torch.arange(1, n) - 1) / self.n_blocks).expand(R, -1)
        return torch.cat([W[:, 1:, None], t[..., None], D[:, None, :].expand(R, n - 1, -1)], -1)


# ----------------------------------------------------------------------------- model
class OutcomeGRU(nn.Module):
    def __init__(self, enc_dim: int, dec_dim: int, hidden: int = 64):
        super().__init__()
        self.enc = nn.GRU(enc_dim, hidden, batch_first=True)
        self.dec = nn.GRU(dec_dim, hidden, batch_first=True)
        self.head = nn.Linear(hidden, 2)

    def encode(self, enc_x: torch.Tensor) -> torch.Tensor:
        return self.enc(enc_x)[0]  # (R, rows, H): state after each row

    def decode(self, h0: torch.Tensor, dec_x: torch.Tensor) -> torch.Tensor:
        out, _ = self.dec(dec_x, h0.unsqueeze(0).contiguous())
        return torch.sigmoid(self.head(out))  # (N, steps, 2)


def cut_predictions(model: OutcomeGRU, enc_x: torch.Tensor, dec_x: torch.Tensor,
                    cuts: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor, torch.Tensor]:
    """Predictions from history rows 0..i for each cut i in ``cuts``, for every later row i+1+j.

    Returns preds (R, C, S, 2), a validity mask (C, S) for rows <= n-1, and idx (C, S): the dec_x / Y[:, 1:]
    index of the target row (row i+1+j has index i+j).
    """
    R, n_dec = enc_x.shape[0], dec_x.shape[1]  # n_dec = n_rows - 1
    cuts = cuts.to(enc_x.device)
    h = model.encode(enc_x)[:, cuts]  # (R, C, H)
    S = n_dec - int(cuts.min())
    j = torch.arange(S, device=enc_x.device)
    raw = cuts[:, None] + j[None, :]
    valid = raw < n_dec
    idx = raw.clamp(max=n_dec - 1)
    C = len(cuts)
    seq = dec_x[:, idx]  # (R, C, S, F)
    out = model.decode(h.reshape(R * C, -1), seq.reshape(R * C, S, -1)).reshape(R, C, S, 2)
    return out, valid, idx


def fit_gru(tr: Data, va: Data, device: torch.device, epochs: int, hidden: int, seed: int,
            cuts_per_batch: int = CUTS_PER_BATCH, lr: float = 2e-3, weight_decay: float = 0.0,
            patience_max: int = 25) -> tuple[OutcomeGRU, list]:
    """Masked MSE over (cut, future block); early stopping on validation seeds (patience 25 by default).

    lr / weight_decay default to the xp1/xp2 settings (Adam, 2e-3, none); xp3 overfits with them.
    """
    torch.manual_seed(seed)
    model = OutcomeGRU(tr.enc.shape[-1], tr.dec_inputs(tr.W).shape[-1], hidden).to(device)
    opt = (torch.optim.AdamW(model.parameters(), lr=lr, weight_decay=weight_decay) if weight_decay
           else torch.optim.Adam(model.parameters(), lr=lr))
    tr_dec, va_dec = tr.dec_inputs(tr.W), va.dec_inputs(va.W)
    n_cuts = tr.n_rows - 1
    va_cuts = torch.arange(0, n_cuts, max(1, n_cuts // 50))  # fixed, evenly spaced: a stable validation loss
    best, best_state, history, patience = np.inf, None, [], 0
    gen = torch.Generator().manual_seed(seed)

    def loss_on(data: Data, dec: torch.Tensor, rows: torch.Tensor, cuts: torch.Tensor) -> torch.Tensor:
        pred, valid, idx = cut_predictions(model, data.enc[rows].to(device), dec[rows].to(device), cuts)
        Y = data.Y[rows][:, 1:].to(device)[:, idx]  # (B, C, S, 2): target row i+1+j
        M = data.Ymask[rows][:, 1:].to(device)[:, idx] * valid[None, :, :, None]
        return (((pred - Y) ** 2) * M).sum() / M.sum()

    for _ in range(epochs):
        model.train()
        for batch in torch.randperm(len(tr.seed), generator=gen).split(32):
            cuts = (torch.arange(n_cuts) if n_cuts <= cuts_per_batch
                    else torch.randperm(n_cuts, generator=gen)[:cuts_per_batch].sort().values)
            opt.zero_grad()
            loss_on(tr, tr_dec, batch, cuts).backward()
            opt.step()
        model.eval()
        with torch.no_grad():
            v = np.mean([loss_on(va, va_dec, rows, va_cuts).item() for rows in torch.arange(len(va.seed)).split(16)])
        history.append(float(v))
        if v < best - 1e-6:
            best, patience = v, 0
            best_state = {k: t.detach().clone() for k, t in model.state_dict().items()}
        else:
            patience += 1
            if patience >= patience_max:
                break
    model.load_state_dict(best_state)
    return model, history


@torch.no_grad()
def predict_cuts(model: OutcomeGRU, data: Data, cuts: torch.Tensor, device, chunk: int = 16) -> np.ndarray:
    """(R, C, S, 2) predictions under each run's own schedule, computed in chunks of runs."""
    dec = data.dec_inputs(data.W)
    parts = [cut_predictions(model, data.enc[r].to(device), dec[r].to(device), cuts)[0].cpu().numpy()
             for r in torch.arange(len(data.seed)).split(chunk)]
    return np.concatenate(parts)


# ----------------------------------------------------------------------------- baselines
def ridge_features(data: Data, cut_rows: np.ndarray, target_rows: np.ndarray, run_idx: np.ndarray) -> np.ndarray:
    """Direct multi-horizon linear baseline: X at the cut, time, horizon, defense, and future-W summaries."""
    enc = data.enc.numpy()
    Xc = enc[run_idx, cut_rows]  # (N, F): X, W, t, init, defense one-hot
    D = data.D.numpy()[run_idx]
    W = data.W[run_idx]
    h = (target_rows - cut_rows)[:, None] / data.n_blocks
    w_target = W[np.arange(len(run_idx)), target_rows][:, None]
    csum = np.cumsum(W, axis=1)
    w_frac = ((csum[np.arange(len(run_idx)), target_rows] - csum[np.arange(len(run_idx)), cut_rows])
              / (target_rows - cut_rows))[:, None]
    wf = np.concatenate([w_target, w_frac], 1)
    inter = (wf[:, :, None] * D[:, None, :]).reshape(len(run_idx), -1)  # W summaries x defense
    return np.concatenate([Xc, h, h**2, wf, inter, wf * h], 1)


def pairs(R: int, n_rows: int, cuts: np.ndarray | None = None) -> tuple[np.ndarray, np.ndarray, np.ndarray]:
    """All (run, cut row, target row) with target > cut, for the given cut rows (default: all)."""
    cuts = np.arange(n_rows - 1) if cuts is None else np.asarray(cuts)
    run, cut, tgt = [], [], []
    for i in cuts:
        k = np.arange(i + 1, n_rows)
        run.append(np.repeat(np.arange(R), len(k))); cut.append(np.full(R * len(k), i)); tgt.append(np.tile(k, R))
    return np.concatenate(run), np.concatenate(cut), np.concatenate(tgt)


def fit_ridge(data: Data, alpha: float = 1.0, seed: int = 0) -> list[np.ndarray]:
    run, cut, tgt = pairs(len(data.seed), data.n_rows)
    if len(run) > MAX_RIDGE_PAIRS:  # xp2: subsample (xp1's 642k pairs are all used)
        keep = np.sort(np.random.default_rng(seed).choice(len(run), MAX_RIDGE_PAIRS, replace=False))
        run, cut, tgt = run[keep], cut[keep], tgt[keep]
    F = ridge_features(data, cut, tgt, run)
    F = np.concatenate([F, np.ones((len(F), 1))], 1)
    Y, M = data.Y.numpy()[run, tgt], data.Ymask.numpy()[run, tgt]
    coefs = []
    for c in range(2):
        keep = M[:, c] > 0
        A = F[keep]
        coefs.append(np.linalg.solve(A.T @ A + alpha * np.eye(A.shape[1]), A.T @ Y[keep, c]))
    return coefs


def predict_ridge(coefs: list[np.ndarray], data: Data, run, cut, tgt) -> np.ndarray:
    F = ridge_features(data, cut, tgt, run)
    F = np.concatenate([F, np.ones((len(F), 1))], 1)
    return np.clip(np.stack([F @ c for c in coefs], 1), 0, 1)


# ----------------------------------------------------------------------------- check 1
def eval_cuts(data: Data) -> np.ndarray:
    n_cuts = data.n_rows - 1
    return np.arange(0, n_cuts, max(1, n_cuts // 50))  # xp1: every cut; xp2: every 5th


def check1(model: OutcomeGRU, ridge: list, train: Data, test: Data, device) -> pd.DataFrame:
    cuts = eval_cuts(test)
    pred = predict_cuts(model, test, torch.as_tensor(cuts), device)  # (R, C, S, 2)
    run, cut, tgt = pairs(len(test.seed), test.n_rows, cuts)
    pos = np.searchsorted(cuts, cut)
    gru = pred[run, pos, tgt - cut - 1]
    lin = predict_ridge(ridge, test, run, cut, tgt)
    # Defense-mean trajectory (schedule- and history-blind): mean over train runs with the same defense.
    Ytr, Mtr = train.Y.numpy(), train.Ymask.numpy()
    mean_traj = {d: np.nansum(Ytr[train.defense == d] * Mtr[train.defense == d], 0)
                 / Mtr[train.defense == d].sum(0).clip(1) for d in set(train.defense)}
    dmean = np.stack([mean_traj[test.defense[r]][k] for r, k in zip(run, tgt)])
    # Oracle persistence: true Y at the cut carried forward (uses unobservable Y; reference only).
    Y, M = test.Y.numpy(), test.Ymask.numpy()
    oracle = Y[run, cut]
    truth, mask = Y[run, tgt], M[run, tgt] * M[run, cut]
    h = tgt - cut
    rows = []
    for c, y in enumerate(Y_COLS):
        for name, p in [("GRU", gru), ("ridge (direct, W-aware)", lin), ("defense-mean trajectory", dmean),
                        ("oracle persistence (true Y_b)", oracle)]:
            for hz in ["all", *horizons(test.n_blocks)]:
                sel = mask[:, c] > 0
                if hz != "all":
                    sel &= h == hz
                if not sel.any():
                    continue
                err = p[sel, c] - truth[sel, c]
                rows.append({"outcome": y, "model": name, "horizon": hz, "rmse": np.sqrt(np.mean(err**2)),
                             "mae": np.mean(np.abs(err)), "n": int(sel.sum())})
    return pd.DataFrame(rows)


# ----------------------------------------------------------------------------- check 2 (xp1)
def implied_effects(model: OutcomeGRU, data: Data, device) -> np.ndarray:
    """(R, n_blocks, 2): predicted Y at block b with W_b=1 minus W_b=0, from history up to block b-1."""
    with torch.no_grad():
        h = model.encode(data.enc.to(device))[:, : data.n_rows - 1]  # history rows 0..i -> predicts row i+1
        R, C, H = h.shape
        out = []
        for w in (1.0, 0.0):
            Wf = np.full((R, data.n_rows), w)
            x = data.dec_inputs(Wf).to(device)  # step input for row i+1 is x[:, i]
            out.append(model.decode(h.reshape(R * C, H), x.reshape(R * C, 1, -1)).reshape(R, C, 2))
    return (out[0] - out[1]).cpu().numpy()


def check2(model: OutcomeGRU, df: pd.DataFrame, test: Data, device, out: Path, n_boot: int) -> pd.DataFrame:
    eff = implied_effects(model, test, device)
    rng = np.random.default_rng(0)
    rows = []
    for c, y in enumerate(Y_COLS):
        _, phase, _ = analyze.q1(df, y, n_boot, rng)  # randomized estimate, all 20 seeds
        for (a, d), g in phase.groupby(["attack", "defense"]):
            sel = (test.attack == a) & (test.defense == d)
            gru = eff[sel, :, c].mean(0).reshape(5, -1).mean(1)
            for _, r in g.iterrows():
                rows.append({"outcome": y, "attack": a, "defense": d, "phase": r.phase, "randomized": r.effect,
                             "lo": r.lo, "hi": r.hi, "gru": gru[int(r.phase) - 1]})
    t = pd.DataFrame(rows)
    t["inside_ci"] = (t.gru >= t.lo) & (t.gru <= t.hi)
    fig, axes = plt.subplots(1, 2, figsize=(11, 4.6))
    for ax, y in zip(axes, Y_COLS):
        s = t[t.outcome == y]
        lim = [min(s.lo.min(), s.gru.min()) * 100 - 1, max(s.hi.max(), s.gru.max()) * 100 + 1]
        ax.plot(lim, lim, color=INK2, linewidth=0.8)
        for d in DEFENSES:
            q = s[s.defense == d]
            ax.errorbar(q.gru * 100, q.randomized * 100, yerr=[(q.randomized - q.lo) * 100, (q.hi - q.randomized) * 100],
                        fmt="o", markersize=4, color=SERIES[d], elinewidth=0.8, label=d)
        r = np.corrcoef(s.gru, s.randomized)[0, 1]
        ax.set_title(f"{analyze.OUTCOMES[y]}: r = {r:.2f}, GRU inside 95% CI in {100 * s.inside_ci.mean():.0f}% "
                     f"of {len(s)} cells", color=INK, loc="left")
        ax.set_xlabel("GRU-implied effect, test seeds (pts per defended block)")
        ax.set_ylabel("randomized estimate, 95% CI (pts)")
    axes[0].legend(fontsize=8, ncol=2)
    fig.suptitle("Check 2: one-step effect of W per (attack, defense, phase) — GRU vs randomized estimate",
                 fontsize=9, color=INK, x=0.01, ha="left")
    fig.tight_layout()
    fig.savefig(out / "check2_effects.png", dpi=130)
    plt.close(fig)
    return t


def is_xp1_shaped(df: pd.DataFrame, data: Data) -> bool:
    return data.n_blocks == 50 and df.defense.nunique() > 1 and df.attack.nunique() > 1


# ----------------------------------------------------------------------------- check K (windowed attacks)
@torch.no_grad()
def check_kill(model: OutcomeGRU, data: Data, device, out: Path) -> pd.DataFrame:
    """For each test run with a windowed attack: history up to the attack's first block (detectable in X), then
    two plans: defend from the next block on, or never. Predicted backdoor success at the window end and at
    the run end, next to what the run's own schedule actually produced.

    The window is read from u_active, an evaluation label; it is never a model input.
    """
    if data.U is None:
        return pd.DataFrame()
    rows = []
    for r in range(len(data.seed)):
        if data.attack[r] not in ("backdoor_win", "backdoor_burst", "flip_win") or data.Ymask[r, :, 1].sum() == 0:
            continue
        active = np.flatnonzero(data.U[r] > 0)  # rows (block + 1)
        if len(active) == 0:
            continue
        first, last = int(active[0]), int(active[-1])
        h = model.encode(data.enc[r:r + 1, : first + 1].to(device))[:, -1]  # state after the first poisoned block
        preds = {}
        for name, w in [("defend", 1.0), ("never", 0.0)]:
            W = data.W[r:r + 1].copy()
            W[:, first + 1:] = w
            dec = data.dec_inputs(W, runs=slice(r, r + 1))[:, first:]  # rows first+1 .. n-1
            preds[name] = model.decode(h.expand(1, -1), dec.to(device))[0, :, 1].cpu().numpy()
        end_w = last - first - 1  # index of the window's last row in the decoded sequence
        W_true = data.W[r]
        on_rows = np.flatnonzero(W_true[first:] > 0)
        delay = int(on_rows[0]) if len(on_rows) else -1  # blocks after the attack's first block
        covered = len(on_rows) > 0 and bool((W_true[first + delay: last + 1] > 0).all())
        rows.append({
            "run_id": data.run_ids[r], "seed": int(data.seed[r]), "window_blocks": (first - 1, last - 1),
            "actual_delay_blocks": delay, "actual_covered_to_end": covered,
            "actual_atk_window_end": float(data.Y[r, last, 1]), "actual_atk_final": float(data.Y[r, -1, 1]),
            "gru_atk_window_end_if_defend": float(preds["defend"][max(end_w, 0)]),
            "gru_atk_window_end_if_never": float(preds["never"][max(end_w, 0)]),
            "gru_atk_final_if_defend": float(preds["defend"][-1]), "gru_atk_final_if_never": float(preds["never"][-1]),
        })
    t = pd.DataFrame(rows)
    if len(t):
        t.to_csv(out / "checkK_kill.csv", index=False)
    return t


# ----------------------------------------------------------------------------- check 3 (xp1)
def score_cf(model: OutcomeGRU, ridge: list, train: Data, cf_df: pd.DataFrame, xp1: pd.DataFrame,
             device, out: Path) -> dict:
    """Score predictions on true counterfactual runs. History = the run's own first CF_PREFIX blocks (observed)."""
    res: dict = {}
    # Reproduction check: cf 'random' runs must equal the xp1 runs with the same run_id.
    rand = cf_df[~cf_df.run_id.str.contains("__cf_")]
    if len(rand):
        merged = rand.merge(xp1, on=["run_id", "block"], suffixes=("", "_xp1"))
        cols = [c for c in [*X_COLS, *Y_COLS] if c in rand.columns]
        diffs = {c: float(np.nanmax(np.abs(merged[c] - merged[f"{c}_xp1"]))) for c in cols}
        res["reproduction"] = {"runs": int(rand.run_id.nunique()), "max_abs_diff": max(diffs.values()),
                               "per_column": diffs}
    data = Data(cf_df[cf_df.run_id.str.contains("__cf_")], train.x_mean, train.x_std)
    n = data.n_rows
    sched = pd.Series(data.run_ids).str.extract(r"__cf_(\w+?)_p\d+__")[0].to_numpy()
    cut = CF_PREFIX  # rows 0..3 = blocks -1..2 observed
    with torch.no_grad():
        h = model.encode(data.enc[:, : cut + 1].to(device))[:, -1]
        pred = model.decode(h, data.dec_inputs(data.W)[:, cut:].to(device)).cpu().numpy()  # rows cut+1..n-1
    run, tgt = np.repeat(np.arange(len(data.seed)), n - 1 - cut), np.tile(np.arange(cut + 1, n), len(data.seed))
    lin = predict_ridge(ridge, data, run, np.full(len(run), cut), tgt).reshape(len(data.seed), -1, 2)
    Y, M = data.Y.numpy()[:, cut + 1:], data.Ymask.numpy()[:, cut + 1:]
    rows = []
    for r in range(len(data.seed)):
        for c, y in enumerate(Y_COLS):
            if M[r, -1, c] == 0:
                continue
            rows.append({"run_id": data.run_ids[r], "attack": data.attack[r], "defense": data.defense[r],
                         "seed": data.seed[r], "schedule": sched[r], "outcome": y,
                         "true_final": Y[r, -1, c], "gru_final": pred[r, -1, c], "ridge_final": lin[r, -1, c],
                         "gru_rmse_traj": float(np.sqrt(np.mean((pred[r, :, c] - Y[r, :, c]) ** 2))),
                         "ridge_rmse_traj": float(np.sqrt(np.mean((lin[r, :, c] - Y[r, :, c]) ** 2)))})
    t = pd.DataFrame(rows)
    t.to_csv(out / "check3_counterfactual.csv", index=False)
    # Ranking: per (seed, attack, defense, outcome), do predicted finals order the 5 schedules like the truth?
    rank = []
    for key, g in t.groupby(["seed", "attack", "defense", "outcome"]):
        if g.true_final.nunique() > 1:
            rank.append({"outcome": key[3], "attack": key[1], "defense": key[2],
                         "gru_spearman": g.true_final.rank().corr(g.gru_final.rank()),
                         "ridge_spearman": g.true_final.rank().corr(g.ridge_final.rank())})
    res["ranking"] = pd.DataFrame(rank).groupby(["outcome", "attack"])[["gru_spearman", "ridge_spearman"]].mean() \
        .round(3).reset_index().to_dict("records") if rank else []
    res["final_error"] = t.groupby(["outcome", "schedule"]).apply(
        lambda g: pd.Series({"true": g.true_final.mean(), "gru": g.gru_final.mean(), "ridge": g.ridge_final.mean(),
                             "gru_mae": (g.gru_final - g.true_final).abs().mean(),
                             "ridge_mae": (g.ridge_final - g.true_final).abs().mean()})).round(3) \
        .reset_index().to_dict("records")
    return res


# ----------------------------------------------------------------------------- support diagnostic
def support(df: pd.DataFrame) -> dict:
    """How long the defended stretches in the training schedules are (the GRU's training support)."""
    W = df[df.block >= 0].sort_values(["run_id", "block"]).groupby("run_id").W.apply(lambda s: [int(v) for v in s])
    n_blocks = len(W.iloc[0])
    longest_on = W.apply(lambda w: max(len(m) for m in re.findall("1+", "".join(map(str, w))) or [""]))
    first_off = W.apply(lambda w: w.index(0) if 0 in w else len(w))
    return {"runs": int(len(W)), "n_blocks": n_blocks, "longest_defended_streak_max": int(longest_on.max()),
            "longest_defended_streak_median": float(longest_on.median()),
            "first_undefended_block_median": float(first_off.median()),
            "runs_with_defended_streak_over_20pct": int((longest_on >= n_blocks // 5).sum())}


# ----------------------------------------------------------------------------- main
def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--runs", type=Path, default=Path("results/xp1/results_collect/runs/all_blocks.csv"))
    ap.add_argument("--out", type=Path, default=Path("results/xp1/gru"))
    ap.add_argument("--cf", type=Path, help="all_blocks.csv of the counterfactual runs (check 3)")
    ap.add_argument("--retrain", action="store_true", help="overwrite the frozen gru.pt (never with --cf)")
    ap.add_argument("--epochs", type=int, default=300)
    ap.add_argument("--hidden", type=int, default=64)
    ap.add_argument("--cuts-per-batch", type=int, default=CUTS_PER_BATCH)
    ap.add_argument("--seed", type=int, default=0)
    ap.add_argument("--boot", type=int, default=500)
    ap.add_argument("--lr", type=float, default=2e-3)
    ap.add_argument("--wd", type=float, default=0.0, help="AdamW weight decay (0 = Adam, as in xp1/xp2)")
    ap.add_argument("--patience", type=int, default=25)
    args = ap.parse_args()
    if args.cf and args.retrain:
        raise SystemExit("--retrain with --cf would score check 3 with a model fitted after the runs existed.")
    sys.stdout.reconfigure(encoding="utf-8")
    args.out.mkdir(parents=True, exist_ok=True)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")

    df = analyze.load(args.runs)
    split = assign_splits(df)
    train = Data(df[split == "train"])
    val = Data(df[split == "val"], train.x_mean, train.x_std)
    test = Data(df[split == "test"], train.x_mean, train.x_std)
    print(f"runs: train {len(train.seed)}, val {len(val.seed)}, test {len(test.seed)}; "
          f"{train.n_blocks} blocks per run; device {device}", flush=True)

    weights = args.out / "gru.pt"
    model = OutcomeGRU(train.enc.shape[-1], train.dec_inputs(train.W).shape[-1], args.hidden).to(device)
    if weights.exists() and not args.retrain:
        # Frozen model (check 3 must use the model trained BEFORE the counterfactual runs existed).
        model.load_state_dict(torch.load(weights, map_location=device))
        model.eval()
        history = json.loads((args.out / "report.json").read_text())["val_history"]
    elif args.cf:
        raise SystemExit(f"No frozen model at {weights}: train it first (without --cf).")
    else:
        model, history = fit_gru(train, val, device, args.epochs, args.hidden, args.seed, args.cuts_per_batch,
                                 args.lr, args.wd, args.patience)
        model.eval()
        torch.save(model.state_dict(), weights)
    weights_sha = hashlib.sha256(weights.read_bytes()).hexdigest()[:16]
    print(f"model: {len(history)} epochs, best val MSE {min(history):.5f}, weights sha256 {weights_sha}", flush=True)
    ridge = fit_ridge(train)

    c1 = check1(model, ridge, train, test, device)
    c1.to_csv(args.out / "check1_prediction.csv", index=False)
    report = {"weights_sha256": weights_sha, "n_blocks": train.n_blocks, "support": support(df),
              "hparams": {"hidden": args.hidden, "lr": args.lr, "wd": args.wd, "patience": args.patience,
                          "cuts_per_batch": args.cuts_per_batch, "seed": args.seed},
              "epochs": len(history), "best_val_mse": min(history), "val_history": history}
    c2 = check2(model, df, test, device, args.out, args.boot) if is_xp1_shaped(df, test) else None
    if c2 is not None:
        c2.to_csv(args.out / "check2_effects.csv", index=False)
    ck = check_kill(model, test, device, args.out)
    if args.cf:
        report["check3"] = score_cf(model, ridge, train, analyze.load(args.cf), df, device, args.out)
    (args.out / ("report_cf.json" if args.cf else "report.json")).write_text(json.dumps(report, indent=2, default=float))

    print("\n## Check 1: test-seed prediction error (RMSE, accuracy units)")
    print(c1.pivot_table(index=["outcome", "model"], columns="horizon", values="rmse", sort=False).round(4).to_string())
    if c2 is not None:
        print("\n## Check 2: GRU-implied one-step effect vs randomized estimate")
        for y, s in c2.groupby("outcome"):
            print(f"{y}: corr {np.corrcoef(s.gru, s.randomized)[0, 1]:.3f}, inside 95% CI "
                  f"{100 * s.inside_ci.mean():.0f}% of {len(s)} cells")
    if len(ck):
        killed = (ck.actual_atk_window_end < 0.1)
        print(f"\n## Check K: kill awareness on {len(ck)} windowed test runs")
        print(f"predicted backdoor at window end if defending from the attack's 2nd block: "
              f"mean {ck.gru_atk_window_end_if_defend.mean():.3f}; if never defending: "
              f"mean {ck.gru_atk_window_end_if_never.mean():.3f}")
        print(f"actual: {int(killed.sum())} runs killed (backdoor < 0.1 at window end), {int((~killed).sum())} not")
    print("\n## Training support")
    print(json.dumps(report["support"], indent=2))
    if "check3" in report:
        print("\n## Check 3")
        print(json.dumps(report["check3"], indent=2, default=float))


if __name__ == "__main__":
    main()
__CPC_DP_EOF__
cat > deploy_xp7.py <<'__CPC_DP_EOF__'
"""xp7 deployment: the trained models as Krum controllers on new seeds (layout of GRU_mnist/deploy_xp5.py).

    ../.venv/Scripts/python xp7/deploy_xp7.py --models gru_g0=g0/gru cpc_g0=g0/A0 ...   # -> results/xp7/deploy/
    ../.venv/Scripts/python xp7/deploy_xp7.py --report-only
    ../.venv/Scripts/python xp7/deploy_xp7.py --smoke --models ...                       # 30 blocks, 2 environments

Environments (Fashion-MNIST, Krum, 250 blocks of 2 rounds; 3 new seeds each: k = 0 early window, k = 1, 2 later;
persistent: from block 1-10 to the end): the xp7 families (corner 2/8, patch 8/8, flip 8/8, ALIE, SignFlip 4.6,
no attack) and persistent corner 2/8, patch 8/8, ALIE.
Policies (same seed = same data and noise):
    clean_ref   no attack, never defend (ALIE / SignFlip only: their harm = clean accuracy lost against it)
    off / on    never / always defend
    oracle      defends exactly the attack's active blocks (knows the attack: reference only)
    alarm       the xp6 alarm rule alarm_t3.67_d0_h20 (the xp5 deployment threshold, hold 20 blocks)
    <model>     each block b: predicted gain of 'Krum on over [b, b + 20), then off' over 'off from b', whole-run
                utility (mean of clean - atk over blocks b..T); defend iff gain > margin (0 by default; --margin val: validation twins)
"""

import argparse
import json
import sys
import time
from concurrent.futures import ProcessPoolExecutor, as_completed
from multiprocessing import get_context
from pathlib import Path
from types import SimpleNamespace

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402
import torch  # noqa: E402
from matplotlib.lines import Line2D  # noqa: E402
from matplotlib.patches import Patch  # noqa: E402

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent if HERE.name in ("xp6", "xp7") else HERE  # local: CPC_DP/xp7/; Kaggle: files flat in $WORK
sys.path.insert(0, str(ROOT))
from cpc import _GRU  # noqa: E402,F401
from cpc.data import RunData  # noqa: E402
from cpc.evaluate import CPCPredictor, GRUPredictor  # noqa: E402
from cpc.train import load  # noqa: E402
from cpc.xp7data import signed_log  # noqa: E402
import poison_testbed  # noqa: E402,F401
from analyze import INK, INK2, SURFACE  # noqa: E402
from gru_experiment import OutcomeGRU  # noqa: E402
from poison_testbed.runner import RunConfig, simulate  # noqa: E402
from run_experiment import xp5_params  # noqa: E402
from xp7 import SIGNFLIP_SCALE  # noqa: E402

MODELS = ROOT / "results/xp7/models"
SCORES = ROOT / "results/xp7/scores/summary.csv"
OUT = ROOT / "results/xp7/deploy"
N_BLOCKS, HORIZON, LAMBDA, SEED0 = 250, 20, 1.0, 60_000
ALARM = "alarm_t3.67_d0_h20"
ENVIRONMENTS = {  # name -> (RunConfig fields, persistent)
    "corner 2/8": (dict(attack="backdoor_win", trigger="corner", poison_frac=0.25), False),
    "patch 8/8": (dict(attack="backdoor_win", trigger="patch_r3_c5", poison_frac=1.0), False),
    "flip 8/8": (dict(attack="flip_win", poison_frac=1.0, flip_source=1), False),
    "ALIE": (dict(attack="alie_win"), False),
    "SignFlip": (dict(attack="sign_flip_win", sign_flip_scale=SIGNFLIP_SCALE), False),
    "no attack": (dict(attack="none"), False),
    "corner 2/8 persistent": (dict(attack="backdoor_win", trigger="corner", poison_frac=0.25), True),
    "patch 8/8 persistent": (dict(attack="backdoor_win", trigger="patch_r3_c5", poison_frac=1.0), True),
    "ALIE persistent": (dict(attack="alie_win"), True),
}
GRADIENT = ("alie_win", "sign_flip_win")
FIXED = ["clean_ref", "off", "on", "oracle", "alarm"]
COLOR = {"clean_ref": "#52514e", "off": "#1baf7a", "on": "#eb6834", "oracle": "#e87ba4", "alarm": "#008300"}
MODEL_COLORS = ["#2a78d6", "#104281", "#9ec2ee", "#7b4fc9", "#c94f9b", "#8a94a6"]
SEEDS = 3


def environment(env: str, k: int, smoke: bool) -> tuple[int, tuple[int, int], int]:
    seed = SEED0 + 100 * list(ENVIRONMENTS).index(env) + k
    rng = np.random.default_rng(91_000 + seed)
    target = int(rng.choice([0, 3, 7]))
    n = 30 if smoke else N_BLOCKS
    if smoke:
        return seed, (5, 20), target
    if ENVIRONMENTS[env][1]:
        return seed, (int(rng.integers(1, 11)), n - 1), target
    start = int(rng.integers(2, 21)) if k == 0 else int(rng.integers(40, 151))
    return seed, (start, start + int(rng.integers(30, 81)) - 1), target


def config(env: str, policy: str, k: int, smoke: bool) -> RunConfig:
    fields = dict(ENVIRONMENTS[env][0])
    seed, window, target = environment(env, k, smoke)
    if policy == "clean_ref":
        fields, schedule = {"attack": "none"}, "off"
    elif policy in ("off", "on"):
        schedule = policy
    elif policy == "oracle":
        schedule = "oracle" if fields["attack"] != "none" else "off"
    elif policy == "alarm":
        schedule = ALARM
    else:
        schedule = "policy"
    over = {"n_blocks": 30} if smoke else {}
    return RunConfig(defense="Krum", seed=seed, schedule=schedule, window=window, target=target, **fields,
                     **xp5_params(over))


# ----------------------------------------------------------------------------- model controller
class ModelPolicy:
    """Defend at block b iff the model's predicted whole-run gain of 'on for H blocks' over 'off' > margin."""

    def __init__(self, folder: Path, margin: float, device: str, n_blocks: int):
        rep = json.loads((folder / "report.json").read_text())
        norm = np.load(folder / "norm.npz")
        self.device, self.n_blocks, self.margin = device, n_blocks, margin
        if rep["model"] == "gru":
            x_cols = rep["x_cols"]
        else:
            x_cols = json.loads((folder / "config.json").read_text())["x_cols"]
        self.ref = SimpleNamespace(x_cols=x_cols, d=SimpleNamespace(x_mean=norm["x_mean"], x_std=norm["x_std"]))
        probe = self._data([{"run_id": "p", "seed": 0, "defense": "Krum", "block": -1, "W": np.nan}])
        if rep["model"] == "gru":
            m = OutcomeGRU(probe.d.enc.shape[-1], probe.d.dec_inputs(probe.d.W).shape[-1], rep["hparams"]["hidden"])
            m.load_state_dict(torch.load(folder / "gru.pt", map_location=device))
            self.pred = GRUPredictor(m.to(device).eval(), device)
        else:
            self.pred = CPCPredictor(load(folder, device)[0], device)

    def _data(self, history: list[dict]) -> RunData:
        df = pd.DataFrame(history)
        last = int(df.block.max())
        pad = pd.DataFrame([{"run_id": df.run_id.iloc[0], "seed": df.seed.iloc[0], "defense": "Krum", "block": b}
                            for b in range(last + 1, self.n_blocks)])
        df = pd.concat([df, pad], ignore_index=True)
        df["attack"] = "unknown"  # the controller never knows the attack
        for c in ["W", "y_clean_acc", "y_atk", *self.ref.x_cols]:
            if c not in df:
                df[c] = np.nan
        df[self.ref.x_cols] = signed_log(df[self.ref.x_cols].to_numpy(float))
        df["W"] = pd.to_numeric(df.W, errors="coerce")
        return RunData(df, ref=self.ref)

    def __call__(self, history: list[dict], b: int) -> tuple[int, dict]:
        rd = self._data(history)
        n = rd.n_rows
        h = min(HORIZON, self.n_blocks - b)
        plans = rd.W[0].clone().expand(2, -1).clone()  # rows 0..b = the realised past W (row b = block b-1)
        plans[:, b + 1:] = 0
        plans[1, b + 1:b + 1 + h] = 1
        y = self.pred.plans(rd, 0, b, plans).numpy()  # (2, n-1-b, 2): rows b+1 .. n-1
        u = (y[..., 0] - LAMBDA * y[..., 1]).mean(1)
        gain = float(u[1] - u[0])
        assert y.shape[1] == n - 1 - b
        return int(gain > self.margin), {"gain": gain}


# ----------------------------------------------------------------------------- runs
def run_one(env: str, policy: str, k: int, ctx: dict) -> pd.DataFrame:
    smoke = ctx["smoke"]
    cfg = config(env, policy, k, smoke)
    out = OUT / ("runs_smoke" if smoke else "runs") / f"{env.replace(' ', '_').replace('/', 'of')}__{policy}__s{cfg.seed}"
    meta = {"config": json.loads(json.dumps(cfg.__dict__, default=str)), "model": ctx["models"].get(policy)}
    if (out / "blocks.csv").exists() and json.loads((out / "meta.json").read_text()).get("key") == meta:
        return pd.read_csv(out / "blocks.csv", low_memory=False)
    controller = None
    if policy in ctx["models"]:
        spec = ctx["models"][policy]
        controller = ModelPolicy(MODELS / spec["folder"], spec["margin"], cfg.device, cfg.n_blocks)
    t0 = time.time()
    df = simulate(cfg, controller).copy()
    df.insert(0, "environment", env)
    df.insert(1, "policy", policy)
    df["k"] = k
    df["window_start"], df["window_end"] = cfg.window
    out.mkdir(parents=True, exist_ok=True)
    df.to_csv(out / "blocks.csv", index=False)
    (out / "meta.json").write_text(json.dumps({"key": meta, "wall_clock_s": round(time.time() - t0, 1)}, indent=1))
    return df


def summarize(blocks: pd.DataFrame) -> tuple[pd.DataFrame, pd.DataFrame]:
    ref = blocks[(blocks.policy == "clean_ref") & (blocks.block >= 0)].set_index(["seed", "block"]).y_clean_acc
    rows = []
    for (env, pol, seed), g in blocks[blocks.policy != "clean_ref"].groupby(["environment", "policy", "seed"]):
        tr = g[g.block >= 0].sort_values("block")
        w = tr.W.astype(float).to_numpy()
        active = tr.u_active.to_numpy().astype(bool)
        attack = tr.attack.iloc[0]
        targeted = attack in ("backdoor_win", "flip_win")
        atk = tr.y_atk.to_numpy(float) if targeted else np.zeros(len(tr))
        s = int(tr.window_start.iloc[0])
        on_after = np.flatnonzero(w[s:]) if attack != "none" else []
        r = ref.reindex(list(zip(tr.seed, tr.block))).to_numpy() if attack in GRADIENT else np.full(len(tr), np.nan)
        rows.append({
            "environment": env, "policy": pol, "seed": seed,
            "utility": float(np.mean(tr.y_clean_acc.to_numpy() - LAMBDA * atk)),
            "final_clean_acc": float(tr.y_clean_acc.iloc[-1]), "mean_clean_acc": float(tr.y_clean_acc.mean()),
            "mean_attack_success_active": float(atk[active].mean()) if targeted and active.any() else np.nan,
            "final_attack_success": float(atk[-1]) if targeted else np.nan,
            "clean_lost_vs_no_attack": float(np.nanmean(r - tr.y_clean_acc.to_numpy())) if attack in GRADIENT else np.nan,
            "defended_blocks": int(w.sum()), "defended_while_active": int(w[active].sum()),
            "false_alarm_blocks": int(w[~active].sum()),
            "reaction_delay_blocks": int(on_after[0]) if len(on_after) else np.nan,
        })
    per_run = pd.DataFrame(rows)
    orc = per_run[per_run.policy == "oracle"].set_index(["environment", "seed"]).utility
    per_run["utility_vs_oracle"] = per_run.utility - orc.reindex(list(zip(per_run.environment, per_run.seed))).to_numpy()
    cols = ["utility", "utility_vs_oracle", "final_clean_acc", "mean_clean_acc", "mean_attack_success_active",
            "final_attack_success", "clean_lost_vs_no_attack", "defended_blocks", "false_alarm_blocks",
            "reaction_delay_blocks"]
    agg = per_run.groupby(["environment", "policy"], sort=False)[cols].mean().round(4).reset_index()
    return per_run, agg


# ----------------------------------------------------------------------------- figures
def colors(policies: list[str]) -> dict:
    c = dict(COLOR)
    for i, p in enumerate([p for p in policies if p not in COLOR]):
        c[p] = MODEL_COLORS[i % len(MODEL_COLORS)]
    return c


def fig_environment(blocks: pd.DataFrame, env: str, policies: list[str], out: Path) -> None:
    g = blocks[(blocks.environment == env) & (blocks.block >= 0)].copy()
    col = colors(policies)
    gradient = g.attack.isin(GRADIENT).any()
    ref = g[g.policy == "clean_ref"].set_index(["seed", "block"]).y_clean_acc
    g["harm"] = (ref.reindex(list(zip(g.seed, g.block))).to_numpy() - g.y_clean_acc) if gradient else g.y_atk
    seeds = sorted(g.seed.unique())
    deciders = [p for p in policies if p not in ("clean_ref", "off", "on")]
    fig, axes = plt.subplots(3, len(seeds), figsize=(3.9 * len(seeds) + 0.6, 8.8), sharex=True, squeeze=False,
                             gridspec_kw={"height_ratios": [1, 1, 0.75]})
    no_attack = env == "no attack"
    for j, seed in enumerate(seeds):
        s = g[g.seed == seed]
        first = s[s.policy == "off"].sort_values("block")
        active = first.u_active.to_numpy().astype(bool)
        for i, (c, label) in enumerate([("harm", "clean acc. lost vs no attack" if gradient else "attack success"),
                                        ("y_clean_acc", "clean accuracy")]):
            ax = axes[i, j]
            if not no_attack:
                for b in np.flatnonzero(active):
                    ax.axvspan(b - 0.5, b + 0.5, color=INK2, alpha=0.08, linewidth=0)
            for p in policies:
                if p == "clean_ref" and (c == "harm" or not gradient):
                    continue
                q = s[s.policy == p].sort_values("block")
                ax.plot(q.block, q[c], color=col[p], linewidth=1.8 if p not in FIXED else 1.1,
                        zorder=3 if p not in FIXED else 2)
            if i == 0:
                ws, we = int(first.window_start.iloc[0]), int(first.window_end.iloc[0])
                ttl = f"seed {seed}: " + ("no attack" if no_attack else f"attack {ws}-{we}")
                ax.set_title(ttl, color=INK, fontsize=9)
                if not gradient:
                    ax.set_ylim(-0.03, 1.03)
            else:
                ax.set_ylim(0.4 if not gradient else 0.0, 0.9)
            if j == 0:
                ax.set_ylabel(label)
        ax = axes[2, j]
        for r_, p in enumerate(deciders):
            q = s[s.policy == p].sort_values("block")
            on = q.block[q.W.astype(float) == 1].to_numpy()
            ax.broken_barh([(b - 0.5, 1) for b in on], (r_ - 0.35, 0.7), color=col[p], linewidth=0)
        ax.set_yticks(range(len(deciders)), deciders if j == 0 else [])
        ax.set_ylim(-0.6, len(deciders) - 0.4)
        ax.invert_yaxis()
        ax.grid(False)
        ax.set_xlabel("block (2 SGD steps each)")
    axes[2, 0].set_ylabel("Krum on")
    handles = [Line2D([], [], color=col[p], linewidth=1.8 if p not in FIXED else 1.2, label=p) for p in policies
               if not (p == "clean_ref" and not gradient)]
    if not no_attack:
        handles.append(Patch(color=INK2, alpha=0.15, label="attack active"))
    fig.suptitle(f"xp7 deployment (Fashion-MNIST, Krum): {env}: trajectories and Krum decisions (same seed = same data "
                 f"and noise)", fontsize=10, color=INK, x=0.01, y=0.995, ha="left")
    top = 1 - 0.8 / fig.get_figheight()
    fig.legend(handles=handles, loc="upper left", bbox_to_anchor=(0.01, top + 0.045), ncol=6, fontsize=8)
    fig.tight_layout(rect=(0, 0, 1, top - 0.035))
    fig.savefig(out / f"trajectory_{env.replace(' ', '_').replace('/', 'of')}.png", dpi=120)
    plt.close(fig)


def fig_summary(per_run: pd.DataFrame, policies: list[str], out: Path) -> None:
    envs = [e for e in ENVIRONMENTS if e in set(per_run.environment)]
    pols = [p for p in policies if p != "clean_ref"]
    col = colors(policies)
    panels = [("utility_vs_oracle", "utility − oracle's\n(mean over the run of clean − attack success)"),
              ("mean_clean_acc", "mean clean accuracy"),
              ("defended_blocks", "blocks with Krum on")]
    fig, axes = plt.subplots(len(panels), 1, figsize=(15, 10), sharex=True)
    width = 0.84 / len(pols)
    for ax, (c, label) in zip(axes, panels):
        for e_i, env in enumerate(envs):
            for k, pol in enumerate(pols):
                v = per_run[(per_run.environment == env) & (per_run.policy == pol)][c].to_numpy(float)
                if not len(v):
                    continue
                x = e_i - 0.42 + width * (k + 0.5)
                ax.scatter(np.full(len(v), x), v, s=14, color=col[pol], edgecolor=SURFACE, linewidth=0.6, zorder=3)
                ax.plot([x - width * 0.4, x + width * 0.4], [np.nanmean(v)] * 2, color=col[pol], linewidth=2.2)
        ax.set_ylabel(label, fontsize=8)
    axes[-1].set_xticks(range(len(envs)), [e.replace(" persistent", "\npersistent") for e in envs], fontsize=8)
    handles = [Line2D([], [], color=col[q], marker="o", linewidth=2, label=q) for q in pols]
    fig.legend(handles=handles, loc="upper left", bbox_to_anchor=(0.01, 0.955), ncol=8, fontsize=8)
    fig.suptitle("xp7 deployment summary (dots = seeds, bar = mean)", fontsize=10, color=INK, x=0.01, y=0.995, ha="left")
    fig.tight_layout(rect=(0, 0, 1, 0.92))
    fig.savefig(out / "summary_by_policy.png", dpi=120)
    plt.close(fig)


def report(blocks: pd.DataFrame, policies: list[str], out: Path) -> None:
    per_run, agg = summarize(blocks)
    per_run.to_csv(out / "per_run.csv", index=False)
    agg.to_csv(out / "summary.csv", index=False)
    for env in blocks.environment.unique():
        fig_environment(blocks, env, policies, out)
    fig_summary(per_run, policies, out)
    pd.set_option("display.width", 220)
    print(agg.pivot_table(index="environment", columns="policy", values="utility_vs_oracle", sort=False).round(3)
          .to_string())
    print("\nmean over environments (utility - oracle):")
    print(per_run.groupby("policy").utility_vs_oracle.mean().round(4).sort_values(ascending=False).to_string())


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--models", nargs="*", default=[], metavar="NAME=LEVEL/MODEL")
    ap.add_argument("--smoke", action="store_true")
    ap.add_argument("--jobs", type=int, default=1, help="parallel runs (separate processes)")
    ap.add_argument("--report-only", action="store_true")
    ap.add_argument("--margin", choices=["zero", "val"], default="zero",
                    help="zero: defend iff predicted gain > 0 (default). val: margin from the validation twins; those "
                         "sit at attack onsets, so it pushes towards always defending")
    args = ap.parse_args()
    scores = pd.read_csv(SCORES) if SCORES.exists() else pd.DataFrame(columns=["level", "model", "margin"])
    models = {}
    for spec in args.models:
        name, folder = spec.split("=")
        level, model = folder.split("/")
        row = scores[(scores.level == level) & (scores.model == model)]
        margin = float(row.margin.iloc[0]) if (len(row) and args.margin == "val") else 0.0
        models[name] = {"folder": folder, "margin": margin}
    policies = FIXED + list(models)
    ctx = {"smoke": args.smoke, "models": models}
    out = OUT / ("smoke" if args.smoke else "")
    out.mkdir(parents=True, exist_ok=True)
    envs = ["corner 2/8", "ALIE"] if args.smoke else list(ENVIRONMENTS)
    seeds = 1 if args.smoke else SEEDS
    jobs = [(e, p, k) for e in envs for k in range(seeds) for p in policies
            if not (p == "clean_ref" and ENVIRONMENTS[e][0]["attack"] not in GRADIENT)]
    if args.report_only:
        frames = [pd.read_csv(f, low_memory=False) for f in (OUT / ("runs_smoke" if args.smoke else "runs")).glob("*/blocks.csv")]
    else:
        frames, t0 = [], time.time()
        if args.jobs <= 1:
            for i, (e, p, k) in enumerate(jobs):
                frames.append(run_one(e, p, k, ctx))
                print(f"[{i + 1}/{len(jobs)}] {e} | {p} | k={k}  (elapsed {time.time() - t0:.0f}s)", flush=True)
        else:
            with ProcessPoolExecutor(max_workers=args.jobs, mp_context=get_context("spawn")) as pool:
                futs = {pool.submit(run_one, e, p, k, ctx): (e, p, k) for e, p, k in jobs}
                for i, fut in enumerate(as_completed(futs)):
                    frames.append(fut.result())
                    e, p, k = futs[fut]
                    print(f"[{i + 1}/{len(jobs)}] {e} | {p} | k={k}  (elapsed {time.time() - t0:.0f}s)", flush=True)
    (out / "models.json").write_text(json.dumps(models, indent=1))
    report(pd.concat(frames, ignore_index=True), policies, out)
    print(f"saved {out}")


if __name__ == "__main__":
    main()
__CPC_DP_EOF__
cat > xp8.py <<'__CPC_DP_EOF__'
"""xp8: paired branches for learning WHEN to switch Krum on (decision at step t uses step t's own gradients).

    ../.venv/Scripts/python xp8/xp8.py --list                    # plan tables and cost, run nothing
    ../.venv/Scripts/python xp8/xp8.py --part 1 --jobs 4         # Kaggle session 1 -> results/xp8/part1/
    ../.venv/Scripts/python xp8/xp8.py --part 2 --jobs 4         # Kaggle session 2 -> results/xp8/part2/
    ../.venv/Scripts/python xp8/xp8.py --part 1 --smoke          # 6 setups of 40 steps (pipeline check)

Time: 1 block = 1 SGD step (block_len 1), T = 500 steps, as many SGD steps as xp1-xp7.

Order inside a step t (PoisoningSimulation.gather / apply):
  1. the 16 workers send their gradients; the signals of row t are computed from them (before any aggregation);
  2. the aggregator of step t is chosen (W_t = 1: Krum, 0: plain average): a controller may use row t's signals;
  3. aggregation and update; the outcomes of row t are measured on the updated model.
  x_val_acc_pre = validation accuracy of the model BEFORE step t (= the one measured after step t - 1): usable at t.
  Row -1 = the initial model (outcomes only).

Design (264 setups = 34 attack configurations x 6 seeds + 60 no-attack setups; CONFIGS, N_NONE):
- Attacks: backdoor corner and patch (poisoned share 2/8, 4/8, 8/8), targeted flip (4/8, 8/8), ALIE (z max / half
  max), SignFlip (scale 2 / 4.6); durations short (30 steps), long (120), persistent (to the end; not SignFlip);
  random onset. Attackers per setup: 1, 3 or 5 (ALIE: 3 or 5, as 1 attacker gives z_max = 0; SignFlip: 1 or 3).
  Krum always assumes f = 3. No attack: 60 setups.
- Each setup is run twice, Krum always off and always on (the two "trunks", same seed = same data and noise).
- Branches: at a few steps t, the trunk's full state is saved; the run is resumed from it with the defense
  flipped for K = 40 steps, then back to the trunk's setting until the end. Trunk vs branch = the true effect of
  switching on (off trunk) or off (on trunk) at t, at that exact history. Branch points: attack onset, onset + 10,
  onset + 30 and one quiet step (before the attack or well after it); no attack: 4 random steps.
- Splits by setup: per configuration, seed 0 -> test, seed 1 -> val, seeds 2-5 -> train. Branches of val / test
  setups are evaluation data, as the xp7 twins were.
- Two parts (two Kaggle sessions) of equal cost; every configuration has setups in both.

Output (per part): jobs/<job>.parquet (one per setup x trunk: the trunk rows, then each branch from its step t),
all_blocks.parquet (all jobs), manifest.csv (setups), jobs.csv (status, wall time, errors).
A job that crashes is recorded in jobs.csv and does not stop the others. Re-running a part skips finished jobs.
"""

from __future__ import annotations

import argparse
import copy
import json
import math
import sys
import time
import traceback
from concurrent.futures import FIRST_COMPLETED, ProcessPoolExecutor, wait
from multiprocessing import get_context
from pathlib import Path

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent if HERE.name == "xp8" else HERE  # local: CPC_DP/xp8/; Kaggle: files flat in $WORK
sys.path.insert(0, str(ROOT))
if (ROOT.parent / "GRU_mnist" / "run_experiment.py").exists():  # local layout; on Kaggle the files sit side by side
    sys.path.insert(0, str(ROOT.parent / "GRU_mnist"))

import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402
import torch  # noqa: E402

import run_experiment as R  # noqa: E402
from poison_testbed.runner import RunConfig, _outcomes, build  # noqa: E402
from poison_testbed.signals import X2_SIGNALS, X_COLUMNS  # noqa: E402

T, K = 500, 40
SEED0 = 90_000
N_SEEDS, N_NONE = 6, 60
SHORT, LONG = 30, 120
DURATIONS = ("short", "long", "persistent")
ATTACKERS = {"alie": (3, 5), "signflip": (1, 3)}  # others: (1, 3, 5)
RATE = 100.0  # run-equivalents (500 steps) per hour on Kaggle (xp7_deploy: 130 s per run at 4 jobs, + 10%)
SIGNALS = list(X_COLUMNS) + [f"x2_{s}" for s in X2_SIGNALS]
OUTCOMES = ["y_clean_acc", "y_clean_loss", "y_atk", "y_bd", "y_flip"]
COLUMNS = (["job", "setup", "trunk", "traj", "t_branch", "step", "W"] + SIGNALS + ["x_val_acc_pre"] + OUTCOMES
           + ["u_active"])


def _configs() -> list[dict]:
    """The 35 attack configurations (family, label, RunConfig fields)."""
    out = []
    for fam, trigger in (("corner", "corner"), ("patch", "patch_r3_c5")):
        for frac in (0.25, 0.5, 1.0):
            for dur in DURATIONS:
                out.append({"family": fam, "label": f"{fam} {int(frac * 8)}/8 {dur}", "duration": dur,
                            "attack": "backdoor_win", "trigger": trigger, "poison_frac": frac})
    for frac in (0.5, 1.0):
        for dur in DURATIONS:
            out.append({"family": "flip", "label": f"flip {int(frac * 8)}/8 {dur}", "duration": dur,
                        "attack": "flip_win", "poison_frac": frac})
    for z in ("max", "half"):
        for dur in DURATIONS:
            out.append({"family": "alie", "label": f"ALIE z {z} {dur}", "duration": dur, "attack": "alie_win",
                        "alie": z})
    for scale in (2.0, 4.6):
        for dur in ("short", "long"):
            out.append({"family": "signflip", "label": f"SignFlip {scale:g} {dur}", "duration": dur,
                        "attack": "sign_flip_win", "sign_flip_scale": scale})
    return out


CONFIGS = _configs()


def alie_z(kind: str, n_attackers: int, n: int = 16) -> float | str:
    """'max' (the library's largest factor) or half of it, as a number."""
    if kind == "max":
        return "max"
    from krum.primitives.attacks.alie import ALIEAttack
    return 0.5 * float(ALIEAttack.max_z(torch.zeros(n - n_attackers, 1), n_attackers))


def _window(rng: np.random.Generator, duration: str) -> tuple[int, int]:
    if duration == "persistent":
        return int(rng.integers(2, 21)), T - 1
    onset = int(rng.integers(4, 41)) if rng.random() < 0.3 else int(rng.integers(42, 301))
    return onset, min(onset + (SHORT if duration == "short" else LONG) - 1, T - 1)


def _branch_points(rng: np.random.Generator, family: str, window: tuple[int, int]) -> list[int]:
    if family == "none":
        return sorted(int(v) for v in rng.choice(np.arange(10, T - 50, 10), 4, replace=False))
    onset, end = window
    pts = [t for t in (onset, onset + 10, onset + 30) if t < T - 1]
    if onset >= 50:
        pts.append(int(rng.integers(10, onset - 19)))
    elif end + 20 <= T - 60:
        pts.append(int(rng.integers(end + 20, T - 59)))
    return sorted(set(pts))


def setups() -> pd.DataFrame:
    """One row per setup: attack, seed, window, attackers, branch points, split, part."""
    rows = []
    groups = [(None, N_NONE)] + [(c, N_SEEDS) for c in CONFIGS]
    for ci, (c, n) in enumerate(groups):
        for k in range(n):
            i = len(rows)
            rng = np.random.default_rng(190_000 + i)
            fam = "none" if c is None else c["family"]
            dur = "none" if c is None else c["duration"]
            window = (0, 0) if c is None else _window(rng, dur)
            n_att = int(rng.choice(ATTACKERS.get(fam, (1, 3, 5))))
            row = {"setup": i, "seed": SEED0 + i, "family": fam, "config": "no attack" if c is None else c["label"],
                   "duration": dur, "persistent": dur == "persistent", "attack": "none" if c is None else c["attack"],
                   "trigger": "corner" if c is None else c.get("trigger", "corner"),
                   "poison_frac": 1.0 if c is None else c.get("poison_frac", 1.0),
                   "alie_z": "max" if c is None else (alie_z(c["alie"], n_att) if "alie" in c else "max"),
                   "sign_flip_scale": 1.0 if c is None else c.get("sign_flip_scale", 1.0),
                   "n_attackers": n_att, "target": int(rng.choice(R.XP5_TARGETS)),
                   "flip_source": int(rng.choice(R.XP5_FLIP_SOURCES)),
                   "onset": window[0] if c is not None else -1, "end": window[1] if c is not None else -1}
            row["branch_points"] = " ".join(map(str, _branch_points(rng, fam, window)))
            row["split"] = {0: "test", 1: "val"}.get(k % N_SEEDS, "train")
            row["part"] = 1 + (ci + k) % 2
            rows.append(row)
    return pd.DataFrame(rows)


def smoke_setups() -> pd.DataFrame:
    """One train setup per family, shrunk to 40 steps (K = 8): exercises every attack, trunk and branch path."""
    s = setups()
    s = s[s.split == "train"].groupby("family").head(1).copy()
    s["onset"] = np.where(s.family == "none", -1, 5)
    s["end"] = np.where(s.family == "none", -1, np.where(s.persistent, 39, 20))
    s["branch_points"] = np.where(s.family == "none", "8 16 24 30", "5 10 20 30")
    s["part"] = [1, 2] * 3
    return s.reset_index(drop=True)


def run_cost(bps: list[int], n_steps: int = T) -> float:
    """Run-equivalents of one job: the trunk + each branch from its step to the end."""
    return 1 + sum((n_steps - t) / n_steps for t in bps)


def jobs_of(s: pd.DataFrame, n_steps: int = T) -> pd.DataFrame:
    rows = []
    for r in s.itertuples():
        bps = [int(v) for v in r.branch_points.split()]
        for trunk in (0, 1):
            rows.append({"job": f"s{r.setup:03d}_{'on' if trunk else 'off'}", "setup": r.setup, "trunk": trunk,
                         "part": r.part, "n_branches": len(bps), "cost": run_cost(bps, n_steps)})
    return pd.DataFrame(rows)


def config(r, trunk: int, n_steps: int = T, device: str | None = None) -> RunConfig:
    over = {"block_len": 1, "n_blocks": n_steps, **({"device": device} if device else {})}
    z = r["alie_z"]
    return RunConfig(defense="Krum", seed=int(r["seed"]), schedule="on" if trunk else "off", attack=r["attack"],
                     window=(int(r["onset"]), int(r["end"])) if r["family"] != "none" else (0, 0),
                     trigger=r["trigger"], poison_frac=float(r["poison_frac"]), flip_source=int(r["flip_source"]),
                     target=int(r["target"]), sign_flip_scale=float(r["sign_flip_scale"]),
                     alie_z=z if z == "max" else float(z), n_attackers=int(r["n_attackers"]), **R.xp5_params(over))


# ----------------------------------------------------------------------------- engine
def snapshot(sim, prev_val: float) -> dict:
    """Everything that determines the rest of a run: weights, round, every RNG stream, the signal tracker."""
    fg = sim.corrupt_kwargs.get("flip_gen")
    return {"params": sim._model.parameters.detach().clone(), "round": sim._current_round,
            "loaders": [ld.generator.get_state() for ld in sim._worker_loaders],
            "perm": sim._perm_gen.get_state(), "noise": sim._noise_gen.get_state(),
            "flip": None if fg is None else fg.get_state(), "tracker": copy.deepcopy(sim.tracker),
            "cpu_rng": torch.get_rng_state(),
            "cuda_rng": torch.cuda.get_rng_state_all() if torch.cuda.is_available() else None,
            "schedule": list(sim.schedule), "prev_val": prev_val}


def restore(sim, st: dict) -> float:
    with torch.no_grad():
        sim._model.parameters.copy_(st["params"])
    sim._current_round = st["round"]
    for ld, g in zip(sim._worker_loaders, st["loaders"]):
        ld.generator.set_state(g)
    sim._perm_gen.set_state(st["perm"])
    sim._noise_gen.set_state(st["noise"])
    if st["flip"] is not None:
        sim.corrupt_kwargs["flip_gen"].set_state(st["flip"])
    sim.tracker = copy.deepcopy(st["tracker"])
    torch.set_rng_state(st["cpu_rng"])
    if st["cuda_rng"] is not None:
        torch.cuda.set_rng_state_all(st["cuda_rng"])
    sim.schedule[:] = st["schedule"]
    sim._pending = None
    return st["prev_val"]


def step_row(sim, cfg: RunConfig, s: int, w: int, prev_val: float) -> tuple[dict, float]:
    """One SGD step: gather (signals of step s) -> W_s -> apply -> outcomes. Returns the row and the new val acc."""
    x = sim.gather()
    sim.schedule[s] = int(w)
    sim.apply()
    out = _outcomes(sim, cfg)
    row = {"step": s, "W": int(w), **{c: x[c] for c in SIGNALS}, "x_val_acc_pre": prev_val,
           **{k: out.get(k, math.nan) for k in OUTCOMES}, "u_active": int(sim.attack_spec.active(s))}
    return row, out["x_val_acc"]


def simulate_job(cfg: RunConfig, trunk: int, bps: list[int], k: int) -> tuple[pd.DataFrame, dict]:
    """The trunk (W = trunk at every step) and one branch per t in bps (W = 1 - trunk on [t, t + k))."""
    sim = build(cfg)
    n = cfg.n_blocks
    init = _outcomes(sim, cfg)
    rows = [{"traj": "trunk", "t_branch": -1, "step": -1, "W": -1, **{c: math.nan for c in SIGNALS},
             "x_val_acc_pre": math.nan, **{k_: init.get(k_, math.nan) for k_ in OUTCOMES}, "u_active": 0}]
    prev = init["x_val_acc"]
    snaps = {}
    for s in range(n):
        if s in bps:
            snaps[s] = snapshot(sim, prev)
        row, prev = step_row(sim, cfg, s, trunk, prev)
        rows.append({"traj": "trunk", "t_branch": -1, **row})
    trunk_x = {r["step"]: [r[c] for c in SIGNALS] for r in rows if r["step"] in snaps}
    info = {"branches_ok": 0, "restore_mismatch": [], "errors": []}
    for t in bps:
        try:
            prev = restore(sim, snaps.pop(t))
            for s in range(t, n):
                row, prev = step_row(sim, cfg, s, 1 - trunk if s < t + k else trunk, prev)
                if s == t and not np.array_equal(np.array([row[c] for c in SIGNALS]), np.array(trunk_x[t]),
                                                 equal_nan=True):
                    info["restore_mismatch"].append(t)  # step t's signals precede W_t: must equal the trunk's
                rows.append({"traj": "branch", "t_branch": t, **row})
            info["branches_ok"] += 1
        except Exception:  # keep the trunk and the other branches; the error is reported in jobs.csv
            rows = [r for r in rows if r["t_branch"] != t]
            info["errors"].append(f"branch {t}: {traceback.format_exc(limit=3)}")
    return pd.DataFrame(rows), info


def run_job(job: dict, setup: dict, out: str, n_steps: int, k: int) -> dict:
    """Worker entry point (one process per job). Never raises: errors are returned."""
    f = Path(out) / "jobs" / f"{job['job']}.parquet"
    t0 = time.time()
    for attempt in range(3):  # a transient CUDA out-of-memory (GPU busy) gets two more tries, 60 s apart
        res = _run_job_once(job, setup, f, n_steps, k)
        if res["status"] != "failed" or "out of memory" not in res["error"]:
            break
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
        time.sleep(60)
    res["wall_s"] = round(time.time() - t0, 1)
    return res


def _run_job_once(job: dict, setup: dict, f: Path, n_steps: int, k: int) -> dict:
    res = {"job": job["job"], "setup": job["setup"], "trunk": job["trunk"], "status": "done", "wall_s": 0.0,
           "branches_ok": 0, "n_branches": job["n_branches"], "restore_mismatch": "", "error": ""}
    try:
        cfg = config(setup, job["trunk"], n_steps)
        bps = [int(v) for v in setup["branch_points"].split()]
        df, info = simulate_job(cfg, job["trunk"], bps, k)
        df.insert(0, "job", job["job"]); df.insert(1, "setup", job["setup"]); df.insert(2, "trunk", job["trunk"])
        df = df[COLUMNS]
        tmp = f.with_suffix(".tmp")
        df.to_parquet(tmp, index=False)
        tmp.replace(f)
        res.update(branches_ok=info["branches_ok"], restore_mismatch=" ".join(map(str, info["restore_mismatch"])),
                   error=" | ".join(info["errors"]))
        if info["errors"] or info["restore_mismatch"]:
            res["status"] = "partial"
    except Exception:
        res.update(status="failed", error=traceback.format_exc(limit=5))
    return res


# ----------------------------------------------------------------------------- driver
def _last_error(err) -> str:
    lines = [ln for ln in str(err or '').splitlines() if 'Error' in ln or 'Exception' in ln]
    return lines[-1].strip() if lines else str(err or '').strip()[-200:]


def describe(s: pd.DataFrame, jobs: pd.DataFrame) -> None:
    j = jobs.merge(s[["setup", "family", "config"]], on="setup")
    fam = j.groupby("family").agg(setups=("setup", "nunique"), jobs=("job", "size"),
                                  branches=("n_branches", "sum"), run_eq=("cost", "sum"))
    fam.loc["total"] = fam.sum()
    print(fam.round(0).astype(int).to_string())
    print("\nsplits (setups):", s.groupby("split").size().to_dict(), " attackers:", s.n_attackers.value_counts()
          .sort_index().to_dict())
    p = j.groupby("part").agg(setups=("setup", "nunique"), jobs=("job", "size"), branches=("n_branches", "sum"),
                              run_eq=("cost", "sum"))
    p["est_hours"] = p.run_eq / RATE
    print("\nper part (Kaggle session):\n" + p.round(1).to_string())


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--part", type=int, choices=[1, 2], default=1)
    ap.add_argument("--jobs", type=int, default=1)
    ap.add_argument("--out", type=Path, default=None)
    ap.add_argument("--list", action="store_true")
    ap.add_argument("--smoke", action="store_true", help="6 setups (one per family) of 40 steps")
    ap.add_argument("--only", type=int, default=None, help="run only the first N jobs of the part (local checks)")
    ap.add_argument("--budget-hours", type=float, default=11.0,
                    help="stop starting new jobs after this many hours (finished jobs are kept and merged)")
    args = ap.parse_args()
    n_steps, k = (40, 8) if args.smoke else (T, K)
    s = smoke_setups() if args.smoke else setups()
    jobs = jobs_of(s, n_steps)
    describe(s, jobs)
    if args.list:
        return
    out = args.out or ROOT / "results/xp8" / f"part{args.part}{'_smoke' if args.smoke else ''}"
    (out / "jobs").mkdir(parents=True, exist_ok=True)
    s_part = s[s.part == args.part]
    s_part.to_csv(out / "manifest.csv", index=False)
    todo = jobs[jobs.part == args.part].sort_values("cost", ascending=False)  # longest first: better packing
    if args.only:
        todo = todo.head(args.only)
    status_file = out / "jobs.csv"
    old = pd.read_csv(status_file) if status_file.exists() else pd.DataFrame(columns=["job", "status"])
    done_before = set(old[old.status.isin(["done", "partial"])].job) & {p.stem for p in (out / "jobs").glob("*.parquet")}
    results = [r for r in old.to_dict("records") if r["job"] in done_before]
    pending = [j for j in todo.to_dict("records") if j["job"] not in done_before]
    by_setup = {r["setup"]: r for r in s_part.to_dict("records")}
    print(f"\npart {args.part}: {len(todo)} jobs, {len(done_before & set(todo.job))} already done, "
          f"{len(pending)} to run, {args.jobs} parallel, budget {args.budget_hours} h", flush=True)
    t0, stopped = time.time(), False
    with ProcessPoolExecutor(max_workers=args.jobs, mp_context=get_context("spawn")) as pool:
        running = set()
        while pending or running:
            while pending and len(running) < 2 * args.jobs and not stopped:
                if time.time() - t0 > args.budget_hours * 3600:
                    stopped = True
                    print(f"== budget of {args.budget_hours} h reached: no new jobs ({len(pending)} left)", flush=True)
                    break
                j = pending.pop(0)
                running.add(pool.submit(run_job, j, by_setup[j["setup"]], str(out), n_steps, k))
            if stopped:
                pending = []
            if not running:
                break
            finished, running = wait(running, return_when=FIRST_COMPLETED)
            for fut in finished:
                try:
                    r = fut.result()
                except Exception:  # the worker process itself died (e.g. out of memory)
                    r = {"job": "?", "status": "failed", "wall_s": 0.0, "branches_ok": 0, "n_branches": 0,
                         "error": traceback.format_exc(limit=3)}
                results.append(r)
                pd.DataFrame(results).to_csv(status_file, index=False)
                print(f"[{len(results)}/{len(todo)}] {r['job']} {r['status']} {r['wall_s']:.0f}s "
                      f"branches {r['branches_ok']}/{r['n_branches']} (elapsed {(time.time() - t0) / 60:.0f} min)"
                      + (f"  ERROR {_last_error(r['error'])}"
                         if r["status"] != "done" else ""), flush=True)
    st = pd.DataFrame(results, columns=["job", "setup", "trunk", "status", "wall_s", "branches_ok",
                                        "n_branches", "restore_mismatch", "error"])
    files = [out / "jobs" / f"{j}.parquet" for j in st[st.status.isin(["done", "partial"])].job]
    merged = (pd.concat([pd.read_parquet(f) for f in files], ignore_index=True) if files
              else pd.DataFrame(columns=COLUMNS))  # nothing finished: still write the file (the zip step expects it)
    merged.to_parquet(out / "all_blocks.parquet", index=False)
    counts = {k: int(v) for k, v in st.status.value_counts().items()}
    print(f"== part {args.part}: {counts}; missing {len(set(todo.job) - set(st.job))}; "
          f"wrote {out / 'all_blocks.parquet'} ({len(files)} jobs)", flush=True)
    (out / "summary.json").write_text(json.dumps({"status": counts, "jobs_planned": len(todo),
                                                  "minutes": round((time.time() - t0) / 60, 1)}, indent=1))


if __name__ == "__main__":
    main()
__CPC_DP_EOF__
cat > tests/test_xp8.py <<'__CPC_DP_EOF__'
"""xp8: plan invariants, the gather/apply split, save/resume (bit-exact), branch semantics, a full job end to end."""

import sys
from dataclasses import replace
from pathlib import Path

import numpy as np
import pandas as pd
import pytest
import torch

HERE = Path(__file__).resolve().parent.parent
sys.path.insert(0, str(HERE / "xp8" if (HERE / "xp8").is_dir() else HERE))  # local: CPC_DP/xp8/; Kaggle: flat
import xp8 as X  # noqa: E402
from poison_testbed.runner import build  # noqa: E402

N = 30  # steps in the small runs below


def _setup(family: str, **over) -> dict:
    s = X.setups()
    r = s[s.family == family].iloc[0].to_dict()
    r.update(onset=4, end=20 if family != "none" else -1, **over)
    return r


# ----------------------------------------------------------------------------- plan
def test_plan():
    s = X.setups()
    assert len(s) == 264 and len(X.CONFIGS) == 34 and s.seed.is_unique
    assert s.seed.min() == X.SEED0 and s.seed.max() < X.SEED0 + 1000  # xp5-xp7 seeds are 30k-70k
    per = s.groupby(["config", "split"]).size().unstack(fill_value=0)
    assert (per.loc[per.index != "no attack", "test"] == 1).all() and (per.loc[per.index != "no attack", "val"] == 1).all()
    assert (per.loc[per.index != "no attack", "train"] == 4).all()
    assert s.groupby("config").part.nunique().min() == 2  # every configuration in both sessions
    assert s.groupby("part").size().to_dict() == {1: 132, 2: 132}
    assert not ((s.family == "signflip") & s.persistent).any()
    assert set(s[s.family == "alie"].n_attackers) <= {3, 5} and set(s[s.family == "signflip"].n_attackers) <= {1, 3}
    half = s[(s.family == "alie") & s.config.str.contains("half")].alie_z
    assert all(isinstance(z, float) and z > 0 for z in half)
    for r in s.itertuples():
        bps = [int(v) for v in r.branch_points.split()]
        assert bps == sorted(set(bps)) and 0 <= bps[0] and bps[-1] < X.T - 1 and len(bps) >= 3
        if r.family != "none":
            assert r.onset in bps and 0 < r.onset <= r.end <= X.T - 1
            if r.persistent:
                assert r.end == X.T - 1
    j = X.jobs_of(s)
    assert len(j) == 528 and j.job.is_unique


# ----------------------------------------------------------------------------- testbed
def test_gather_apply_equals_step():
    cfg = X.config(_setup("corner"), 0, N)
    a, b = build(cfg), build(cfg)
    for t in range(N):
        xa = a.step()
        xb = b.gather()
        b.apply()
        assert xa == xb
    assert torch.equal(a._model.parameters, b._model.parameters)
    with pytest.raises(RuntimeError):
        b.apply()


def test_n_attackers():
    for n_att in (1, 5):
        cfg = X.config(_setup("corner", n_attackers=n_att), 0, N)
        sim = build(cfg)
        assert sim.n_byz == n_att and sim.f == 3
        calls = []
        spec = sim.attack_spec
        sim.attack_spec = replace(spec, corrupt=lambda x, y, **kw: (calls.append(1), spec.corrupt(x, y, **kw))[1])
        for _ in range(5):  # onset 4: steps 0-3 clean, step 4 attacked
            sim.step()
        assert len(calls) == n_att


# ----------------------------------------------------------------------------- save / resume
@pytest.mark.parametrize("family", ["flip", "alie", "patch", "signflip"])
def test_resume_is_bit_exact(family):
    """k = 0: a branch is the trunk resumed from a snapshot; it must reproduce the trunk exactly."""
    r = _setup(family)
    df, info = X.simulate_job(X.config(r, 1, N), 1, [3, 11], 0)
    trunk = df[df.traj == "trunk"].set_index("step")
    for t in (3, 11):
        br = df[df.t_branch == t].set_index("step")
        assert list(br.index) == list(range(t, N))
        cols = X.SIGNALS + ["x_val_acc_pre", "W", "u_active"] + X.OUTCOMES
        assert np.array_equal(br[cols].to_numpy(float), trunk.loc[t:, cols].to_numpy(float), equal_nan=True)
    assert info["restore_mismatch"] == [] and info["branches_ok"] == 2 and not info["errors"]


def test_branch_semantics():
    """Off trunk, branch at 6 with k = 5: W = 1 on [6, 11), 0 after; step 6's signals equal the trunk's (they
    precede W_6) but its outcomes differ (W_6 changed the update); the branch differs from the trunk afterwards."""
    r = _setup("patch", n_attackers=5, poison_frac=1.0)
    df, info = X.simulate_job(X.config(r, 0, N), 0, [6], 5)
    trunk = df[df.traj == "trunk"].set_index("step")
    br = df[df.t_branch == 6].set_index("step")
    assert (trunk.loc[0:, "W"] == 0).all()
    assert list(br.W) == [1] * 5 + [0] * (N - 11)
    assert np.array_equal(br.loc[6, X.SIGNALS].to_numpy(float), trunk.loc[6, X.SIGNALS].to_numpy(float))
    assert br.loc[6, "x_val_acc_pre"] == trunk.loc[6, "x_val_acc_pre"]
    assert br.loc[6, "y_clean_loss"] != trunk.loc[6, "y_clean_loss"]
    assert not np.allclose(br.loc[7, X.SIGNALS].to_numpy(float), trunk.loc[7, X.SIGNALS].to_numpy(float))
    assert info["restore_mismatch"] == []
    # x_val_acc_pre(7) is measured after step 6, which differs between trunk and branch: it must differ too
    assert br.loc[7, "x_val_acc_pre"] != trunk.loc[7, "x_val_acc_pre"]


def test_run_job_end_to_end(tmp_path):
    s = X.smoke_setups()
    (tmp_path / "jobs").mkdir()
    for setup in s.to_dict("records")[:2]:
        bps = [int(v) for v in setup["branch_points"].split()]
        for trunk in (0, 1):
            job = {"job": f"s{setup['setup']:03d}_{trunk}", "setup": setup["setup"], "trunk": trunk,
                   "n_branches": len(bps)}
            res = X.run_job(job, setup, str(tmp_path), 40, 8)
            assert res["status"] == "done", res["error"]
            df = pd.read_parquet(tmp_path / "jobs" / f"{job['job']}.parquet")
            assert list(df.columns) == X.COLUMNS
            assert (df.traj == "trunk").sum() == 41
            for t in bps:
                assert (df.t_branch == t).sum() == 40 - t
            body = df[df.step >= 0]
            assert body[X.SIGNALS].notna().all().all() and body.x_val_acc_pre.notna().all()
            assert np.isfinite(body[X.SIGNALS].to_numpy(float)).all()
__CPC_DP_EOF__
cat > learn8.py <<'__CPC_DP_EOF__'
"""xp8 learning: WHEN to switch Krum on, learned from the paired branches. Models A and B, offline test.

    ../.venv/Scripts/python xp8/learn8.py                # A and B, 3 seeds each -> results/xp8/learn/{A,B}/
    ../.venv/Scripts/python xp8/learn8.py --smoke        # few setups, few epochs (pipeline check)

Data: results/xp8/part*/all_blocks.parquet + manifest.csv (trunks Krum off / on and the branches of every setup).

Inputs at step t (what a defender sees before choosing W_t; outcomes never enter):
    the 25 gradient signals of step t + validation accuracy before step t   (signed log, normalised on the train
    trunks, clipped to +-10), W_{t-1}, t / T.
Utility of a step: u = clean acc - LAMBDA * targeted attack success (backdoor / flip; 0 for ALIE, SignFlip, none).
Gain of defending at a branch point t, from a trunk in state s (s = 0 off, 1 on):
    G_t = U(Krum on over [t, t+K), then s) - U(Krum off over [t, t+K), then s),   U = mean of u over steps t..T-1.

Model A (direct gain): a GRU reads the input rows; its head at row t predicts G_t. Trained on the measured G_t of
    the train branch points (MSE), early stopping on the val branch points.
Model B (outcome model, Causal CPC): CPC + InfoMax pretraining of the encoder on the train trunks; then a decoder
    predicts [clean acc, attack success] at every future step under an on/off plan; trained on every train
    trajectory (trunks + branches; factual MSE), early stopping on val. G_hat_t = U_hat(plan on) - U_hat(plan off).
Decision rule (both): defend at step t iff G_hat_t > 0.

Splits by setup (manifest 'split'): per configuration seeds 2-5 train, seed 1 val, seed 0 test.
Per model and seed: weights, normalisation, config, training history, val / test predictions. The seed with the
lowest val regret is the model used for the offline test tables and the live test (live8.py).
"""

from __future__ import annotations

import argparse
import json
import math
import sys
import time
from dataclasses import asdict, dataclass
from pathlib import Path

import numpy as np
import pandas as pd
import torch
from torch import nn

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent if HERE.name == "xp8" else HERE  # local: CPC_DP/xp8/; Kaggle: files flat in $WORK
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(HERE))
import xp8 as X  # noqa: E402
from cpc import train as CT  # noqa: E402  (stage 1: CPC + InfoMax pretraining)
from cpc.model import CausalCPC  # noqa: E402

T, K = X.T, X.K
LAMBDA = 1.0
INPUTS = X.SIGNALS + ["x_val_acc_pre"]
N_IN = len(INPUTS) + 2  # + W_{t-1}, t / T
TARGETED = ("backdoor_win", "flip_win")
CLIP = 10.0
SCALE = 10.0  # model A predicts SCALE * G (gains are ~0.01-0.7)
SEEDS = (0, 1, 2)
RES = ROOT / "results" / "xp8"


def signed_log(x: np.ndarray) -> np.ndarray:
    return np.sign(x) * np.log1p(np.abs(x))


def moment(fam: str, onset: int, end: int, t: int) -> str:
    if fam == "none":
        return "no attack"
    for d, name in ((0, "onset"), (10, "onset+10"), (30, "onset+30")):
        if t == onset + d:
            return name
    return "during" if onset <= t <= end else ("before" if t < onset else "after")


# ============================================================================= data
@dataclass
class Bank:
    """Every trajectory as full arrays. A branch = its trunk's rows before t + its own rows from t."""
    x: np.ndarray       # (N, n, F) inputs, signed log (not normalised)
    W: np.ndarray       # (N, n) defense per step
    y: np.ndarray       # (N, n, 2) [clean acc, targeted attack success]
    meta: pd.DataFrame  # one row per trajectory (index = position in the arrays)
    labels: pd.DataFrame  # one row per branch point: traj (its trunk), branch, t, trunk, gain, setup info

    @property
    def n(self) -> int:
        return self.x.shape[1]


SETUP_COLS = ["seed", "split", "family", "config", "duration", "n_attackers", "onset", "end", "attack"]


def read_parts(res: Path) -> tuple[pd.DataFrame, pd.DataFrame]:
    cols = ["setup", "trunk", "t_branch", "step", "W", *INPUTS, "y_clean_acc", "y_atk"]
    parts = sorted(p for p in res.glob("part*") if (p / "all_blocks.parquet").exists() and "smoke" not in p.name)
    if not parts:
        raise FileNotFoundError(f"no xp8 part in {res}")
    df = pd.concat([pd.read_parquet(p / "all_blocks.parquet", columns=cols) for p in parts], ignore_index=True)
    man = pd.concat([pd.read_csv(p / "manifest.csv") for p in parts], ignore_index=True).drop_duplicates("setup")
    return df, man


def build_bank(df: pd.DataFrame, man: pd.DataFrame) -> Bank:
    man = man.set_index("setup")
    df = df[df.step >= 0].sort_values(["setup", "trunk", "t_branch", "step"], kind="stable")
    n = int(df.step.max()) + 1
    xs, ws, ys, meta, labels = [], [], [], [], []

    def arrays(rows: pd.DataFrame, targeted: bool):
        x = signed_log(rows[INPUTS].to_numpy(np.float64)).astype(np.float32)
        atk = rows.y_atk.fillna(0.0).to_numpy(np.float32) if targeted else np.zeros(len(rows), np.float32)
        return x, rows.W.to_numpy(np.float32), np.stack([rows.y_clean_acc.to_numpy(np.float32), atk], -1)

    for (setup, trunk), g in df.groupby(["setup", "trunk"], sort=True):
        r = man.loc[setup]
        targeted = r.attack in TARGETED
        tr = g[g.t_branch == -1]
        if list(tr.step) != list(range(n)):
            raise ValueError(f"setup {setup} trunk {trunk}: steps are not 0..{n - 1}")
        tx, tw, ty = arrays(tr, targeted)
        if not (tw == trunk).all():
            raise ValueError(f"setup {setup} trunk {trunk}: W is not constant")
        ti = len(meta)
        xs.append(tx); ws.append(tw); ys.append(ty)
        meta.append({"setup": setup, "trunk": trunk, "t_branch": -1})
        u_tr = ty[:, 0] - LAMBDA * ty[:, 1]
        for t, b in g[g.t_branch >= 0].groupby("t_branch"):
            t = int(t)
            if list(b.step) != list(range(t, n)):
                raise ValueError(f"setup {setup} trunk {trunk} branch {t}: steps are not {t}..{n - 1}")
            bx, bw, by = arrays(b, targeted)
            x, w, y = tx.copy(), tw.copy(), ty.copy()
            x[t:], w[t:], y[t:] = bx, bw, by
            bi = len(meta)
            xs.append(x); ws.append(w); ys.append(y)
            meta.append({"setup": setup, "trunk": trunk, "t_branch": t})
            u_b = y[:, 0] - LAMBDA * y[:, 1]
            sign = 1.0 if trunk == 0 else -1.0  # + = defended path minus undefended path
            labels.append({"traj": ti, "branch": bi, "setup": setup, "trunk": trunk, "t": t,
                           "gain": float(sign * (u_b[t:].mean() - u_tr[t:].mean())),
                           "moment": moment(r.family, int(r.onset), int(r.end), t)})
    meta = pd.DataFrame(meta).join(man[SETUP_COLS], on="setup")
    labels = pd.DataFrame(labels).join(man[SETUP_COLS], on="setup")
    return Bank(np.stack(xs), np.stack(ws), np.stack(ys), meta, labels)


def smoke_subset(df: pd.DataFrame, man: pd.DataFrame, per: int = 1) -> tuple[pd.DataFrame, pd.DataFrame]:
    """A few setups per (family, split): the smallest real dataset that exercises every code path."""
    keep = man.groupby(["family", "split"]).head(per).setup
    return df[df.setup.isin(keep)], man[man.setup.isin(keep)]


@dataclass
class Norm:
    mean: np.ndarray
    std: np.ndarray

    @classmethod
    def fit(cls, x: np.ndarray) -> "Norm":
        f = x.reshape(-1, x.shape[-1]).astype(np.float64)
        m, s = np.nanmean(f, 0), np.nanstd(f, 0)
        s[~(s > 1e-6)] = 1.0
        return cls(m.astype(np.float32), s.astype(np.float32))

    def _z(self, x: np.ndarray) -> np.ndarray:
        return np.clip(np.nan_to_num((x - self.mean) / self.std, nan=0.0, posinf=CLIP, neginf=-CLIP), -CLIP, CLIP)

    def enc(self, x: np.ndarray, W: np.ndarray) -> np.ndarray:
        """x (..., n, F) signed-log inputs, W (..., n) -> encoder rows (..., n, F + 2): [z, W_{t-1}, t / T]."""
        n = x.shape[-2]
        wp = np.concatenate([np.zeros_like(W[..., :1]), W[..., :-1]], -1)
        t = np.broadcast_to(np.arange(n, dtype=np.float32) / T, W.shape)
        return np.concatenate([self._z(x), wp[..., None], t[..., None]], -1).astype(np.float32)

    def row(self, x_t: np.ndarray, w_prev: float, t: int) -> np.ndarray:
        """One encoder row from one step's signed-log inputs (live use). Same values as enc()[..., t, :]."""
        return np.concatenate([self._z(x_t), [w_prev, t / T]]).astype(np.float32)

    def save(self, f: Path) -> None:
        np.savez(f, mean=self.mean, std=self.std)

    @classmethod
    def load(cls, f: Path) -> "Norm":
        d = np.load(f)
        return cls(d["mean"], d["std"])


# ============================================================================= models
class GainGRU(nn.Module):
    """Model A: input rows -> GRU -> SCALE * G_t at every row (row t has seen the signals of steps 0..t)."""

    def __init__(self, in_dim: int = N_IN, hidden: int = 64, dropout: float = 0.1):
        super().__init__()
        self.local = nn.Sequential(nn.Linear(in_dim, hidden), nn.SELU())
        self.gru = nn.GRU(hidden, hidden, batch_first=True)
        self.head = nn.Sequential(nn.Dropout(dropout), nn.Linear(hidden, hidden), nn.SELU(), nn.Linear(hidden, 1))

    def forward(self, enc: torch.Tensor, h: torch.Tensor | None = None) -> tuple[torch.Tensor, torch.Tensor]:
        c, h = self.gru(self.local(enc), h)
        return self.head(c)[..., 0], h


def plan_gain(model: CausalCPC, h0: torch.Tensor, w_prev0: torch.Tensor, t: torch.Tensor, s: torch.Tensor,
              n: int) -> torch.Tensor:
    """Model B: G_hat = U_hat(on over [t, t+K) then s) - U_hat(off over [t, t+K) then s), U over steps t..n-1.

    h0 (L, H) encoder state at row t; w_prev0 (L,) = W_{t-1}; t, s (L,) long. Returns (L,)."""
    S = n - int(t.min())
    j = torch.arange(S, device=h0.device)
    steps = t[:, None] + j[None]
    valid = (steps < n).float()
    tt = steps.clamp(max=n - 1).float() / T
    first = j[None] < K
    out = []
    for on in (1.0, 0.0):
        plan = torch.where(first, torch.full_like(tt, on), s[:, None].float().expand_as(tt))
        w_prev = torch.cat([w_prev0[:, None].float(), plan[:, :-1]], 1)
        y, _ = model.decode(h0, w_prev, plan, tt)
        u = y[..., 0] - LAMBDA * y[..., 1]
        out.append((u * valid).sum(1) / valid.sum(1))
    return out[0] - out[1]


def decode_cuts(model: CausalCPC, c: torch.Tensor, W: torch.Tensor, cuts: torch.Tensor):
    """Factual predictions from row `cut` (per trajectory) for steps cut..n-1 under the trajectory's own W.

    c (B, n, H), W (B, n), cuts (B, C) long. Returns y (B, C, S, 2), valid (B, C, S), idx (B, C, S)."""
    B, n = W.shape
    S = n - int(cuts.min())
    raw = cuts[..., None] + torch.arange(S, device=W.device)
    valid, idx = raw < n, raw.clamp(max=n - 1)
    wp = torch.cat([torch.zeros_like(W[:, :1]), W[:, :-1]], 1)
    bi = torch.arange(B, device=W.device)[:, None, None]
    h0 = c[torch.arange(B, device=W.device)[:, None], cuts]
    C = cuts.shape[1]
    y, _ = model.decode(h0.reshape(B * C, -1), wp[bi, idx].reshape(B * C, S), W[bi, idx].reshape(B * C, S),
                        (idx.float() / T).reshape(B * C, S))
    return y.reshape(B, C, S, -1), valid, idx


# ============================================================================= training
@dataclass
class HP:
    hidden: int = 64
    lr: float = 1e-3
    wd: float = 1e-2
    batch: int = 32
    dropout: float = 0.1
    a_epochs: int = 400
    a_patience: int = 40
    pre_epochs: int = 300     # B stage 1 (CPC + InfoMax)
    pre_patience: int = 30
    b_lr: float = 5e-4
    b_epochs: int = 150       # B stage 2 (decoder)
    b_patience: int = 20
    b_cuts: int = 8           # random cuts per trajectory per batch (+ the setup's branch points)


def _label_tensors(bank: Bank, norm: Norm, split: str):
    L = bank.labels[bank.labels.split == split]
    trajs = sorted(L.traj.unique())
    pos = {t: i for i, t in enumerate(trajs)}
    enc = torch.tensor(norm.enc(bank.x[trajs], bank.W[trajs]))
    G = torch.full((len(trajs), bank.n), float("nan"))
    for r in L.itertuples():
        G[pos[r.traj], r.t] = r.gain * SCALE
    return enc, G


def _masked_mse(pred: torch.Tensor, target: torch.Tensor) -> torch.Tensor:
    m = ~torch.isnan(target)
    return ((pred - target.nan_to_num()) ** 2)[m].mean()


def train_A(bank: Bank, norm: Norm, seed: int, hp: HP, device, log=print) -> tuple[GainGRU, dict]:
    torch.manual_seed(seed)
    gen = torch.Generator().manual_seed(seed)
    tr_enc, tr_G = _label_tensors(bank, norm, "train")
    va_enc, va_G = _label_tensors(bank, norm, "val")
    va_enc, va_G = va_enc.to(device), va_G.to(device)
    model = GainGRU(N_IN, hp.hidden, hp.dropout).to(device)
    opt = torch.optim.AdamW(model.parameters(), lr=hp.lr, weight_decay=hp.wd)
    best, best_state, patience, hist = math.inf, None, 0, []
    for epoch in range(hp.a_epochs):
        model.train()
        losses = []
        for rows in torch.randperm(len(tr_enc), generator=gen).split(hp.batch):
            loss = _masked_mse(model(tr_enc[rows].to(device))[0], tr_G[rows].to(device))
            opt.zero_grad()
            loss.backward()
            nn.utils.clip_grad_norm_(model.parameters(), 1.0)
            opt.step()
            losses.append(loss.item())
        model.eval()
        with torch.no_grad():
            v = float(_masked_mse(model(va_enc)[0], va_G))
        hist.append({"epoch": epoch, "train_mse": float(np.mean(losses)), "val_mse": v})
        if v < best - 1e-6:
            best, patience = v, 0
            best_state = {k: t.detach().clone() for k, t in model.state_dict().items()}
        else:
            patience += 1
        if epoch % 20 == 0 or patience >= hp.a_patience:
            log(f"  A seed {seed} epoch {epoch}: train {hist[-1]['train_mse']:.4f} val {v:.4f} (best {best:.4f})")
        if patience >= hp.a_patience:
            break
    model.load_state_dict(best_state)
    return model.eval(), {"epochs": hist, "best_val_mse": best}


class _Seqs:
    """Duck-typed view for cpc.train.pretrain: .enc (N, n, F) and .seed (N,)."""

    def __init__(self, enc: torch.Tensor, seed: torch.Tensor):
        self.enc, self.seed = enc, seed

    def __len__(self) -> int:
        return len(self.enc)


def _traj_tensors(bank: Bank, norm: Norm, idx: np.ndarray):
    enc = torch.tensor(norm.enc(bank.x[idx], bank.W[idx]))
    return enc, torch.tensor(bank.W[idx]), torch.tensor(bank.y[idx])


def _branch_points(bank: Bank, idx: np.ndarray, width: int = 4) -> torch.Tensor:
    """(len(idx), width): the branch points of each trajectory's setup (padded by repetition)."""
    bps = bank.labels.groupby("setup").t.apply(lambda v: sorted(set(v))).to_dict()
    out = []
    for s in bank.meta.setup.to_numpy()[idx]:
        p = bps.get(s, [0]) or [0]
        out.append((p * width)[:width])
    return torch.tensor(out, dtype=torch.long)


def _factual_mse(model: CausalCPC, enc, W, Y, cuts, device) -> tuple[torch.Tensor, torch.Tensor]:
    c = model.encode(enc.to(device))[1]
    W, Y = W.to(device), Y.to(device)
    y, valid, idx = decode_cuts(model, c, W, cuts.to(device))
    B = len(W)
    Yt = Y[torch.arange(B, device=device)[:, None, None], idx]
    m = valid[..., None].float()
    return (((y - Yt) ** 2) * m).sum(), m.sum() * y.shape[-1]


def train_B(bank: Bank, norm: Norm, seed: int, hp: HP, device, log=print) -> tuple[CausalCPC, dict]:
    torch.manual_seed(seed)
    gen = torch.Generator().manual_seed(seed + 1)
    meta = bank.meta
    model = CausalCPC(N_IN, hp.hidden, tau=20, feedback=False, n_out=2).to(device)
    # stage 1: CPC + InfoMax on the trunks (same-seed trajectories are never negatives of each other)
    seqs = {}
    for split in ("train", "val"):
        idx = meta.index[(meta.split == split) & (meta.t_branch == -1)].to_numpy()
        seqs[split] = _Seqs(_traj_tensors(bank, norm, idx)[0], torch.tensor(meta.seed.to_numpy()[idx]))
    cfg = CT.Config(hidden=hp.hidden, pretrain=True, infomax=True, pre_epochs=hp.pre_epochs,
                    pre_patience=hp.pre_patience, lr=hp.b_lr, batch=hp.batch, seed=seed)
    h1 = CT.pretrain(model, seqs["train"], seqs["val"], cfg, device, log=lambda m: log(f"  B seed {seed}{m}"))
    # stage 2: decoder on every trajectory (trunks + branches), factual MSE on [clean acc, attack success]
    tr = meta.index[meta.split == "train"].to_numpy()
    va = meta.index[meta.split == "val"].to_numpy()
    tr_enc, tr_W, tr_Y = _traj_tensors(bank, norm, tr)
    va_enc, va_W, va_Y = _traj_tensors(bank, norm, va)
    tr_bp, va_bp = _branch_points(bank, tr), _branch_points(bank, va)
    n = bank.n
    va_cuts = torch.cat([va_bp, torch.arange(0, n - 1, max(1, n // 10)).expand(len(va), -1)], 1)
    opt = torch.optim.AdamW([{"params": model.encoder_params(), "lr": hp.b_lr * 0.5},
                             {"params": model.decoder_params(), "lr": hp.b_lr}], weight_decay=hp.wd)
    best, best_state, patience, hist = math.inf, None, 0, []
    for epoch in range(hp.b_epochs):
        model.train()
        losses = []
        for rows in torch.randperm(len(tr), generator=gen).split(hp.batch):
            cuts = torch.cat([tr_bp[rows], torch.randint(0, n - 1, (len(rows), hp.b_cuts), generator=gen)], 1)
            num, den = _factual_mse(model, tr_enc[rows], tr_W[rows], tr_Y[rows], cuts, device)
            loss = num / den
            opt.zero_grad()
            loss.backward()
            nn.utils.clip_grad_norm_(model.parameters(), 1.0)
            opt.step()
            losses.append(loss.item())
        model.eval()
        num = den = 0.0
        with torch.no_grad():
            for rows in torch.arange(len(va)).split(hp.batch):
                a, b = _factual_mse(model, va_enc[rows], va_W[rows], va_Y[rows], va_cuts[rows], device)
                num, den = num + float(a), den + float(b)
        v = num / den
        hist.append({"epoch": epoch, "train_mse": float(np.mean(losses)), "val_mse": v})
        if v < best - 1e-7:
            best, patience = v, 0
            best_state = {k: t.detach().clone() for k, t in model.state_dict().items()}
        else:
            patience += 1
        if epoch % 5 == 0 or patience >= hp.b_patience:
            log(f"  B seed {seed} stage 2 epoch {epoch}: train {hist[-1]['train_mse']:.5f} val {v:.5f} "
                f"(best {best:.5f})")
        if patience >= hp.b_patience:
            break
    model.load_state_dict(best_state)
    return model.eval(), {"stage1": h1, "stage2": hist, "best_val_mse": best}


# ============================================================================= prediction
@torch.no_grad()
def predict(kind: str, model: nn.Module, bank: Bank, norm: Norm, labels: pd.DataFrame, device,
            chunk: int = 32) -> np.ndarray:
    """G_hat at each labelled branch point (from its trunk's history, the trunk's state as s)."""
    pred = np.full(len(labels), np.nan)
    L = labels.reset_index(drop=True)
    for trajs in np.array_split(np.array(sorted(L.traj.unique())), max(1, math.ceil(L.traj.nunique() / chunk))):
        enc = torch.tensor(norm.enc(bank.x[trajs], bank.W[trajs])).to(device)
        pos = {t: i for i, t in enumerate(trajs)}
        sel = L.index[L.traj.isin(trajs)].to_numpy()
        rows = torch.tensor([pos[t] for t in L.traj.to_numpy()[sel]], device=device)
        ts = torch.tensor(L.t.to_numpy()[sel], device=device)
        if kind == "A":
            pred[sel] = (model(enc)[0][rows, ts] / SCALE).cpu().numpy()
        else:
            c = model.encode(enc)[1]
            Wt = torch.tensor(bank.W[trajs], device=device)
            w_prev0 = torch.where(ts > 0, Wt[rows, (ts - 1).clamp(min=0)], torch.zeros_like(ts, dtype=Wt.dtype))
            s = torch.tensor(L.trunk.to_numpy()[sel], device=device)
            pred[sel] = plan_gain(model, c[rows, ts], w_prev0, ts, s, bank.n).cpu().numpy()
    return pred


class Controller:
    """Live use: feed one step at a time (raw signals in INPUTS order), get G_hat_t, then report the chosen W_t."""

    def __init__(self, folder: Path, device, n_steps: int = T):
        self.kind, self.model, self.norm, self.meta = load_model(folder, device)
        self.device, self.n = device, n_steps
        self.h, self.w_prev, self.t = None, 0.0, 0

    @torch.no_grad()
    def gain(self, x_raw: np.ndarray) -> float:
        row = torch.tensor(self.norm.row(signed_log(np.asarray(x_raw, np.float64)).astype(np.float32),
                                         self.w_prev, self.t), device=self.device)[None, None]
        if self.kind == "A":
            out, self.h = self.model(row, self.h)
            return float(out[0, 0]) / SCALE
        z = self.model.local(row)
        c, self.h = self.model.ar(z, self.h)
        d = self.device
        return float(plan_gain(self.model, c[:, 0], torch.tensor([self.w_prev], device=d),
                               torch.tensor([self.t], device=d), torch.tensor([int(self.w_prev)], device=d),
                               self.n)[0])

    def update(self, w: int) -> None:
        self.w_prev, self.t = float(w), self.t + 1


# ============================================================================= evaluation
def decisions(L: pd.DataFrame) -> pd.DataFrame:
    d = L.copy()
    d["defend"] = d.pred > 0
    d["right"] = d.defend == (d.gain > 0)
    d["value"] = np.where(d.defend, d.gain, 0.0)  # gain obtained relative to not defending
    d["oracle"] = d.gain.clip(lower=0.0)
    d["regret"] = d.oracle - d.value
    return d


def summarise(d: pd.DataFrame, by: list[str] | None = None) -> pd.DataFrame:
    def one(x):
        c = np.corrcoef(x.pred, x.gain)[0, 1] if len(x) > 2 and x.pred.std() > 0 and x.gain.std() > 0 else np.nan
        return pd.Series({"n": len(x), "right_decisions": x.right.mean(), "model": x.value.mean(),
                          "always_on": x.gain.mean(), "always_off": 0.0, "oracle": x.oracle.mean(),
                          "regret": x.regret.mean(), "defend_rate": x.defend.mean(),
                          "true_defend_rate": (x.gain > 0).mean(), "corr": c, "mae": (x.pred - x.gain).abs().mean()})
    if not by:
        return one(d).to_frame().T
    return d.groupby(by).apply(one, include_groups=False)


# ============================================================================= save / load
def save_model(folder: Path, kind: str, model: nn.Module, norm: Norm, seed: int, hp: HP, hist: dict) -> None:
    folder.mkdir(parents=True, exist_ok=True)
    torch.save(model.state_dict(), folder / "model.pt")
    norm.save(folder / "norm.npz")
    (folder / "config.json").write_text(json.dumps({
        "kind": kind, "seed": seed, "hp": asdict(hp), "inputs": INPUTS, "in_dim": N_IN, "T": T, "K": K,
        "lambda": LAMBDA, "scale": SCALE, "rule": "defend at step t iff G_hat_t > 0"}, indent=1))
    (folder / "history.json").write_text(json.dumps(hist, indent=1))


def load_model(folder: Path, device):
    meta = json.loads((folder / "config.json").read_text())
    hp = HP(**meta["hp"])
    if meta["kind"] == "A":
        model = GainGRU(meta["in_dim"], hp.hidden, hp.dropout)
    else:
        model = CausalCPC(meta["in_dim"], hp.hidden, tau=20, feedback=False, n_out=2)
    model.load_state_dict(torch.load(folder / "model.pt", map_location=device))
    return meta["kind"], model.to(device).eval(), Norm.load(folder / "norm.npz"), meta


# ============================================================================= driver
def run(kind: str, bank: Bank, norm: Norm, out: Path, seeds, hp: HP, device, log=print) -> dict:
    rows = []
    for seed in seeds:
        t0 = time.time()
        log(f"== {kind} seed {seed}")
        model, hist = (train_A if kind == "A" else train_B)(bank, norm, seed, hp, device, log)
        folder = out / kind / f"seed{seed}"
        save_model(folder, kind, model, norm, seed, hp, hist)
        res = {"seed": seed, "best_val_mse": hist["best_val_mse"], "train_minutes": round((time.time() - t0) / 60, 1)}
        for split in ("val", "test"):
            L = bank.labels[bank.labels.split == split].copy()
            L["pred"] = predict(kind, model, bank, norm, L, device)
            d = decisions(L)
            d.to_csv(folder / f"pred_{split}.csv", index=False)
            s = summarise(d).iloc[0]
            res.update({f"{split}_{k}": float(s[k]) for k in ("regret", "right_decisions", "model", "corr")})
        rows.append(res)
        log(f"   {kind} seed {seed}: val regret {res['val_regret']:.4f} right {res['val_right_decisions']:.3f} | "
            f"test regret {res['test_regret']:.4f} right {res['test_right_decisions']:.3f} "
            f"({res['train_minutes']} min)")
    seeds_df = pd.DataFrame(rows)
    seeds_df.to_csv(out / kind / "seeds.csv", index=False)
    best = int(seeds_df.sort_values(["val_regret", "best_val_mse"]).iloc[0].seed)
    (out / kind / "best.json").write_text(json.dumps({"best_seed": best, "chosen_by": "lowest val regret",
                                                      "folder": f"seed{best}"}, indent=1))
    d = pd.read_csv(out / kind / f"seed{best}" / "pred_test.csv")
    test = out / kind / "test"
    test.mkdir(exist_ok=True)
    d.to_csv(test / "branch_points.csv", index=False)
    summarise(d).to_csv(test / "overall.csv", index=False)
    for by in (["family"], ["family", "moment"], ["config"], ["trunk"], ["family", "n_attackers"]):
        summarise(d, by).round(4).to_csv(test / f"by_{'_'.join(by)}.csv")
    log(f"== {kind}: best seed {best}\n{summarise(d, ['family']).round(3).to_string()}")
    return {"kind": kind, "best_seed": best, **summarise(d).iloc[0].to_dict()}


def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--res", type=Path, default=RES, help="folder with part1/, part2/")
    ap.add_argument("--out", type=Path, default=None)
    ap.add_argument("--models", nargs="+", default=["A", "B"], choices=["A", "B"])
    ap.add_argument("--seeds", type=int, nargs="+", default=list(SEEDS))
    ap.add_argument("--smoke", action="store_true", help="1 setup per (family, split), few epochs")
    args = ap.parse_args()
    out = args.out or args.res / ("learn_smoke" if args.smoke else "learn")
    out.mkdir(parents=True, exist_ok=True)
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    t0 = time.time()
    df, man = read_parts(args.res)
    hp = HP()
    seeds = args.seeds
    if args.smoke:
        df, man = smoke_subset(df, man)
        hp = HP(a_epochs=3, a_patience=2, pre_epochs=2, pre_patience=1, b_epochs=2, b_patience=1)
        seeds = seeds[:2]
    bank = build_bank(df, man)
    del df
    m = bank.meta
    norm = Norm.fit(bank.x[m.index[(m.split == "train") & (m.t_branch == -1)].to_numpy()])
    print(f"bank: {len(m)} trajectories x {bank.n} steps, {len(bank.labels)} branch points "
          f"{bank.labels.split.value_counts().to_dict()}, device {device} ({time.time() - t0:.0f} s)", flush=True)
    bank.labels.to_csv(out / "branch_points_all.csv", index=False)
    log = lambda s: print(s, flush=True)  # noqa: E731
    summary = [run(kind, bank, norm, out, seeds, hp, device, log) for kind in args.models]
    pd.DataFrame(summary).to_csv(out / "offline_test.csv", index=False)
    print(pd.DataFrame(summary).round(4).to_string(), f"\n== learn done in {(time.time() - t0) / 60:.1f} min",
          flush=True)


if __name__ == "__main__":
    main()
__CPC_DP_EOF__
cat > live8.py <<'__CPC_DP_EOF__'
"""xp8 live test: the chosen seed of model A and of model B decides Krum at every step of new runs (test setups).

    ../.venv/Scripts/python xp8/live8.py --jobs 4        # -> results/xp8/learn/{A,B}/live/, learn/live_compare.*
    ../.venv/Scripts/python xp8/live8.py --smoke         # 6 test setups x 40 steps (pipeline check)

Each test setup (seed 0 of each attack configuration + the no-attack test setups) is run again from scratch with
the model in charge. At step t: the 16 gradients arrive, the signals are computed (before aggregation), the model
gives G_hat_t, W_t = 1 iff G_hat_t > 0, then aggregation and update. Same seed as the xp8 trunks, so "Krum always
off" and "Krum always on" are the trunks themselves (no extra runs).
Check: until the model first defends, a live run must reproduce the off trunk exactly ('prefix_ok').
Utility of a run: mean over all steps of u = clean acc - LAMBDA * targeted attack success.

Output per model (learn/<A|B>/live/): runs/*.parquet, trajectories.parquet, summary.csv (one row per setup),
by_family.csv, overview.png, plots/<setup>.png (clean accuracy, attack success, W and G_hat vs off / on).
Top level (learn/): live_compare.csv, live_compare.png.
"""

from __future__ import annotations

import argparse
import json
import math
import sys
import time
import traceback
from concurrent.futures import FIRST_COMPLETED, ProcessPoolExecutor, wait
from multiprocessing import get_context
from pathlib import Path

import matplotlib

matplotlib.use("Agg")
import matplotlib.pyplot as plt  # noqa: E402
import numpy as np  # noqa: E402
import pandas as pd  # noqa: E402
import torch  # noqa: E402

HERE = Path(__file__).resolve().parent
ROOT = HERE.parent if HERE.name == "xp8" else HERE
sys.path.insert(0, str(ROOT))
sys.path.insert(0, str(HERE))
import learn8 as L  # noqa: E402
import xp8 as X  # noqa: E402
from poison_testbed.runner import _outcomes, build  # noqa: E402

# fixed identity colours (validated default categorical order): off, on, A, B
COLOR = {"off": "#2a78d6", "on": "#eb6834", "A": "#1baf7a", "B": "#eda100"}
LABEL = {"off": "Krum always off", "on": "Krum always on", "A": "model A (direct gain)", "B": "model B (outcome CPC)"}
INK, INK2, GRID, SHADE = "#0b0b0b", "#52514e", "#e4e3df", "#efeeea"


# ============================================================================= one live run
def _live_once(setup: dict, model_dir: str, n_steps: int, f: Path) -> dict:
    device = torch.device("cuda" if torch.cuda.is_available() else "cpu")
    ctrl = L.Controller(Path(model_dir), device, n_steps)
    cfg = X.config(setup, 0, n_steps)  # schedule placeholder: every W_t is set online below
    sim = build(cfg)
    prev = _outcomes(sim, cfg)["x_val_acc"]
    rows = []
    for s in range(n_steps):
        x = sim.gather()  # signals of step s, before aggregation
        g = ctrl.gain([x[c] for c in X.SIGNALS] + [prev])
        w = int(g > 0)
        sim.schedule[s] = w
        sim.apply()
        out = _outcomes(sim, cfg)
        rows.append({"step": s, "W": w, "g_hat": g, **{c: x[c] for c in X.SIGNALS}, "x_val_acc_pre": prev,
                     **{k: out.get(k, math.nan) for k in X.OUTCOMES}, "u_active": int(sim.attack_spec.active(s))})
        ctrl.update(w)
        prev = out["x_val_acc"]
    df = pd.DataFrame(rows)
    df.insert(0, "setup", int(setup["setup"]))
    df.insert(1, "model", ctrl.kind)
    tmp = f.with_suffix(".tmp")
    df.to_parquet(tmp, index=False)
    tmp.replace(f)
    return {"status": "done", "error": ""}


def live_job(kind: str, setup: dict, model_dir: str, n_steps: int, out: str) -> dict:
    """Worker entry point (one process per run). Never raises. A CUDA out-of-memory gets two more tries."""
    f = Path(out) / f"s{int(setup['setup']):03d}.parquet"
    t0 = time.time()
    res = {}
    for attempt in range(3):
        try:
            res = _live_once(setup, model_dir, n_steps, f)
        except Exception:
            res = {"status": "failed", "error": traceback.format_exc(limit=5)}
        if res["status"] != "failed" or "out of memory" not in res["error"]:
            break
        if torch.cuda.is_available():
            torch.cuda.empty_cache()
        time.sleep(60)
    return {"model": kind, "setup": int(setup["setup"]), **res, "wall_s": round(time.time() - t0, 1)}


# ============================================================================= summaries
def _u(df: pd.DataFrame, targeted: bool) -> np.ndarray:
    atk = df.y_atk.fillna(0.0).to_numpy() if targeted else np.zeros(len(df))
    return df.y_clean_acc.to_numpy() - L.LAMBDA * atk


def trunks(res: Path, setups: list[int], n_steps: int) -> pd.DataFrame:
    cols = ["setup", "trunk", "t_branch", "step", "W", *L.INPUTS, *X.OUTCOMES]
    parts = sorted(p for p in res.glob("part*") if (p / "all_blocks.parquet").exists() and "smoke" not in p.name)
    df = pd.concat([pd.read_parquet(p / "all_blocks.parquet", columns=cols, filters=[("t_branch", "==", -1)])
                    for p in parts], ignore_index=True)
    return df[df.setup.isin(setups) & (df.step >= 0) & (df.step < n_steps)].sort_values(["setup", "trunk", "step"])


def summarise(live: pd.DataFrame, tr: pd.DataFrame, man: pd.DataFrame) -> pd.DataFrame:
    rows = []
    mi = man.set_index("setup")
    for (kind, setup), g in live.groupby(["model", "setup"]):
        r = mi.loc[setup]
        targeted = r.attack in L.TARGETED
        g = g.sort_values("step")
        off = tr[(tr.setup == setup) & (tr.trunk == 0)]
        on = tr[(tr.setup == setup) & (tr.trunk == 1)]
        first = int(np.argmax(g.W.to_numpy() == 1)) if (g.W == 1).any() else len(g) - 1
        a = g[L.INPUTS].iloc[:first + 1].to_numpy(float)
        b = off[L.INPUTS].iloc[:first + 1].to_numpy(float)
        att = (g.step >= r.onset) & (g.step <= r.end) if r.family != "none" else pd.Series(False, index=g.index)
        row = {"model": kind, "setup": setup, "family": r.family, "config": r.config, "n_attackers": r.n_attackers,
               "onset": r.onset, "end": r.end,
               "U_model": _u(g, targeted).mean(), "U_off": _u(off, targeted).mean(), "U_on": _u(on, targeted).mean(),
               "final_acc_model": g.y_clean_acc.iloc[-1], "final_acc_off": off.y_clean_acc.iloc[-1],
               "final_acc_on": on.y_clean_acc.iloc[-1],
               "defend_rate": g.W.mean(), "defend_rate_in_attack": g.W[att].mean() if att.any() else np.nan,
               "defend_rate_outside": g.W[~att].mean() if (~att).any() else np.nan,
               "switches": int((g.W.diff().abs() > 0).sum()),
               "first_defense": int(g.step.iloc[first]) if (g.W == 1).any() else -1,
               "prefix_exact": bool(len(a) == len(b) and np.array_equal(a, b, equal_nan=True)),
               "prefix_max_rel_diff": float(np.nanmax(np.abs(a - b) / (np.abs(b) + 1e-12))) if len(a) == len(b)
               else np.inf}
        row["prefix_ok"] = row["prefix_max_rel_diff"] < 1e-4  # exact on the GPU model of the trunks (Kaggle T4)
        if targeted:
            for k, d in (("model", g), ("off", off), ("on", on)):
                row[f"atk_mean_{k}"] = d.y_atk.fillna(0).mean()
        row["best_trunk"] = max(row["U_off"], row["U_on"])
        row["model_minus_best_trunk"] = row["U_model"] - row["best_trunk"]
        rows.append(row)
    return pd.DataFrame(rows)


def by_family(s: pd.DataFrame) -> pd.DataFrame:
    f = s.groupby("family").agg(n=("setup", "size"), U_off=("U_off", "mean"), U_on=("U_on", "mean"),
                                U_model=("U_model", "mean"), defend_rate=("defend_rate", "mean"),
                                defend_in_attack=("defend_rate_in_attack", "mean"),
                                defend_outside=("defend_rate_outside", "mean"), switches=("switches", "mean"),
                                beats_both=("model_minus_best_trunk", lambda v: (v > 0).mean()))
    tot = pd.DataFrame([{"n": len(s), "U_off": s.U_off.mean(), "U_on": s.U_on.mean(), "U_model": s.U_model.mean(),
                         "defend_rate": s.defend_rate.mean(), "defend_in_attack": s.defend_rate_in_attack.mean(),
                         "defend_outside": s.defend_rate_outside.mean(), "switches": s.switches.mean(),
                         "beats_both": (s.model_minus_best_trunk > 0).mean()}], index=["all"])
    return pd.concat([f, tot])


# ============================================================================= plots
def _style(ax):
    ax.grid(axis="y", color=GRID, lw=0.8)
    ax.set_axisbelow(True)
    for sp in ("top", "right"):
        ax.spines[sp].set_visible(False)
    for sp in ("left", "bottom"):
        ax.spines[sp].set_color(INK2)
    ax.tick_params(colors=INK2, labelsize=8)


def plot_setup(kind: str, g: pd.DataFrame, off: pd.DataFrame, on: pd.DataFrame, r, srow: dict, f: Path) -> None:
    targeted = r.attack in L.TARGETED
    fig, axes = plt.subplots(3, 1, figsize=(10, 7.2), sharex=True, gridspec_kw={"height_ratios": [3, 2, 1.6]})
    fig.patch.set_facecolor("#fcfcfb")
    for ax in axes:
        ax.set_facecolor("#fcfcfb")
        _style(ax)
        if r.family != "none" and r.onset <= g.step.max():
            ax.axvspan(r.onset, min(r.end, g.step.max()), color=SHADE, lw=0, zorder=0)
    series = (("off", off), ("on", on), (kind, g))
    for k, d in series:
        axes[0].plot(d.step, d.y_clean_acc, color=COLOR[k], lw=2 if k == kind else 1.4, label=LABEL[k])
    axes[0].set_ylabel("clean accuracy", color=INK2, fontsize=9)
    if targeted:
        for k, d in series:
            axes[1].plot(d.step, d.y_atk.fillna(0), color=COLOR[k], lw=2 if k == kind else 1.4)
        axes[1].set_ylabel("attack success", color=INK2, fontsize=9)
        axes[1].set_ylim(-0.03, 1.03)
    else:
        diff = g.y_clean_acc.to_numpy() - off.y_clean_acc.to_numpy()[:len(g)]
        axes[1].plot(g.step, diff, color=COLOR[kind], lw=2)
        axes[1].axhline(0, color=COLOR["off"], lw=1.4)
        axes[1].set_ylabel("clean acc\nminus always off", color=INK2, fontsize=9)
    ax = axes[2]
    w = np.r_[0, g.W.to_numpy(), 0]
    starts, ends = np.flatnonzero(np.diff(w) == 1), np.flatnonzero(np.diff(w) == -1)
    steps = g.step.to_numpy()
    for a, b in zip(starts, ends):  # Krum on (model's decision): coloured background over each defended stretch
        ax.axvspan(steps[a], steps[b - 1] + 1, color=COLOR[kind], alpha=0.3, lw=0, zorder=0.5)
    ax.plot(g.step, g.g_hat, color=INK, lw=1)
    ax.axhline(0, color=INK2, lw=0.8, ls=":")
    ax.set_ylabel("predicted gain\n(coloured: Krum on)", color=INK2, fontsize=9)
    ax.set_xlabel("SGD step" + ("   (shaded: attack active)" if r.family != "none" else ""), color=INK2, fontsize=9)
    axes[0].legend(loc="lower right", fontsize=8, frameon=False)
    fig.suptitle(f"{r.config}  ·  {r.n_attackers} attacker(s)  ·  setup {r.name}", color=INK, fontsize=11,
                 x=0.06, ha="left")
    fig.text(0.06, 0.935, f"utility  model {srow['U_model']:.3f}  ·  always off {srow['U_off']:.3f}  ·  "
             f"always on {srow['U_on']:.3f}  ·  defended {srow['defend_rate']:.0%} of steps, "
             f"{srow['switches']} switches", color=INK2, fontsize=9)
    fig.tight_layout(rect=(0, 0, 1, 0.93))
    fig.savefig(f, dpi=110)
    plt.close(fig)


def plot_bars(tab: pd.DataFrame, keys: list[str], f: Path, title: str) -> None:
    """Grouped bars: mean run utility per attack family, one bar per policy (fixed colours)."""
    fams = [x for x in tab.index if x != "all"] + ["all"]
    fig, ax = plt.subplots(figsize=(10, 4.2))
    fig.patch.set_facecolor("#fcfcfb")
    ax.set_facecolor("#fcfcfb")
    _style(ax)
    w = 0.8 / len(keys)
    for i, k in enumerate(keys):
        xs = np.arange(len(fams)) + (i - (len(keys) - 1) / 2) * w
        ax.bar(xs, tab.loc[fams, f"U_{k}"], width=w - 0.02, color=COLOR[k], label=LABEL[k])
    ax.set_xticks(np.arange(len(fams)), fams)
    ax.set_ylabel("mean utility of the run\n(clean acc - attack success)", color=INK2, fontsize=9)
    lo = float(np.nanmin(tab[[f"U_{k}" for k in keys]].to_numpy()))
    ax.set_ylim(min(0.0, lo - 0.05), 1.0)
    ax.legend(fontsize=8, frameon=False, ncol=len(keys), loc="upper left")
    ax.set_title(title, color=INK, fontsize=11, loc="left")
    fig.tight_layout()
    fig.savefig(f, dpi=110)
    plt.close(fig)


# ============================================================================= driver
def main() -> None:
    ap = argparse.ArgumentParser(description=__doc__, formatter_class=argparse.RawDescriptionHelpFormatter)
    ap.add_argument("--res", type=Path, default=L.RES, help="folder with part1/, part2/")
    ap.add_argument("--learn", type=Path, default=None, help="learn8.py output (default res/learn[_smoke])")
    ap.add_argument("--models", nargs="+", default=["A", "B"], choices=["A", "B"])
    ap.add_argument("--jobs", type=int, default=1)
    ap.add_argument("--smoke", action="store_true", help="1 test setup per family, 40 steps")
    ap.add_argument("--report-only", action="store_true", help="summaries and plots from existing runs")
    args = ap.parse_args()
    learn = args.learn or args.res / ("learn_smoke" if args.smoke else "learn")
    n_steps = 40 if args.smoke else X.T
    man = pd.concat([pd.read_csv(p / "manifest.csv") for p in sorted(args.res.glob("part[12]"))])
    man = man.drop_duplicates("setup")
    test = man[man.split == "test"]
    if args.smoke:
        test = test.groupby("family").head(1)
    test = test.sort_values("setup")
    t0 = time.time()
    dirs = {}
    for kind in args.models:
        best = json.loads((learn / kind / "best.json").read_text())
        dirs[kind] = learn / kind / best["folder"]
        (learn / kind / "live" / "runs").mkdir(parents=True, exist_ok=True)
    todo = [(k, r) for k in args.models for r in test.to_dict("records")
            if not (learn / k / "live" / "runs" / f"s{int(r['setup']):03d}.parquet").exists()]
    print(f"live: {len(test)} test setups x {args.models} = {len(test) * len(args.models)} runs of {n_steps} steps, "
          f"{len(todo)} to run, {args.jobs} parallel; models {({k: str(v.name) for k, v in dirs.items()})}",
          flush=True)
    status = []
    if todo and not args.report_only:
        with ProcessPoolExecutor(max_workers=args.jobs, mp_context=get_context("spawn")) as pool:
            futs = {pool.submit(live_job, k, r, str(dirs[k]), n_steps, str(learn / k / "live" / "runs"))
                    for k, r in todo}
            done_n = 0
            while futs:
                fin, futs = wait(futs, return_when=FIRST_COMPLETED)
                for fu in fin:
                    try:
                        res = fu.result()
                    except Exception:
                        res = {"model": "?", "setup": -1, "status": "failed", "error": traceback.format_exc(limit=3),
                               "wall_s": 0.0}
                    status.append(res)
                    done_n += 1
                    err = res["error"].strip().splitlines()[-1] if res["status"] != "done" else ""
                    print(f"[{done_n}/{len(todo)}] {res['model']} s{res['setup']:03d} {res['status']} "
                          f"{res['wall_s']:.0f}s (elapsed {(time.time() - t0) / 60:.0f} min) {err}", flush=True)
    tr = trunks(args.res, test.setup.tolist(), n_steps)
    compare = {}
    for kind in args.models:
        live_dir = learn / kind / "live"
        files = sorted((live_dir / "runs").glob("s*.parquet"))
        if not files:
            print(f"== {kind}: no live run finished", flush=True)
            continue
        live = pd.concat([pd.read_parquet(f) for f in files], ignore_index=True)
        live.to_parquet(live_dir / "trajectories.parquet", index=False)
        s = summarise(live, tr, man)
        s.to_csv(live_dir / "summary.csv", index=False)
        fam = by_family(s)
        fam.round(4).to_csv(live_dir / "by_family.csv")
        compare[kind] = fam
        (live_dir / "plots").mkdir(exist_ok=True)
        mi = man.set_index("setup")
        for srow in s.to_dict("records"):
            st = srow["setup"]
            plot_setup(kind, live[live.setup == st].sort_values("step"), tr[(tr.setup == st) & (tr.trunk == 0)],
                       tr[(tr.setup == st) & (tr.trunk == 1)], mi.loc[st], srow,
                       live_dir / "plots" / f"s{st:03d}_{mi.loc[st].config.replace(' ', '_').replace('/', 'of')}.png")
        plot_bars(fam.rename(columns={"U_model": f"U_{kind}"}), ["off", "on", kind], live_dir / "overview.png",
                  f"Live test, model {kind}: mean utility per attack family")
        print(f"== {kind}: {len(s)} live runs; prefix vs off trunk: exact {int(s.prefix_exact.sum())}, "
              f"within 1e-4 {int(s.prefix_ok.sum())}, max rel diff {s.prefix_max_rel_diff.max():.1e}\n"
              f"{fam.round(3).to_string()}", flush=True)
    if compare:
        k0 = next(iter(compare))
        tab = compare[k0][["n", "U_off", "U_on"]].copy()
        for kind, fam in compare.items():
            tab[f"U_{kind}"] = fam.U_model
            tab[f"defend_rate_{kind}"] = fam.defend_rate
            tab[f"beats_both_{kind}"] = fam.beats_both
        tab.round(4).to_csv(learn / "live_compare.csv")
        plot_bars(tab, ["off", "on", *compare], learn / "live_compare.png",
                  "Live test on the test setups: mean utility per attack family")
        print(tab.round(3).to_string(), flush=True)
    if status:
        pd.DataFrame(status).to_csv(learn / "live_status.csv", index=False)
    print(f"== live done in {(time.time() - t0) / 60:.1f} min", flush=True)


if __name__ == "__main__":
    main()
