cat > cpc/evaluate.py <<'__CPC_DP_EOF__'
"""Evaluation shared by CausalCPC and the xp6 OutcomeGRU: factual error by horizon, and Delta_k on onset twins.

Delta_k(H_t) = U(on over blocks [t, t + k), off elsewhere) - U(off), U = y_clean(T) - lam * y_atk(t + tau).
History H_t = the off twin's rows 0..t (blocks -1..t-1), identical in both twins. Row r holds the outcome after
block r - 1, so y_atk(t + tau) is row t + tau (tau blocks after the decision) and y_clean(T) is the last row.
"""

from __future__ import annotations

import numpy as np
import pandas as pd
import torch
from sklearn.metrics import roc_auc_score

from .data import RunData
from . import _GRU  # noqa: F401
import gru_experiment as ge  # noqa: E402


class CPCPredictor:
    name = "cpc"

    def __init__(self, model, device, name: str = "cpc"):
        self.model, self.device, self.name = model.eval(), device, name

    @torch.no_grad()
    def cuts(self, rd: RunData, rows, cuts):
        y, _, valid, idx = self.model.cut_predictions(rd.enc[rows].to(self.device), rd.W[rows].to(self.device),
                                                      rd.t.to(self.device), cuts.to(self.device))
        return y.cpu(), valid.cpu(), idx.cpu()

    @torch.no_grad()
    def plans(self, rd: RunData, i: int, cut: int, plans: torch.Tensor) -> torch.Tensor:
        """(P, n - 1 - cut, 2): predictions for rows cut+1 .. n-1 from run i's history 0..cut, per plan (P, n)."""
        dev, n = self.device, rd.n_rows
        c = self.model.encode(rd.enc[i:i + 1].to(dev))[1]
        P = len(plans)
        w = plans.to(dev)
        y, _ = self.model.decode(c[:, cut].expand(P, -1), w[:, cut:n - 1], w[:, cut + 1:n],
                                 rd.t[cut + 1:n].to(dev).expand(P, -1))
        return y.cpu()


class GRUPredictor:
    """The xp6 OutcomeGRU (gru_experiment), on the same RunData (identical normalisation when built from the
    same training runs)."""

    def __init__(self, model, device, name: str = "gru"):
        self.model, self.device, self.name = model.eval(), device, name

    @torch.no_grad()
    def cuts(self, rd: RunData, rows, cuts):
        dec = rd.d.dec_inputs(rd.d.W)
        y, valid, idx = ge.cut_predictions(self.model, rd.d.enc[rows].to(self.device), dec[rows].to(self.device),
                                           cuts.to(self.device))
        return y.cpu(), valid.cpu(), idx.cpu()

    @torch.no_grad()
    def plans(self, rd: RunData, i: int, cut: int, plans: torch.Tensor) -> torch.Tensor:
        h = self.model.encode(rd.d.enc[i:i + 1].to(self.device))[:, cut]
        dec = rd.d.dec_inputs(plans.numpy(), runs=slice(i, i + 1))[:, cut:].to(self.device)
        return self.model.decode(h.expand(len(plans), -1), dec).cpu()


# ----------------------------------------------------------------------------- factual error
def factual_table(pred, rd: RunData, set_name: str, step: int = 5) -> pd.DataFrame:
    """RMSE by horizon (1, 5, n/5, n/2 blocks and all), per outcome and attack family, under each run's own W."""
    n_dec = rd.n_rows - 1
    cuts = torch.arange(0, n_dec, step)
    hz = ge.horizons(rd.d.n_blocks)
    acc: dict = {}
    for rows in torch.arange(len(rd)).split(16):
        y, valid, idx = pred.cuts(rd, rows, cuts)
        Y = rd.Y[rows][:, 1:][:, idx]
        M = rd.M[rows][:, 1:][:, idx] * valid[None, :, :, None]
        se = ((y - Y) ** 2 * M).numpy()
        m = M.numpy()
        for r, a in zip(range(len(rows)), rd.attack[rows.numpy()]):
            for o, oname in enumerate(ge.Y_COLS):
                for h in ["all", *hz]:
                    sl = slice(None) if h == "all" else slice(h - 1, h)
                    for fam in ("all", a):
                        k = (fam, oname, str(h))
                        s, c = acc.get(k, (0.0, 0.0))
                        acc[k] = (s + se[r, :, sl, o].sum(), c + m[r, :, sl, o].sum())
    out = [{"model": pred.name, "set": set_name, "attack": k[0], "outcome": k[1], "horizon": k[2],
            "rmse": np.sqrt(s / c) if c else np.nan, "n": int(c)} for k, (s, c) in acc.items()]
    return pd.DataFrame(out)


# ----------------------------------------------------------------------------- Delta on onset twins
def score_twins(pred, rd: RunData, manifest: pd.DataFrame, lam: float = 1.0, tau: int = 20) -> pd.DataFrame:
    pos = {r: i for i, r in enumerate(rd.run_ids)}
    n = rd.n_rows
    rows = []
    for seed, g in manifest.groupby("seed"):
        i_off = pos[g[g.plan == "off"].run_id.iloc[0]]
        for t, gt in g[g.plan == "on"].groupby("t"):
            t = int(t)
            plans = [torch.zeros(n)]
            for r in gt.itertuples():
                p = torch.zeros(n)
                p[t + 1:t + 1 + int(r.k)] = 1
                if not torch.equal(p, rd.W[pos[r.run_id]]):
                    raise ValueError(f"plan of {r.run_id} does not match its logged W")
                plans.append(p)
            yhat = pred.plans(rd, i_off, t, torch.stack(plans)).numpy()  # (P, n-1-t, 2)
            ra = min(t + tau, n - 1)
            u_hat = yhat[:, -1, 0] - lam * yhat[:, ra - (t + 1), 1]
            Y_off = rd.Y[i_off].numpy()
            for j, r in enumerate(gt.itertuples(), start=1):
                Y_on = rd.Y[pos[r.run_id]].numpy()
                rows.append({
                    "model": pred.name, "seed": seed, "group": r.group, "attack": r.attack,
                    "poison_frac": r.poison_frac, "trigger": r.trigger, "d": int(r.d), "k": int(r.k), "t": t,
                    "true_delta": (Y_on[-1, 0] - lam * Y_on[ra, 1]) - (Y_off[-1, 0] - lam * Y_off[ra, 1]),
                    "pred_delta": float(u_hat[j] - u_hat[0]),
                    "true_benefit_atk": Y_off[ra, 1] - Y_on[ra, 1], "pred_benefit_atk": float(yhat[0, ra - t - 1, 1] - yhat[j, ra - t - 1, 1]),
                    "true_clean_change": Y_on[-1, 0] - Y_off[-1, 0], "pred_clean_change": float(yhat[j, -1, 0] - yhat[0, -1, 0]),
                })
    return pd.DataFrame(rows)


def delta_metrics(df: pd.DataFrame, by: list[str]) -> pd.DataFrame:
    def one(g: pd.DataFrame) -> pd.Series:
        t, p = g.true_delta.to_numpy(), g.pred_delta.to_numpy()
        pos = t > 0
        both = pos.any() and (~pos).any()
        return pd.Series({
            "n": len(g), "true_mean": t.mean(), "pred_mean": p.mean(),
            "rmse": np.sqrt(np.mean((p - t) ** 2)),
            "corr": np.corrcoef(p, t)[0, 1] if len(g) > 2 and p.std() > 0 and t.std() > 0 else np.nan,
            "slope": np.polyfit(p, t, 1)[0] if len(g) > 2 and p.std() > 0 else np.nan,  # 1 = calibrated
            "sign_acc": np.mean(np.sign(p) == np.sign(t)),
            "auc_true_pos": roc_auc_score(pos, p) if both else np.nan,
            "share_true_pos": pos.mean(),
        })
    return df.groupby(by).apply(one, include_groups=False).reset_index()


# ----------------------------------------------------------------------------- whole-run Delta (xp7, agreed 2026-11-24)
def score_twins_whole(pred, rd: RunData, manifest: pd.DataFrame, lam: float = 1.0) -> pd.DataFrame:
    """Delta(H_t) = U(on over [t, t + k), off elsewhere) - U(off), U = mean over blocks t..T of
    (y_clean - lam * y_atk): every block after the decision counts (the attack coming back after Krum goes off, the
    clean-accuracy dip while Krum is on). Rows t+1 .. n-1 hold the outcomes after blocks t .. T.
    manifest: one 'off' run per 'base' plus its 'on' plans (columns base, plan, t, k, run_id, ...)."""
    pos = {r: i for i, r in enumerate(rd.run_ids)}
    n = rd.n_rows
    out = []
    for base, g in manifest.groupby("base"):
        i_off = pos[g[g.plan == "off"].run_id.iloc[0]]
        Y_off = rd.Y[i_off].numpy()
        for t, gt in g[g.plan == "on"].groupby("t"):
            t = int(t)
            plans = [torch.zeros(n)]
            for r in gt.itertuples():
                p = torch.zeros(n)
                p[t + 1:t + 1 + int(r.k)] = 1
                if not torch.equal(p, rd.W[pos[r.run_id]]):
                    raise ValueError(f"plan of {r.run_id} does not match its logged W")
                plans.append(p)
            yhat = pred.plans(rd, i_off, t, torch.stack(plans)).numpy()  # (P, n-1-t, 2): rows t+1 .. n-1
            u_hat = (yhat[..., 0] - lam * yhat[..., 1]).mean(1)
            c_hat, a_hat = yhat[..., 0].mean(1), yhat[..., 1].mean(1)
            for j, r in enumerate(gt.itertuples(), start=1):
                Y_on = rd.Y[pos[r.run_id]].numpy()
                seg_on, seg_off = Y_on[t + 1:], Y_off[t + 1:]
                out.append({
                    "model": pred.name, "base": base, "seed": r.seed, "split": r.split, "family": r.family,
                    "persistent": r.persistent, "d": int(r.d), "k": int(r.k), "t": t,
                    "true_delta": float((seg_on[:, 0] - lam * seg_on[:, 1]).mean() - (seg_off[:, 0] - lam * seg_off[:, 1]).mean()),
                    "pred_delta": float(u_hat[j] - u_hat[0]),
                    "true_clean": float(seg_on[:, 0].mean() - seg_off[:, 0].mean()), "pred_clean": float(c_hat[j] - c_hat[0]),
                    "true_atk_benefit": float(seg_off[:, 1].mean() - seg_on[:, 1].mean()),
                    "pred_atk_benefit": float(a_hat[0] - a_hat[j]),
                })
    return pd.DataFrame(out)


def best_margin(val: pd.DataFrame) -> float:
    """Margin m maximising the decision value on validation twins: defend iff pred_delta > m."""
    cands = np.unique(np.concatenate([[0.0], val.pred_delta.to_numpy()]))
    vals = [(val.true_delta * (val.pred_delta > m)).mean() for m in cands]
    return float(cands[int(np.argmax(vals))] - 1e-9)


def decision_table(test: pd.DataFrame, margin: float) -> dict:
    """Mean true Delta obtained on test twins (0 = never defend). oracle = defend exactly when Delta > 0."""
    t, p = test.true_delta.to_numpy(), test.pred_delta.to_numpy()
    model = float((t * (p > margin)).mean())
    oracle = float(np.clip(t, 0, None).mean())
    return {"margin": margin, "value_model": model, "value_always": float(t.mean()), "value_oracle": oracle,
            "share_of_oracle": model / oracle if oracle > 0 else np.nan, "defend_rate": float((p > margin).mean()),
            "corr": float(np.corrcoef(p, t)[0, 1]) if p.std() > 0 else np.nan,
            "auc": float(roc_auc_score(t > 0, p)) if 0 < (t > 0).mean() < 1 else np.nan,
            "rmse": float(np.sqrt(np.mean((p - t) ** 2))), "pred_mean": float(p.mean()), "true_mean": float(t.mean())}
__CPC_DP_EOF__
cat > cpc/model.py <<'__CPC_DP_EOF__'
"""Causal CPC (El Bouchattaoui et al., NeurIPS 2024) adapted to 'when to defend'.

Differences from the paper (all deliberate, see notes/01, 02):
  * the history holds no outcome: encoder rows are [X, W, t, init] (Y is an oracle quantity here);
  * the decoder runs to the end of the run (not tau steps), with or without feeding back its own predictions
    (`feedback`; the start value is a learned constant, never a true Y);
  * twins (same seed) are never negatives of each other in the contrastive losses;
  * W is binary (Krum on / off), so the treatment head is one logit.

Decoder step j (target row cut+1+j) reads [W of the previous row, t of the target row (, previous prediction)]:
its hidden state therefore never contains the planned W of its own step, which only the outcome head sees. The
balancing representation br_j is thus a function of the history and the plan BEFORE step j, as in the paper, and
the treatment head predicting W_j from br_j is a valid CLUB critic.
"""

from __future__ import annotations

import torch
import torch.nn.functional as F
from torch import nn
from torch.nn.utils.parametrizations import spectral_norm, weight_norm


def contrastive_mask(seed: torch.Tensor) -> torch.Tensor:
    """(B, B) True where column b must not serve as a negative for row a: another run with the same seed (twin)."""
    same = seed[:, None] == seed[None, :]
    return same & ~torch.eye(len(seed), dtype=torch.bool, device=seed.device)


def info_nce(targets: torch.Tensor, preds: torch.Tensor, mask: torch.Tensor) -> torch.Tensor:
    """InfoNCE: for each row a, the true prediction preds[a] against the other runs' predictions."""
    logits = (targets @ preds.T).masked_fill(mask, float("-inf"))
    return F.cross_entropy(logits, torch.arange(len(targets), device=targets.device))


class CausalCPC(nn.Module):
    def __init__(self, in_dim: int, hidden: int = 64, tau: int = 20, feedback: bool = False, n_out: int = 2):
        super().__init__()
        self.tau, self.feedback, self.n_out = tau, feedback, n_out
        z = hidden
        self.local = nn.Sequential(weight_norm(nn.Linear(in_dim, 3 * z // 2)), nn.SELU(),
                                   weight_norm(nn.Linear(3 * z // 2, z)))  # Z_t = phi1([X, W, t, init])
        self.ar = nn.GRU(z, hidden, batch_first=True)  # C_t
        self.wk = nn.ModuleList([nn.Linear(hidden, z, bias=False) for _ in range(tau)])  # CPC, horizons 1..tau
        self.infomax_map = nn.Linear(hidden, hidden, bias=False)  # C^h -> prediction of C^f
        self.dec = nn.GRU(2 + (n_out if feedback else 0), hidden, batch_first=True)
        self.br = nn.Sequential(weight_norm(nn.Linear(hidden, hidden)), nn.SELU())  # balancing representation
        self.out = nn.Sequential(weight_norm(nn.Linear(hidden + 1, hidden)), nn.SELU(),
                                 weight_norm(nn.Linear(hidden, n_out)))
        self.treat = nn.Sequential(spectral_norm(nn.Linear(hidden, hidden)), nn.SELU(),
                                   spectral_norm(nn.Linear(hidden, 1)))  # CLUB critic q(W_j | br_j)
        self.y0 = nn.Parameter(torch.zeros(n_out))  # learned start value of the fed-back outcome

    # ----------------------------------------------------------------- groups of parameters
    def encoder_params(self):
        return [*self.local.parameters(), *self.ar.parameters()]

    def pretrain_params(self):
        return [*self.encoder_params(), *self.wk.parameters(), *self.infomax_map.parameters()]

    def decoder_params(self):
        return [*self.dec.parameters(), *self.br.parameters(), *self.out.parameters(), self.y0]

    def treat_params(self):
        return list(self.treat.parameters())

    # ----------------------------------------------------------------- encoder
    def encode(self, enc: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        z = self.local(enc)
        c, _ = self.ar(z)
        return z, c  # (B, n, H) each; c[:, i] summarises rows 0..i

    def cpc_loss(self, z: torch.Tensor, c: torch.Tensor, mask: torch.Tensor, times: torch.Tensor) -> torch.Tensor:
        """Mean InfoNCE over the sampled times and horizons j = 1..tau (only where t + j is a row of the run)."""
        n, losses = z.shape[1], []
        for t in times.tolist():
            for j in range(1, self.tau + 1):
                if t + j > n - 1:
                    break
                losses.append(info_nce(z[:, t + j], self.wk[j - 1](c[:, t]), mask))
        return torch.stack(losses).mean()

    def infomax_loss(self, z: torch.Tensor, mask: torch.Tensor, t: int, t0: int) -> torch.Tensor:
        """InfoNCE between the past view rows [0, t0) and the future view rows [t0, t] (each encoded from scratch)."""
        ch = self.ar(z[:, :t0])[0][:, -1]
        cf = self.ar(z[:, t0:t + 1])[0][:, -1]
        return info_nce(cf, self.infomax_map(ch), mask)

    # ----------------------------------------------------------------- decoder
    def decode(self, h0: torch.Tensor, w_prev: torch.Tensor, w_now: torch.Tensor,
               t: torch.Tensor) -> tuple[torch.Tensor, torch.Tensor]:
        """h0 (N, H); w_prev, w_now, t (N, S). Returns outcome predictions (N, S, n_out) in [0, 1], br (N, S, H)."""
        hidden = h0.unsqueeze(0).contiguous()
        if not self.feedback:
            o, _ = self.dec(torch.stack([w_prev, t], -1), hidden)
            br = self.br(o)
            return torch.sigmoid(self.out(torch.cat([br, w_now[..., None]], -1))), br
        y = torch.sigmoid(self.y0).expand(len(h0), -1)
        ys, brs = [], []
        for s in range(w_now.shape[1]):  # autoregressive, no teacher forcing (the paper's decoder)
            x = torch.cat([w_prev[:, s, None], t[:, s, None], y], -1)[:, None]
            o, hidden = self.dec(x, hidden)
            b = self.br(o[:, 0])
            y = torch.sigmoid(self.out(torch.cat([b, w_now[:, s, None]], -1)))
            ys.append(y)
            brs.append(b)
        return torch.stack(ys, 1), torch.stack(brs, 1)

    def cut_predictions(self, enc: torch.Tensor, W: torch.Tensor, t_rows: torch.Tensor, cuts: torch.Tensor,
                        c: torch.Tensor | None = None):
        """Predictions from history rows 0..i for each cut i, for rows i+1 .. n-1, under the schedule W (B, n).

        Returns preds (B, C, S, n_out), br (B, C, S, H), valid (C, S), idx (C, S) with target row = idx + 1.
        Same convention as gru_experiment.cut_predictions."""
        B, n = W.shape
        n_dec = n - 1
        if c is None:
            c = self.encode(enc)[1]
        h = c[:, cuts]  # (B, C, H)
        S = n_dec - int(cuts.min())
        raw = cuts[:, None] + torch.arange(S, device=W.device)[None]
        valid, idx = raw < n_dec, raw.clamp(max=n_dec - 1)
        w_now, w_prev, tt = W[:, 1:][:, idx], W[:, :-1][:, idx], t_rows[1:][idx].expand(B, -1, -1)
        C = len(cuts)
        y, br = self.decode(h.reshape(B * C, -1), w_prev.reshape(B * C, S), w_now.reshape(B * C, S),
                            tt.reshape(B * C, S))
        return y.reshape(B, C, S, -1), br.reshape(B, C, S, -1), valid, idx
__CPC_DP_EOF__
cat > cpc/train.py <<'__CPC_DP_EOF__'
"""Two-stage training (paper §5, Alg. 1-2), on the xp6 OutcomeGRU's runs, splits and loss.

Stage 1 (if cfg.pretrain): encoder pretraining with InfoNCE over horizons 1..tau (+ InfoMax), early stopping on
the validation contrastive loss. Stage 2: decoder to the end of the run, masked MSE on [y_clean_acc, y_atk] (the
paper's Gaussian NLL with fixed sigma is the same objective up to scale), encoder fine-tuned at a lower learning
rate, optional CLUB balancing (treatment head on detached br, SGD; representation minimises CLUB with a weight
rising from 0 to club_alpha). Early stopping on the validation factual MSE (fixed, evenly spaced cuts).
"""

from __future__ import annotations

import json
import math
from dataclasses import asdict, dataclass
from pathlib import Path

import numpy as np
import torch
import torch.nn.functional as F

from .data import RunData
from .model import CausalCPC, contrastive_mask


@dataclass
class Config:
    hidden: int = 64
    tau: int = 20
    pretrain: bool = True    # stage 1 (CPC)
    infomax: bool = True     # + InfoMax in stage 1
    club: bool = False       # CLUB balancing in stage 2
    feedback: bool = False   # decoder fed with its own previous prediction
    a_cpc: float = 1.0
    a_infomax: float = 0.2   # paper configs: alpha_infonce 0.5, alpha_recons 0.1
    cpc_times: int = 4       # sampled times per batch for the CPC loss
    pre_epochs: int = 1000   # paper: max 1000 epochs, patience 100
    pre_patience: int = 100
    epochs: int = 300
    patience: int = 40
    lr: float = 5e-4
    wd: float = 1e-2
    enc_lr_mult: float = 0.5  # encoder learning rate in stage 2, relative (only after pretraining)
    club_alpha: float = 1.0
    club_ramp: int = 50       # epochs to reach ~club_alpha
    lr_treat: float = 1e-2
    batch: int = 32
    cuts: int = 16
    seed: int = 0


# Ablation ladder: A0 = the OutcomeGRU's recipe in the CPC architecture; each rung adds one ingredient.
PRESETS = {
    "A0": dict(pretrain=False, infomax=False, club=False, feedback=False),
    "A1": dict(pretrain=True, infomax=False, club=False, feedback=False),
    "A2": dict(pretrain=True, infomax=True, club=False, feedback=False),
    "A3": dict(pretrain=True, infomax=True, club=True, feedback=False),
    "A4": dict(pretrain=True, infomax=True, club=True, feedback=True),
}


def _stage1_loss(model: CausalCPC, data: RunData, rows: torch.Tensor, cfg: Config, gen: torch.Generator,
                 device) -> torch.Tensor:
    enc = data.enc[rows].to(device)
    mask = contrastive_mask(data.seed[rows].to(device))
    z, c = model.encode(enc)
    n = enc.shape[1]
    times = torch.randint(1, n - 1, (cfg.cpc_times,), generator=gen)
    loss = cfg.a_cpc * model.cpc_loss(z, c, mask, times)
    if cfg.infomax:
        t = int(torch.randint(2, n, (1,), generator=gen))
        t0 = int(torch.randint(1, t, (1,), generator=gen))
        loss = loss + cfg.a_infomax * model.infomax_loss(z, mask, t, t0)
    return loss


def pretrain(model: CausalCPC, tr: RunData, va: RunData, cfg: Config, device, log=print) -> list[dict]:
    opt = torch.optim.AdamW(model.pretrain_params(), lr=cfg.lr, weight_decay=cfg.wd)
    gen = torch.Generator().manual_seed(cfg.seed)
    best, best_state, patience, hist = math.inf, None, 0, []
    for epoch in range(cfg.pre_epochs):
        model.train()
        losses = []
        for rows in torch.randperm(len(tr), generator=gen).split(cfg.batch):
            if len(rows) < 2:
                continue
            loss = _stage1_loss(model, tr, rows, cfg, gen, device)
            opt.zero_grad()
            loss.backward()
            opt.step()
            losses.append(loss.item())
        model.eval()
        with torch.no_grad():  # fixed sampling: a comparable validation loss across epochs
            vgen = torch.Generator().manual_seed(12345)
            v = float(np.mean([_stage1_loss(model, va, rows, cfg, vgen, device).item()
                               for _ in range(4) for rows in torch.arange(len(va)).split(cfg.batch) if len(rows) > 1]))
        hist.append({"epoch": epoch, "train": float(np.mean(losses)), "val": v})
        if v < best - 1e-4:
            best, patience = v, 0
            best_state = {k: t.detach().clone() for k, t in model.state_dict().items()}
        else:
            patience += 1
        if epoch % 10 == 0 or patience >= cfg.pre_patience:
            log(f"  stage 1 epoch {epoch}: train {hist[-1]['train']:.4f} val {v:.4f} (best {best:.4f})")
        if patience >= cfg.pre_patience:
            break
    model.load_state_dict(best_state)
    return hist


def _factual(model: CausalCPC, data: RunData, rows: torch.Tensor, cuts: torch.Tensor, device):
    W = data.W[rows].to(device)
    y, br, valid, idx = model.cut_predictions(data.enc[rows].to(device), W, data.t.to(device), cuts.to(device))
    Y = data.Y[rows][:, 1:].to(device)[:, idx]
    M = data.M[rows][:, 1:].to(device)[:, idx] * valid[None, :, :, None]
    return y, br, valid, idx, W, Y, M


def val_mse(model: CausalCPC, va: RunData, cuts: torch.Tensor, device) -> float:
    model.eval()
    num = den = 0.0
    with torch.no_grad():
        for rows in torch.arange(len(va)).split(16):
            y, _, _, _, _, Y, M = _factual(model, va, rows, cuts, device)
            num += float((((y - Y) ** 2) * M).sum())
            den += float(M.sum())
    return num / den


def fit_decoder(model: CausalCPC, tr: RunData, va: RunData, cfg: Config, device, log=print) -> list[dict]:
    enc_lr = cfg.lr * (cfg.enc_lr_mult if cfg.pretrain else 1.0)
    opt = torch.optim.AdamW([{"params": model.encoder_params(), "lr": enc_lr},
                             {"params": model.decoder_params(), "lr": cfg.lr}], weight_decay=cfg.wd)
    opt_t = torch.optim.SGD(model.treat_params(), lr=cfg.lr_treat, momentum=0.9)
    gen = torch.Generator().manual_seed(cfg.seed + 1)
    n_cuts = tr.n_rows - 1
    va_cuts = torch.arange(0, n_cuts, max(1, n_cuts // 50))
    best, best_state, patience, hist = math.inf, None, 0, []
    for epoch in range(cfg.epochs):
        alpha = cfg.club_alpha * (2 / (1 + math.exp(-10 * epoch / cfg.club_ramp)) - 1) if cfg.club else 0.0
        model.train()
        ly, lc, lt = [], [], []
        for rows in torch.randperm(len(tr), generator=gen).split(cfg.batch):
            cuts = (torch.arange(n_cuts) if n_cuts <= cfg.cuts
                    else torch.randperm(n_cuts, generator=gen)[:cfg.cuts].sort().values)
            y, br, valid, idx, W, Y, M = _factual(model, tr, rows, cuts, device)
            loss_y = (((y - Y) ** 2) * M).sum() / M.sum()
            loss = loss_y
            if cfg.club:
                w_now = W[:, 1:][:, idx]  # planned W of each step (B, C, S)
                v = valid[None].expand_as(w_now)
                w = w_now[v]
                logit = model.treat(br)[..., 0][v]
                perm = torch.randperm(len(w), generator=gen).to(device)
                pos = -F.binary_cross_entropy_with_logits(logit, w, reduction="none")
                neg = -F.binary_cross_entropy_with_logits(logit, w[perm], reduction="none")
                club = (pos - neg).mean()
                loss = loss + alpha * club
                lc.append(club.item())
            opt.zero_grad()
            loss.backward()
            opt.step()
            if cfg.club:  # critic step: treatment head only, on the detached representation
                bce = F.binary_cross_entropy_with_logits(model.treat(br.detach())[..., 0][v], w)
                opt_t.zero_grad()
                bce.backward()
                opt_t.step()
                lt.append(bce.item())
            ly.append(loss_y.item())
        v = val_mse(model, va, va_cuts, device)
        hist.append({"epoch": epoch, "train_mse": float(np.mean(ly)), "val_mse": v, "alpha": alpha,
                     "club": float(np.mean(lc)) if lc else None, "treat_bce": float(np.mean(lt)) if lt else None})
        if v < best - 1e-6:
            best, patience = v, 0
            best_state = {k: t.detach().clone() for k, t in model.state_dict().items()}
        else:
            patience += 1
        if epoch % 10 == 0 or patience >= cfg.patience:
            extra = f" club {hist[-1]['club']:.4f} treat_bce {hist[-1]['treat_bce']:.4f} a {alpha:.2f}" if cfg.club else ""
            log(f"  stage 2 epoch {epoch}: train {hist[-1]['train_mse']:.5f} val {v:.5f} (best {best:.5f}){extra}")
        if patience >= cfg.patience:
            break
    model.load_state_dict(best_state)
    return hist


def train_model(cfg: Config, tr: RunData, va: RunData, device, log=print) -> tuple[CausalCPC, dict]:
    torch.manual_seed(cfg.seed)
    model = CausalCPC(tr.enc.shape[-1], cfg.hidden, cfg.tau, cfg.feedback).to(device)
    hist = {"stage1": pretrain(model, tr, va, cfg, device, log) if cfg.pretrain else []}
    hist["stage2"] = fit_decoder(model, tr, va, cfg, device, log)
    hist["best_val_mse"] = min(h["val_mse"] for h in hist["stage2"])
    return model, hist


def save(folder: Path, model: CausalCPC, cfg: Config, tr: RunData, hist: dict) -> None:
    folder.mkdir(parents=True, exist_ok=True)
    torch.save(model.state_dict(), folder / "cpc.pt")
    np.savez(folder / "norm.npz", x_mean=tr.d.x_mean, x_std=tr.d.x_std)
    (folder / "config.json").write_text(json.dumps({"config": asdict(cfg), "x_cols": tr.x_cols,
                                                    "in_dim": int(tr.enc.shape[-1])}, indent=1))
    (folder / "history.json").write_text(json.dumps(hist, indent=1))


def load(folder: Path, device) -> tuple[CausalCPC, Config]:
    meta = json.loads((folder / "config.json").read_text())
    cfg = Config(**meta["config"])
    model = CausalCPC(meta["in_dim"], cfg.hidden, cfg.tau, cfg.feedback).to(device)
    model.load_state_dict(torch.load(folder / "cpc.pt", map_location=device))
    return model.eval(), cfg
__CPC_DP_EOF__
cat > cpc/xp7data.py <<'__CPC_DP_EOF__'
"""xp7 data for the GRU and CPC models: splits from the xp7 manifests, one dataset per policy level.

- Inputs: the same 80 signals as xp6 (cpc.data.input_columns), passed through a signed log, sign(x) log(1 + |x|),
  before the usual normalisation: SignFlip windows push some signals to ~1e8 (notes/03_xp7_design.md).
- Outcomes [y_clean_acc, y_atk]: y_atk is the targeted attack's success (backdoor / flip). ALIE and SignFlip have no
  targeted outcome (y_atk is NaN in the logs): their harm is entirely in y_clean_acc, so y_atk is set to the
  measured backdoor base rate (y_bd), as in no-attack runs. The utility U = clean - lam * atk then counts their
  damage once, through clean accuracy.
- Policy logs (p_on, decision) are never inputs (input_columns keeps only x_ signals).

Splits (by base setup, identical at every level): train 134, val 22, test 44 setups. Twins: val + test setups only.
Never train on twins.
"""

from __future__ import annotations

from pathlib import Path

import numpy as np
import pandas as pd

from .data import RunData, input_columns

HERE = Path(__file__).resolve().parent.parent
RES = HERE / "results/xp7"
SRC = {p: RES / p for p in ("a", "b", "twins")}
CACHE = RES / "cache"
LEVELS = ["g0", "g2", "g8", "hard"]
PART_OF = {"g0": "a", "g2": "a", "g8": "b", "hard": "b"}
GRADIENT = ("alie_win", "sign_flip_win")


def signed_log(x: np.ndarray) -> np.ndarray:
    return np.sign(x) * np.log1p(np.abs(x))


def prepare(df: pd.DataFrame) -> pd.DataFrame:
    """Signed-log inputs, y_atk for gradient attacks, W as Int64. Idempotent guard via a marker column."""
    if "_prepared" in df:
        return df
    df = df.copy()
    cols = input_columns(df)
    df[cols] = signed_log(df[cols].to_numpy(float))
    grad = df.attack.isin(GRADIENT)
    df.loc[grad, "y_atk"] = df.loc[grad, "y_bd"]
    df["W"] = pd.to_numeric(df.W, errors="coerce").astype("Int64")
    df["_prepared"] = 1
    return df


def _read(part: str) -> pd.DataFrame:
    """One xp7 part, prepared, with its manifest columns; cached in results/xp7/cache (the CSVs are ~190 MB)."""
    CACHE.mkdir(parents=True, exist_ok=True)
    f = CACHE / f"{part}.pkl"
    if f.exists():
        return pd.read_pickle(f)
    df = pd.read_csv(SRC[part] / "all_blocks.csv", dtype={"round_start": "Int64", "W": "Int64"}, low_memory=False)
    man = pd.read_csv(SRC[part] / "manifest.csv")
    keep = [c for c in man.columns if c not in df.columns or c == "run_id"]
    df = prepare(df).merge(man[keep], on="run_id")
    df.to_pickle(f)
    return df


def level_splits(level: str) -> dict[str, pd.DataFrame]:
    """{'train', 'val', 'test'}: the main runs of one policy level."""
    df = _read(PART_OF[level])
    df = df[df.level == level]
    return {s: df[df.split == s] for s in ("train", "val", "test")}


def twins() -> tuple[pd.DataFrame, pd.DataFrame]:
    """(blocks, manifest) of the onset twins (val + test setups)."""
    df = _read("twins")
    return df, pd.read_csv(SRC["twins"] / "manifest.csv")


def level_data(level: str) -> tuple[RunData, RunData, RunData]:
    sp = level_splits(level)
    tr = RunData(sp["train"])
    return tr, RunData(sp["val"], ref=tr), RunData(sp["test"], ref=tr)
__CPC_DP_EOF__
